package com.fromscratch.beta;

import com.fromscratch.FromScratchPlugin;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/** Owner-distributed bootstrap, excluded from the Plugin Hub plugin JAR. No authentication code. */
public final class BetaLauncher
{
	private BetaLauncher() { }

	public static void main(String[] args) throws Exception
	{
		if (args.length == 1 && "--help".equals(args[0]))
		{
			RuneLite.main(new String[]{"--help"});
			return;
		}
		if (args.length != 0)
		{
			throw new IllegalArgumentException("Use the supplied launcher, or --help. Authentication is handled by RuneLite's Jagex Accounts panel.");
		}
		ExternalPluginManager.loadBuiltin(FromScratchPlugin.class);
		RuneLite.main(new String[]{"--developer-mode", "--disable-telemetry"});
	}
}

package com.fromscratch;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;
import net.runelite.api.gameval.ItemID;

/** Local presentation preferences; progression will be stored separately per character. */
@ConfigGroup(FromScratchConfig.GROUP)
public interface FromScratchConfig extends Config
{
	String GROUP = "fromscratch";

	@ConfigItem(
		keyName = "showFoundationHelp",
		name = "Legacy setup preference",
		description = "Retained for configuration compatibility; bank-only setup uses short instructions",
		hidden = true,
		position = 0
	)
	default boolean showFoundationHelp()
	{
		return true;
	}

	@ConfigItem(keyName = "bankVirtualQuantities", name = "Virtual bank quantities",
		description = "Show signed bank progress at bottom-right", position = 1)
	default boolean bankVirtualQuantities() { return true; }

	@ConfigItem(keyName = "lockedBankItems", name = "Dim locked bank items",
		description = "Dim items with zero or negative From Scratch bank balance; keep ordinary quantity labels visible", position = 2)
	default boolean lockedBankItems() { return true; }

	@ConfigItem(keyName = "virtualQuantityColor", name = "Virtual quantity color",
		description = "Color of virtual bank quantities and From Scratch Examine numbers", position = 3)
	default Color virtualQuantityColor() { return new Color(0x1DFF00); }

	@ConfigItem(keyName = "negativeVirtualQuantityColor", name = "Negative Virtual Quantity Color",
		description = "Color of negative virtual quantities and outstanding amounts", position = 4)
	default Color negativeVirtualQuantityColor() { return new Color(0xFF4040); }

	@ConfigItem(keyName = "lockedItemBackgroundColor", name = "Locked Item Background Color",
		description = "Neutral tint behind locked bank counters; independent of quantity text", position = 5)
	default Color lockedItemBackgroundColor() { return new Color(0x333333); }

	@Range(min = 0, max = 100)
	@ConfigItem(keyName = "lockedItemBackgroundOpacity", name = "Locked Item Background Opacity",
		description = "Locked bank tint opacity as a percentage", position = 6)
	default int lockedItemBackgroundOpacity() { return 50; }

	@ConfigItem(keyName = "virtualBankView", name = "Enable Virtual Bank View",
		description = "Show only virtually owned item types in your bank. Disable to view your full bank.", position = 0)
	default boolean virtualBankView() { return true; }

	@ConfigItem(keyName = "developmentItemTrace", name = "Development: bank diagnostics",
		description = "Retained developer DEBUG logging preference", hidden = true, position = 100)
	default boolean developmentItemTrace() { return false; }

	@ConfigItem(keyName = "developmentTraceItemId", name = "Development: traced item ID",
		description = "Retained historical preference; bank-only diagnostics do not log individual holdings", hidden = true, position = 101)
	default int developmentTraceItemId() { return ItemID.WOODEN_SHIELD; }
}

package com.fromscratch;

import com.fromscratch.bank.BankController;
import com.fromscratch.bank.RuneLiteBankSource;
import com.fromscratch.overlay.BankOverlayRegistration;
import com.fromscratch.overlay.BankOverlayState;
import com.fromscratch.bank.BankSidebar;
import com.google.inject.Provides;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Wires lifecycle and supported observations to local snapshot setup. It never
 * sends game actions; storage and UI remain outside the client observation layer.
 */
@Slf4j
@PluginDescriptor(
	name = "From Scratch",
	internalName = "from-scratch",
	configName = FromScratchConfig.GROUP,
	description = "Restart item progression on your existing character with a Virtual Bank and legacy gear buybacks.",
	tags = {"bank", "virtual", "progression", "challenge", "fresh", "start", "legacy", "solo", "friends", "wealth"}
)
public class FromScratchPlugin extends Plugin
{
	@Inject
	private BankSidebar sidebar;

	@Inject
	private FromScratchConfig config;

	@Inject
	private BankController setupController;

	@Inject
	private RuneLiteBankSource observer;

	@Inject
	private ClientThread clientThread;
	@Inject private BankOverlayRegistration bankOverlay;
	@Inject private BankOverlayState bankOverlayState;
	@Inject private com.fromscratch.wealth.PriceService prices;
	@Inject private com.fromscratch.ge.RuneLiteGeSource exchangeObserver;
	@Inject private com.fromscratch.examine.NativeExamine examine;
	@Inject private com.fromscratch.bank.VirtualBankMode virtualBank;
	@Inject private com.fromscratch.playtime.PlaytimeTracker playtime;
	@Inject private net.runelite.api.Client client;
	@Inject private ConfigManager configManager;
	@Inject private net.runelite.client.Notifier notifier;
	@Inject private net.runelite.client.chat.ChatMessageManager chat;
	@Inject private com.fromscratch.persistence.BankRepository repository;

	@Override
	protected void startUp()
	{
		com.fromscratch.persistence.CanonicalStorageGate storage = new com.fromscratch.persistence.CanonicalStorageGate(this::getPluginDirectory, repository);
		bankOverlayState.configure(config);
		sidebar.negativeColor(config.negativeVirtualQuantityColor());
		observer.configure(config.developmentItemTrace());
		bankOverlay.start();
		prices.start();
		// Queue UI work without blocking the client thread. Lifecycle operations
		// share the EDT queue, so rapid enable/disable sequences retain their order.
		clientThread.invokeLater(() ->
		{
			observer.resetSession();exchangeObserver.resetSession();
			virtualBank.setEnabled(config.virtualBankView());
			virtualBank.fullBankSelected(()->SwingUtilities.invokeLater(()->configManager.setConfiguration(FromScratchConfig.GROUP,"virtualBankView",false)));
			setupController.informationActions(this::updateVirtualBank);
			setupController.initialBankView(virtualBank::fullBankForSetup);
			setupController.overdrafts(warnings->{for(com.fromscratch.bank.Overdrafts.Warning warning:warnings){String text=warning.message();chat.queue(net.runelite.client.chat.QueuedMessage.builder().type(net.runelite.api.ChatMessageType.GAMEMESSAGE).runeLiteFormattedMessage(net.runelite.client.util.ColorUtil.wrapWithColorTag("From Scratch: LEGACY ITEMS OVERDRAWN",java.awt.Color.RED)+" "+text).build());try{notifier.notify("From Scratch: LEGACY ITEMS OVERDRAWN. "+text);}catch(RuntimeException ex){log.debug("From Scratch notification delivery failed",ex);}}});
		});
		setupController.start(storage);
		clientThread.invokeLater(()->
		{
			examine.start(setupController::currentRun);
			playtime.start(storage);
			setupController.restoreLifecycle(playtime::beforeRestore,playtime::afterRestore);
			setupController.exportLifecycle(playtime::checkpoint);
		});
		SwingUtilities.invokeLater(() ->
		{
			sidebar.bind(setupController);
			sidebar.show();
		});
		log.debug("From Scratch started");
	}

	@Override
	protected void shutDown()
	{
		bankOverlay.stop();
		setupController.stop();
		prices.stop();
		clientThread.invokeLater(()->{examine.stop();virtualBank.stop();playtime.stop();});
		clientThread.invokeLater(() -> {observer.resetSession();exchangeObserver.resetSession();});
		SwingUtilities.invokeLater(sidebar::hide);
		log.debug("From Scratch stopped");
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		flushExchangeObservations();
		observer.gameTick();
		setupController.tick();
		playtime.tick(setupController.currentRun(),client.getGameState()==GameState.LOGGED_IN,client.getTickCount());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if(state!=GameState.LOGGED_IN&&state!=GameState.LOADING){virtualBank.update(null,false);}
		if(state!=GameState.LOGGED_IN){observer.bagUnavailable();observer.storageUnavailable();}
		examine.clear();
		if(state!=GameState.LOGGED_IN) { playtime.interrupted(); }
		if(state==GameState.LOGGING_IN||state==GameState.HOPPING||state==GameState.CONNECTION_LOST||state==GameState.LOGIN_SCREEN){exchangeObserver.resetSession();}
		// Region loading and a normal world hop do not establish a new host login.
		// The renderer already hides itself outside LOGGED_IN. Clearing a valid
		// projection here could strand it when unchanged state is restored.
		if (state != GameState.LOGGED_IN && state != GameState.LOADING && state != GameState.HOPPING)
		{
			bankOverlayState.clear();
			observer.resetSession();
			setupController.tick();
		}
		else if (state == GameState.LOGGED_IN) { setupController.tick(); }
	}
	@Subscribe public void onMenuOptionClicked(MenuOptionClicked event)
	{
		examine.clicked(event);observer.bagClicked(event);
		if(event.getParam1()==InterfaceID.Bankmain.POTIONSTORE_BUTTON){virtualBank.potionStorageSelected();return;}
		// invokeLater defers reconciliation until core Bank Tags has handled this same click.
		if(event.getMenuOption().startsWith("View tab")||event.getMenuOption().equals("View all items")){virtualBank.nativeTabSelected();}else{virtualBank.viewChanged();}
	}
	@Subscribe public void onBeforeRender(net.runelite.api.events.BeforeRender event) { bankOverlay.beforeRender(); }
	@Subscribe(priority=-1) public void onScriptCallbackEvent(net.runelite.api.events.ScriptCallbackEvent event)
	{String name=event.getEventName();if("bankBuildTab".equals(name)||"bankSearchFilter".equals(name)){virtualBank.script(name,client.getIntStack(),client.getIntStackSize());}}
	@Subscribe(priority=1) public void onScriptPreFired(net.runelite.api.events.ScriptPreFired event)
	{if(event.getScriptId()==net.runelite.api.ScriptID.BANKMAIN_SEARCH_TOGGLE){virtualBank.searchSelected();}}
	@Subscribe(priority=-1) public void onScriptPostFired(net.runelite.api.events.ScriptPostFired event)
	{
		observer.potionScript(event.getScriptId());
		if(event.getScriptId()==net.runelite.api.ScriptID.BANKMAIN_FINISHBUILDING){virtualBank.bankBuilt();virtualBank.title(config.virtualQuantityColor());}
	}
	@Subscribe public void onVarbitChanged(net.runelite.api.events.VarbitChanged event){observer.potionVarp(event.getVarpId());}
	private void updateVirtualBank(com.fromscratch.bank.BankRun run)
	{
		try
		{
			boolean open=client.getGameState()==GameState.LOGGED_IN&&observer.bankOpen();
			if(run==null||!open){virtualBank.update(null,open);return;}
			virtualBank.update(run,true,observer.observe());
		}
		catch(RuntimeException ex){virtualBank.failed(ex);}
	}
	// Core Examine runs at priority 0 and queues its price line first; queue our line afterward.
	@Subscribe(priority=com.fromscratch.examine.NativeExamine.RESPONSE_PRIORITY) public void onChatMessage(ChatMessage event) { examine.response(event);observer.bagMessage(event); }
	@Subscribe public void onPluginChanged(net.runelite.client.events.PluginChanged event)
	{
		if(event.getPlugin() instanceof net.runelite.client.plugins.banktags.BankTagsPlugin)
		{ clientThread.invokeLater(()->{virtualBank.availabilityChanged();updateVirtualBank(setupController.currentRun());}); }
	}

	@Subscribe public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		exchangeObserver.changed(event.getSlot(),event.getOffer());
		// The API event already represents a completed offer update. Queue its value copy
		// immediately; no filesystem work runs here and logout need not wait for another tick.
		flushExchangeObservations();
	}
	private void flushExchangeObservations()
	{
		for(com.fromscratch.ge.GeObservation offer:exchangeObserver.drain()){setupController.exchange(offer);}
		if(exchangeObserver.takeObservationGap()){setupController.exchangeGap();}
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		// Rendering revalidates character identity each frame. A same-character
		// configuration-profile change must not strand its valid projection.
		clientThread.invokeLater(setupController::tick);
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		int id = event.getContainerId();
		observer.storageChanged(id);
		if(id==InventoryID.LOOTING_BAG){observer.bagChanged();}
		if (id == InventoryID.BANK)
		{
			virtualBank.itemsChanged();
			observer.changed();
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN || event.getGroupId() == InterfaceID.BANKPIN_KEYPAD
			|| event.getGroupId() == InterfaceID.BANKPIN_SETTINGS)
		{
			observer.changed();
		}
	}

	@Subscribe(priority=1)
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			if(event.isUnload()) { virtualBank.bankClosed(); observer.bagBankClosed();observer.potionClosed(); }
			observer.changed();
		}
		else if (event.getGroupId() == InterfaceID.BANKPIN_KEYPAD || event.getGroupId() == InterfaceID.BANKPIN_SETTINGS)
		{
			observer.changed();
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (FromScratchConfig.GROUP.equals(event.getGroup()))
		{
			bankOverlayState.configure(config);
			sidebar.negativeColor(config.negativeVirtualQuantityColor());
			observer.configure(config.developmentItemTrace());
			clientThread.invokeLater(()->{virtualBank.setEnabled(config.virtualBankView());updateVirtualBank(setupController.currentRun());virtualBank.title(config.virtualQuantityColor());});
		}
	}

	@Provides
	FromScratchConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(FromScratchConfig.class);
	}
}

package com.fromscratch.bank;

import java.util.UUID;

/** User intent only; no operation operates the game UI. */
public interface BankActions
{
	void startRun(boolean attested);
	default void setupAttested(UUID attempt,boolean value) { }
	default void setupStorageAnswer(UUID attempt,Boolean unlocked) { }
	default void startRun(boolean attested,com.fromscratch.potion.PotionCapture captured,boolean notUnlocked){startRun(attested);}
	void anchor(UUID revision, com.fromscratch.model.ContainerSnapshot reviewedBank, boolean approveReductions);
	void correct(UUID revision, int itemId, long desired);
	void reset(UUID revision);
	void retry();
	default void confirmFreshInstallation() { }
	default void reviewStorage(UUID revision,java.util.Map<Integer,Long> quantities){throw new UnsupportedOperationException("Storage review unavailable");}
	default void correctStorage(UUID revision,int type,long desired){throw new UnsupportedOperationException("Storage correction unavailable");}
	default void exportProgress(net.runelite.client.util.Filepath file,java.util.function.Consumer<String> result){result.accept("Export is unavailable.");}
	default void previewImport(net.runelite.client.util.Filepath file,java.util.function.Consumer<com.fromscratch.persistence.ProgressBackup.Candidate> result,java.util.function.Consumer<String> failure){failure.accept("Import is unavailable.");}
	default void importProgress(com.fromscratch.persistence.ProgressBackup.Candidate candidate,java.util.function.Consumer<String> result){result.accept("Import is unavailable.");}
	default void cancelImport(com.fromscratch.persistence.ProgressBackup.Candidate candidate) { }
	default void previewRecovery(java.util.function.Consumer<com.fromscratch.persistence.ProgressBackup.Candidate> result,java.util.function.Consumer<String> failure){failure.accept("Recovery is unavailable.");}
	default void historyItems(java.util.function.Consumer<java.util.Map<Integer,String>> callback) { callback.accept(java.util.Collections.emptyMap()); }
	default void itemHistory(int itemId,BankHistory.Cursor cursor,java.util.function.Consumer<ItemHistory.Page> callback)
	{ callback.accept(new ItemHistory.Page(java.util.Collections.emptyList(),null,"No recorded item history.")); }
	default void buySelected(UUID revision,String catalogId,int itemId,UUID purchaseId){throw new UnsupportedOperationException("Selected buybacks unavailable");}
	default void buyback(UUID revision,String catalogId,UUID purchaseId){throw new UnsupportedOperationException("Buybacks unavailable");}
	default void buyEmptyStorage(UUID revision,String catalogId,UUID purchaseId,com.fromscratch.buyback.EmptyStorageConfirmation confirmation){throw new UnsupportedOperationException("Storage buybacks unavailable");}
	default void pouchPreview(java.util.function.Consumer<com.fromscratch.pouch.PouchObservation> callback){callback.accept(com.fromscratch.pouch.PouchObservation.unknown());}
	default void bagPreview(java.util.function.Consumer<com.fromscratch.buyback.BagObservation> callback){callback.accept(com.fromscratch.buyback.BagObservation.unknown());}
	default void buyBag(UUID revision,UUID purchaseId,com.fromscratch.buyback.BagObservation contents,java.util.function.Consumer<com.fromscratch.buyback.BuybackPurchase> committed){throw new UnsupportedOperationException("Bag buybacks unavailable");}
	default void buyback(UUID revision,String catalogId,UUID purchaseId,com.fromscratch.pouch.PouchObservation contents,java.util.function.Consumer<com.fromscratch.buyback.BuybackPurchase> committed){buyback(revision,catalogId,purchaseId);}
	default void recordExpense(UUID revision,long gp,String reason) { throw new UnsupportedOperationException("Expense recording is unavailable"); }
	default void exchangeHistory(boolean buy,com.fromscratch.ge.GeHistory.Cursor cursor,java.util.function.Consumer<com.fromscratch.ge.GeHistory.Page> callback)
	{callback.accept(new com.fromscratch.ge.GeHistory.Page(java.util.Collections.emptyList(),null,"No completed Grand Exchange trades recorded."));}
	default void history(boolean manual, BankHistory.Cursor cursor, java.util.function.Consumer<BankHistory.Page> callback)
	{ callback.accept(new BankHistory.Page(java.util.Collections.emptyList(), null, "No bank changes recorded.")); }
}

package com.fromscratch.bank;

import java.awt.*;
import javax.swing.*;

/** High-contrast player attestation. Standard checkbox label hit-testing and Space activation remain intact. */
final class BankAttestation extends JCheckBox
{
	BankAttestation()
	{this("<html>I confirm my inventory<br>and equipped items<br>are banked.</html>","I confirm my inventory and equipped items are banked.");}
	BankAttestation(String text,String accessible)
	{
		super(text);
		setFont(new Font(Font.DIALOG, Font.PLAIN, 12));
		setForeground(new Color(240, 231, 216));
		setBackground(new Color(42, 35, 49));
		setOpaque(true); setRolloverEnabled(true); setFocusPainted(false);
		setBorderPainted(true);
		setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(100, 78, 119)), BorderFactory.createEmptyBorder(8, 6, 8, 6)));
		setIconTextGap(8); setAlignmentX(LEFT_ALIGNMENT);
		getAccessibleContext().setAccessibleName(accessible);
		Icon indicator = new Indicator();
		setIcon(indicator); setSelectedIcon(indicator); setRolloverIcon(indicator);
		setRolloverSelectedIcon(indicator); setPressedIcon(indicator); setDisabledIcon(indicator); setDisabledSelectedIcon(indicator);
	}
	@Override public Dimension getMaximumSize()
	{
		// Respect actual font/HTML height instead of stretching the confirmation row or clipping scaled text.
		return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
	}

	/** Draw only our Swing control, never any game widget or sprite. */
	private static final class Indicator implements Icon
	{
		public int getIconWidth() { return 22; }
		public int getIconHeight() { return 22; }
		public void paintIcon(Component component, Graphics graphics, int x, int y)
		{
			AbstractButton button = (AbstractButton) component;
			Graphics2D g = (Graphics2D) graphics.create();
			try
			{
				boolean selected = button.isSelected();
				g.setColor(selected ? new Color(94, 43, 128) : new Color(27, 24, 31)); g.fillRect(x + 2, y + 2, 18, 18);
				g.setColor(selected ? new Color(0xB450FF) : button.getModel().isRollover() ? Color.WHITE : new Color(201, 190, 213));
				g.setStroke(new BasicStroke(2)); g.drawRect(x + 2, y + 2, 18, 18);
				if (selected)
				{
					g.setColor(Color.WHITE); g.setStroke(new BasicStroke(3, BasicStroke.CAP_SQUARE, BasicStroke.JOIN_MITER));
					g.drawPolyline(new int[]{x + 6, x + 10, x + 17}, new int[]{y + 11, y + 15, y + 7}, 3);
				}
				if (button.hasFocus()) { g.setColor(new Color(0xFFD54F)); g.setStroke(new BasicStroke(1)); g.drawRect(x, y, 21, 21); }
			}
			finally { g.dispose(); }
		}
	}
}

package com.fromscratch.bank;

import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import lombok.Value;

/** One durable bank operation with optional high-water valuation/explicit-expense evidence, never inferred acquisition provenance. */
@Value
public class BankAudit
{
	public enum Kind { START, AUTOMATIC, SESSION_CHECK, CORRECTION, MIGRATION, ANCHOR, RESET, FINANCIAL_BASELINE, EXPENSE, EXCHANGE_BASELINE, EXCHANGE, BUYBACK_BASELINE, BUYBACK, POUCH_BASELINE, POUCH, STORAGE, STORAGE_REVIEW }
	UUID id;
	UUID session;
	Instant at;
	Kind kind;
	Map<Integer, Long> physicalChanges;
	Map<Integer, Long> balanceChanges;
	String reason;
	java.util.List<com.fromscratch.wealth.ValuationEvent> valuations;
	com.fromscratch.ge.GeUpdate exchange;
	com.fromscratch.buyback.BuybackPurchase buyback;
	com.fromscratch.pouch.PouchAction pouch;
	Map<Integer,Long> pouchTransfers;
	com.fromscratch.potion.PotionUpdate potion;
	public BankAudit(UUID id, UUID session, Instant at, Kind kind, Map<Integer, Long> physicalChanges,
		Map<Integer, Long> balanceChanges, String reason)
	{ this(id,session,at,kind,physicalChanges,balanceChanges,reason,java.util.Collections.emptyList()); }
	public BankAudit(UUID id, UUID session, Instant at, Kind kind, Map<Integer, Long> physicalChanges,
		Map<Integer, Long> balanceChanges, String reason, java.util.List<com.fromscratch.wealth.ValuationEvent> valuations)
	{this(id,session,at,kind,physicalChanges,balanceChanges,reason,valuations,com.fromscratch.ge.GeUpdate.empty());}
	public BankAudit(UUID id, UUID session, Instant at, Kind kind, Map<Integer, Long> physicalChanges,
		Map<Integer, Long> balanceChanges, String reason, java.util.List<com.fromscratch.wealth.ValuationEvent> valuations, com.fromscratch.ge.GeUpdate exchange)
	{this(id,session,at,kind,physicalChanges,balanceChanges,reason,valuations,exchange,null);}
	public BankAudit(UUID id, UUID session, Instant at, Kind kind, Map<Integer, Long> physicalChanges,
		Map<Integer, Long> balanceChanges, String reason, java.util.List<com.fromscratch.wealth.ValuationEvent> valuations,
		com.fromscratch.ge.GeUpdate exchange, com.fromscratch.buyback.BuybackPurchase buyback)
	{this(id,session,at,kind,physicalChanges,balanceChanges,reason,valuations,exchange,buyback,null,java.util.Collections.emptyMap());}
	public BankAudit(UUID id,UUID session,Instant at,Kind kind,Map<Integer,Long> physicalChanges,Map<Integer,Long> balanceChanges,String reason,
		java.util.List<com.fromscratch.wealth.ValuationEvent> valuations,com.fromscratch.ge.GeUpdate exchange,com.fromscratch.buyback.BuybackPurchase buyback,com.fromscratch.pouch.PouchAction pouch,Map<Integer,Long> pouchTransfers)
	{this(id,session,at,kind,physicalChanges,balanceChanges,reason,valuations,exchange,buyback,pouch,pouchTransfers,null);}
	public BankAudit(UUID id,UUID session,Instant at,Kind kind,Map<Integer,Long> physicalChanges,Map<Integer,Long> balanceChanges,String reason,
		java.util.List<com.fromscratch.wealth.ValuationEvent> valuations,com.fromscratch.ge.GeUpdate exchange,com.fromscratch.buyback.BuybackPurchase buyback,com.fromscratch.pouch.PouchAction pouch,Map<Integer,Long> pouchTransfers,com.fromscratch.potion.PotionUpdate potion)
	{
		this.id = java.util.Objects.requireNonNull(id);
		this.session = java.util.Objects.requireNonNull(session);
		this.at = java.util.Objects.requireNonNull(at);
		this.kind = java.util.Objects.requireNonNull(kind);
		this.physicalChanges = BankRun.quantities(physicalChanges, false);
		this.balanceChanges = BankRun.quantities(balanceChanges, false);
		if (reason == null || reason.length() > 500) { throw new IllegalArgumentException("Invalid bank change description"); }
		this.reason = reason;
		this.valuations=java.util.Collections.unmodifiableList(new java.util.ArrayList<>(valuations));
		this.exchange=java.util.Objects.requireNonNull(exchange);this.buyback=buyback;
		if((kind==Kind.BUYBACK)!=(buyback!=null)||buyback!=null&&(!id.equals(buyback.getId())||!at.equals(buyback.getAt()))){throw new IllegalArgumentException("Invalid purchase audit evidence");}
		this.pouch=pouch;this.pouchTransfers=com.fromscratch.pouch.PouchState.quantities(pouchTransfers);
		this.potion=potion;
		if((kind==Kind.POUCH)!=(pouch!=null)||kind!=Kind.AUTOMATIC&&!this.pouchTransfers.isEmpty()){throw new IllegalArgumentException("Invalid pouch audit evidence");}
	}
}

