			busy = true; error = false; freshInstallationRequired = false;
			message = "Verifying the new installation..."; publish();
			submit(root -> null, ignored -> { busy = false; load(); }, () ->
			{
				gate.confirmFreshInstallation();
				return gate.get();
			});
		});
	}
