/** Compact two-column card that grows with larger fonts/captions; no inner scrolling or rebuilding. */
public final class BankTile extends JPanel
{
	private final JLabel value = new JLabel("Coming soon", SwingConstants.CENTER);
	private final JLabel detail = new JLabel("",SwingConstants.CENTER);
	private final JLabel icon = new JLabel();
	private final JLabel label;
	public BankTile(String title, String wrappedTitle, int itemId, BankIcons icons)
	{
		setLayout(new BorderLayout(0, 2)); setBackground(new Color(43, 39, 33));
		setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(new Color(75, 62, 85)), BorderFactory.createEmptyBorder(4, 3, 4, 3)));
		icon.setHorizontalAlignment(SwingConstants.CENTER); icons.apply(icon, itemId); add(icon, BorderLayout.NORTH);
		label = new JLabel("<html><center>" + wrappedTitle + "</center></html>", SwingConstants.CENTER);
		label.setFont(FontManager.getRunescapeSmallFont()); label.setForeground(new Color(216, 205, 181)); label.setToolTipText(title); add(label, BorderLayout.CENTER);
		value.setFont(FontManager.getRunescapeFont()); value.setForeground(new Color(0xFFD54F)); value.setToolTipText(title + ": Coming soon");
		JPanel numbers=new JPanel(new BorderLayout(0,1));numbers.setOpaque(false);numbers.add(value,BorderLayout.NORTH);
		// RuneLite bitmap fonts render HTML <small> with clipped descenders; use a separate standard-font caption.
		detail.setFont(new Font(Font.DIALOG,Font.PLAIN,10));detail.setForeground(new Color(216,205,181));detail.setVisible(false);numbers.add(detail,BorderLayout.SOUTH);add(numbers,BorderLayout.SOUTH);
		getAccessibleContext().setAccessibleName(title);
	}
	@Override public Dimension getPreferredSize(){Dimension natural=super.getPreferredSize();return new Dimension(Math.max(100,natural.width),Math.max(98,natural.height));}
	@Override public Dimension getMinimumSize(){return new Dimension(92,getPreferredSize().height);}
	public void value(String text, String explanation) { value(text,explanation,null); }
	public void value(String text,String explanation,String caption)
	{
		if(!text.equals(value.getText())){value.setText(text);}value.setToolTipText(explanation);detail.setToolTipText(explanation);label.setToolTipText(explanation);icon.setToolTipText(explanation);setToolTipText(explanation);
		detail.setText(caption==null?"":caption);detail.setVisible(caption!=null);
	}
	/** Small explicit-accounting action; attach once because Swing mouse events do not bubble from labels. */
	public void onActivate(Runnable action)
	{
		setFocusable(true);setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		java.awt.event.MouseAdapter mouse=new java.awt.event.MouseAdapter(){@Override public void mouseClicked(java.awt.event.MouseEvent e){if(SwingUtilities.isLeftMouseButton(e)&&e.getClickCount()==1){action.run();}}};
		addActivation(this,mouse);
		getInputMap(WHEN_FOCUSED).put(KeyStroke.getKeyStroke("SPACE"),"record");getInputMap(WHEN_FOCUSED).put(KeyStroke.getKeyStroke("ENTER"),"record");getActionMap().put("record",new AbstractAction(){public void actionPerformed(java.awt.event.ActionEvent e){action.run();}});
	}
	private static void addActivation(Container root,java.awt.event.MouseListener mouse)
	{
		root.addMouseListener(mouse);root.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));for(Component c:root.getComponents()){if(c instanceof Container){addActivation((Container)c,mouse);}else{c.addMouseListener(mouse);c.setCursor(root.getCursor());}}
	}
}

package com.fromscratch.bank;

import java.util.Arrays;
import java.util.function.Consumer;
import java.util.function.LongSupplier;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Opt-in monotonic, sampled phase timings. No item contents, identities or file paths are recorded. */
@Singleton @Slf4j
public final class BankTimings
{
	public enum Phase { EVENT, CAPTURE, AGGREGATE, DIFFERENCE, PREPARED, WRITE_START, WRITE_END, PUBLISHED, OVERLAY, SWING }
	private volatile boolean enabled;
	private long lastSample;
	private Trace current;
	public synchronized void configure(boolean enabled) { this.enabled = enabled; if (!enabled) { current = null; } }
	public synchronized void event()
	{
		if (!enabled || !log.isDebugEnabled()) { current = null; return; }
		long now = System.nanoTime();
		if (current != null && !current.reached(Phase.PUBLISHED)) { return; }
		current = lastSample != 0 && now - lastSample < 5_000_000_000L ? null : new Trace(System::nanoTime, message -> log.debug("From Scratch timing: {}", message));
		if (current != null) { lastSample = now; }
	}
	public synchronized Trace current() { return current; }
	public static void mark(Trace trace, Phase phase) { if (trace != null) { trace.mark(phase); } }
	public static final class Trace
	{
		private final LongSupplier clock;
		private final Consumer<String> output;
		private final long[] times = new long[Phase.values().length];
		private boolean complete;
		Trace(LongSupplier clock, Consumer<String> output) { this.clock = clock; this.output = output; Arrays.fill(times, -1); mark(Phase.EVENT); }
		public synchronized boolean reached(Phase phase) { return times[phase.ordinal()] >= 0; }
		public synchronized void mark(Phase phase)
		{
			if (times[phase.ordinal()] >= 0) { return; }
			times[phase.ordinal()] = clock.getAsLong();
			if (phase == Phase.PUBLISHED) { output.accept(summary("committed")); }
			if (!complete && reached(Phase.PUBLISHED) && reached(Phase.OVERLAY) && reached(Phase.SWING)) { complete = true; output.accept(summary("presented")); }
		}
		public synchronized String summary(String label)
		{
			StringBuilder text = new StringBuilder(label).append(" elapsed_ms[");
			for (Phase phase : Phase.values()) { long n = times[phase.ordinal()]; text.append(phase).append('=').append(n < 0 ? "pending" : String.format(java.util.Locale.ROOT, "%.3f", (n - times[0]) / 1_000_000.0)).append(' '); }
			return text.append(']').toString();
		}
		public synchronized void failed() { if (!complete) { complete = true; output.accept(summary("save_failed")); } }
	}
}

package com.fromscratch.bank;

import com.fromscratch.wealth.BankValuation;
import com.fromscratch.wealth.FinancialState;
import com.fromscratch.wealth.GpFormatter;

/** Presentation only: bounded Swing HTML, escaped text and no technical accounting timestamps. */
final class BankTooltips
{
	static final int WIDTH = 250;
	private BankTooltips() { }

	static String html(String title, String... lines)
	{
		StringBuilder result = new StringBuilder("<html><div style='width:").append(WIDTH)
			// Swing's legacy HTML renderer enlarges CSS px by 4/3; pt matches its logical layout units.
			.append("pt;font-family:Dialog;font-size:11pt'><b>").append(escape(title)).append("</b>");
		for (String line : lines) { if (line != null && !line.isEmpty()) { result.append("<br>").append(escape(line)); } }
		return result.append("</div></html>").toString();
	}

	static String gained(FinancialState state)
	{
		if (state == null) { return html("Estimated Value Gained", "Estimated bank gains are unavailable."); }
		int unknown = state.getUnpricedGains().size();
		return html("Estimated Value Gained", "Estimated bank gains: " + GpFormatter.exact(state.getGainedGp()) + ".",
			"Tracks bank progress, not every acquisition.", unknown == 0 ? null : unknown == 1
				? "1 item type has an unknown historical price." : unknown + " item types have unknown historical prices.");
	}

	static String netWorth(BankValuation market)
	{
		if (market == null) { return html("Current Bank Net Worth", "Bank value is currently unavailable."); }
		String amount = market.getSubtotalGp() == null ? "Value is too large to display."
			: market.getPricedTypes() == 0 && market.getMissingTypes() > 0 ? "Prices are currently unavailable."
			: (market.getMissingTypes() > 0 ? "Priced subtotal: " : "Estimated bank value: ") + GpFormatter.exact(market.getSubtotalGp()) + ".";
		int missing = market.getMissingTypes(), stale = market.getStaleTypes();
		return html("Current Bank Net Worth", amount, "GE estimates; coins counted once.",
			missing == 0 ? null : missing == 1 ? "1 item type has no available price." : missing + " item types have no available price.",
			stale == 0 ? null : stale == 1 ? "1 item type uses an older price." : stale + " item types use older prices.");
	}

	static String bankGp(long gp)
	{
		return html("Bank GP", "Bank coin balance: " + GpFormatter.exact(gp) + ".", "Signed bank coins, not a spendable wallet.");
	}
	static String bankGp(BankRun run)
	{
		if(run.getBuybacks().getCommittedGp()==0){return bankGp(run.balance(net.runelite.api.gameval.ItemID.COINS));}
		return html("Available Bank GP","Unspent: "+GpFormatter.exact(com.fromscratch.buyback.BuybackEngine.available(run))+".","Raw bank progress: "+GpFormatter.exact(run.balance(net.runelite.api.gameval.ItemID.COINS))+".","Committed buybacks: "+GpFormatter.exact(run.getBuybacks().getCommittedGp())+". Physical coins are untouched.");
	}
	static String expenses(BankRun run)
	{
		if(run.getBuybacks().getCommittedGp()==0){return expenses(run.getFinancial(),run.getExchange());}
		return html("Recorded Losses / Expenses","Legacy buybacks: "+GpFormatter.exact(run.getBuybacks().getCommittedGp())+".","Other recorded expenses: "+GpFormatter.exact(run.getFinancial().getExpenseGp())+".","Estimated GE fees: "+GpFormatter.exact(run.getExchange().getEstimatedTaxGp())+".");
	}

	static String expenses(FinancialState state)
	{
		if (state == null || state.getExpenseRecords() == 0)
		{
			return html("Recorded Losses / Expenses", state==null?"Recorded spending is unavailable.":state.isImportedBaseline()?"Earlier spending history is incomplete.":"No recorded spending yet.", "Withdrawals and legacy offsets are not spending. Click to record a verified expense.");
		}
		long count = state.getExpenseRecords();
		return html("Recorded Losses / Expenses", "Recorded amount: " + GpFormatter.exact(state.getExpenseGp()) + ".",
			count + (count == 1 ? " recorded expense." : " recorded expenses."), "Click to record another expense.");
	}
	static String expenses(FinancialState state,com.fromscratch.ge.GeState exchange)
	{
		if(exchange.getEstimatedTaxGp()==0){return expenses(state);}
		return html("Recorded Losses / Expenses","Explicit expenses: "+GpFormatter.exact(state.getExpenseGp())+".","Estimated GE seller fees: "+GpFormatter.exact(exchange.getEstimatedTaxGp())+".","Fees are estimates; bank coins are never deducted twice.");
	}

	static String escape(String value)
	{
		return value.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;").replace("'", "&#39;");
	}
}

