package com.fromscratch.ge;

import java.time.Instant;
import java.util.*;
import javax.inject.*;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/** Client-thread passive offer observation. No GE UI, inventory, menu or action manipulation. */
@Singleton
public final class RuneLiteGeSource
{
	interface Access { boolean loggedIn(); GrandExchangeOffer[] offers(); String itemName(int id); }
	private final Access access;
	private UUID session=UUID.randomUUID();
	private final boolean[] seen=new boolean[8];
	private final Deque<GeObservation> pending=new ArrayDeque<>();
	private boolean seeded;
	private boolean overflow;
	@Inject public RuneLiteGeSource(Client client)
	{
		this(new Access(){public boolean loggedIn(){return client.getGameState()==GameState.LOGGED_IN&&client.getEnvironment()==0;}public GrandExchangeOffer[] offers(){return client.getGrandExchangeOffers();}public String itemName(int id){return client.getItemDefinition(id).getName();}});
	}
	RuneLiteGeSource(Access access){this.access=access;}
	public void resetSession(){session=UUID.randomUUID();Arrays.fill(seen,false);pending.clear();seeded=false;overflow=false;}
	public void changed(int slot,GrandExchangeOffer offer)
	{
		if(!access.loggedIn()||offer==null||slot<0||slot>=8){return;}
		boolean initial=!seen[slot];
		if(offer.getState()==GrandExchangeOfferState.EMPTY&&initial){return;}
		try
		{
			GeObservation copy=new GeObservation(UUID.randomUUID(),session,Instant.now(),slot,offer.getState()==GrandExchangeOfferState.EMPTY?0:offer.getItemId(),
				offer.getState()==GrandExchangeOfferState.EMPTY?"":access.itemName(offer.getItemId()),offer.getState(),offer.getTotalQuantity(),offer.getQuantitySold(),offer.getPrice(),offer.getSpent(),initial);
			if(pending.size()>=256){overflow=true;return;}pending.addLast(copy);seen[slot]=true;
		}
		catch(IllegalArgumentException ex){overflow=true; /* Report a gap; never turn invalid packets into fills. */}
	}
	/** Seed only nonempty current snapshots, then drain copied events before the same tick's bank comparison. */
	public List<GeObservation> drain()
	{
		if(!access.loggedIn()){return Collections.emptyList();}
		if(!seeded)
		{
			GrandExchangeOffer[] offers=access.offers();
			if(offers!=null&&offers.length==8){for(int slot=0;slot<offers.length;slot++){if(!seen[slot]){changed(slot,offers[slot]);}}seeded=true;}
		}
		List<GeObservation> result=new ArrayList<>(pending);pending.clear();return result;
	}
	public boolean takeObservationGap(){boolean gap=overflow;overflow=false;return gap;}
}

package com.fromscratch.model;

import java.util.Collections;
import java.util.Map;
import java.util.TreeMap;
import lombok.EqualsAndHashCode;
import lombok.Getter;

/** Immutable exact-ID quantities, aggregated across duplicate physical slots. */
@Getter
@EqualsAndHashCode
public final class ContainerSnapshot
{
	private final Map<Integer, Long> quantities;
	private final int occupiedSlots;
	private final long totalQuantity;

	public ContainerSnapshot(Map<Integer, Long> quantities, int occupiedSlots)
	{
		TreeMap<Integer, Long> copy = new TreeMap<>();
		long total = 0;
		for (Map.Entry<Integer, Long> entry : quantities.entrySet())
		{
			if (entry.getKey() == null || entry.getKey() < 0 || entry.getValue() == null || entry.getValue() <= 0)
			{
				throw new IllegalArgumentException("Snapshot item IDs and quantities must be valid");
			}
			total = Math.addExact(total, entry.getValue());
			copy.put(entry.getKey(), entry.getValue());
		}
		if (occupiedSlots < copy.size() || occupiedSlots > total || (copy.isEmpty() && occupiedSlots != 0))
		{
			throw new IllegalArgumentException("Snapshot slot count does not match its quantities");
		}
		this.quantities = Collections.unmodifiableMap(copy);
		this.occupiedSlots = occupiedSlots;
		this.totalQuantity = total;
	}

	public long quantity(int itemId)
	{
		return quantities.getOrDefault(itemId, 0L);
	}
}

package com.fromscratch.model;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;
import lombok.Getter;

/**
 * Pure setup workflow. Previews are ephemeral; only a successful repository commit
 * can replace the loaded run. Callers must supply fresh, verified observations.
 */
@Getter
public final class InitializationSession
{
	private final String characterKey;
	private RunRecord saved;
	private boolean initializing;
	private UUID pendingRunId;
	private UUID reviewToken;
	private LegacySnapshot preview;

	public InitializationSession(String characterKey, RunRecord saved)
	{
		this.characterKey = Objects.requireNonNull(characterKey);
		if (saved != null && !characterKey.equals(saved.getState().getCharacterKey()))
		{
			throw new IllegalArgumentException("Character mismatch");
		}
		this.saved = saved;
	}

	public void begin()
	{
		if (initializing || (saved != null && saved.getState().getStatus() == RunStatus.ACTIVE))
		{
			throw new IllegalStateException("A run or initialization already exists");
		}
		initializing = true;
		pendingRunId = UUID.randomUUID();
	}

	public void observe(LegacySnapshot observation)
	{
		if (!initializing) { throw new IllegalStateException("Begin setup before capturing a snapshot"); }
		if (preview == null || !preview.sameContents(observation))
		{
			preview = Objects.requireNonNull(observation);
			reviewToken = UUID.randomUUID();
		}
	}

	public void invalidatePreview()
	{
		preview = null;
		reviewToken = null;
	}

	public void cancel()
	{
		initializing = false;
		pendingRunId = null;
		invalidatePreview();
	}

	public RunRecord prepareActivation(UUID expectedReview, LegacySnapshot fresh, Instant confirmedAt)
	{
		if (!initializing || preview == null || !Objects.equals(reviewToken, expectedReview))
		{
			throw new IllegalStateException("Snapshot review expired. Review the current snapshot before confirming");
		}
		if (!preview.sameContents(fresh))
		{
			observe(fresh);
			throw new IllegalStateException("Snapshot changed. Review the updated summary and confirm again");
		}
		return RunRecord.activate(characterKey, pendingRunId, preview, confirmedAt);
	}

	public void committed(RunRecord record)
	{
		if (!characterKey.equals(record.getState().getCharacterKey())) { throw new IllegalArgumentException("Character mismatch"); }
		saved = record;
		cancel();
	}
}

package com.fromscratch.model;

import java.time.Instant;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import java.util.Objects;
import lombok.EqualsAndHashCode;
import lombok.Getter;

/** Permanent baseline. No live observation is allowed to modify a confirmed snapshot. */
@Getter
@EqualsAndHashCode
public final class LegacySnapshot
{
	private final Instant capturedAt;
	private final Map<SnapshotLocation, ContainerSnapshot> containers;

	public LegacySnapshot(Instant capturedAt, Map<SnapshotLocation, ContainerSnapshot> containers)
	{
		this.capturedAt = Objects.requireNonNull(capturedAt, "Snapshot time is required");
		EnumMap<SnapshotLocation, ContainerSnapshot> copy = new EnumMap<>(SnapshotLocation.class);
		for (SnapshotLocation location : SnapshotLocation.values())
		{
			copy.put(location, Objects.requireNonNull(containers.get(location), "All three containers are required"));
		}
		this.containers = Collections.unmodifiableMap(copy);
	}

	/** Confirmation compares contents rather than the timestamp of a second read. */
	public boolean sameContents(LegacySnapshot other)
	{
		return other != null && containers.equals(other.containers);
	}

	public ContainerSnapshot at(SnapshotLocation location)
	{
		return containers.get(location);
	}
}

package com.fromscratch.model;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;
import lombok.EqualsAndHashCode;
import lombok.Getter;
import com.fromscratch.tracking.ItemProgress;
import com.fromscratch.tracking.AccountingPlan;

/** A durable activation or reset checkpoint, distinct from an unsaved setup preview. */
@Getter
@EqualsAndHashCode
public final class RunRecord
{
	private final RunState state;
	private final UUID revision;
	private final UUID previousRunId;
	private final LegacySnapshot snapshot;
	private final VirtualOwnership ownership;
	private final ItemProgress itemProgress;

	public RunRecord(RunState state, UUID revision, UUID previousRunId, LegacySnapshot snapshot)
	{
		this(state, revision, previousRunId, snapshot, VirtualOwnership.empty());
	}

	public RunRecord(RunState state, UUID revision, UUID previousRunId, LegacySnapshot snapshot, VirtualOwnership ownership)
	{
		this(state, revision, previousRunId, snapshot, ownership, snapshot == null ? null : ItemProgress.initial(snapshot));
	}

	public RunRecord(RunState state, UUID revision, UUID previousRunId, LegacySnapshot snapshot, VirtualOwnership ownership, ItemProgress itemProgress)
	{
		this.state = Objects.requireNonNull(state);
		this.revision = Objects.requireNonNull(revision);
		this.previousRunId = previousRunId;
		this.snapshot = snapshot;
		this.ownership = Objects.requireNonNull(ownership, "Virtual ownership is required");
		this.itemProgress = itemProgress;
		if (state.getStatus() == RunStatus.ACTIVE)
		{
			Objects.requireNonNull(snapshot, "An active run requires its complete baseline");
			Objects.requireNonNull(itemProgress, "An active run requires its item checkpoint");
			if (itemProgress.isEstablished())
			{
				if (!revision.equals(itemProgress.getLedgerHead())) { throw new IllegalArgumentException("Checkpoint revision does not match its item journal"); }
				itemProgress.validateOwnership(ownership);
			}
			if (previousRunId != null || snapshot.getCapturedAt().isAfter(state.getStartedAt()))
			{
				throw new IllegalArgumentException("Invalid activation checkpoint");
			}
		}
		else if (state.getStatus() != RunStatus.NOT_STARTED || snapshot != null || previousRunId == null || !ownership.getItems().isEmpty() || itemProgress != null)
		{
			throw new IllegalArgumentException("Only active runs or empty explicit resets can be saved");
		}
	}

	public static RunRecord activate(String characterKey, UUID runId, LegacySnapshot snapshot, Instant startedAt)
	{
		return new RunRecord(RunState.restore(RunState.CURRENT_SCHEMA_VERSION, characterKey, runId,
			RunStatus.ACTIVE, startedAt, null), UUID.randomUUID(), null, snapshot);
	}

	public static RunRecord reset(RunRecord active)
	{
		if (active.getState().getStatus() != RunStatus.ACTIVE)
		{
			throw new IllegalStateException("There is no active run to reset");
		}
		return new RunRecord(RunState.notStarted(active.getState().getCharacterKey()),
			UUID.randomUUID(), active.getState().getRunId(), null);
	}

	public VirtualEconomy getEconomy()
	{
		return new VirtualEconomy(ownership, itemProgress == null ? 0 : itemProgress.getUnlocked().size());
	}

	/** New immutable revision; the run header and permanent legacy baseline stay unchanged. */
	public RunRecord withOwnership(VirtualOwnership ownership)
	{
		if (itemProgress != null && itemProgress.isEstablished()) { throw new IllegalStateException("Tracked ownership must change through a journaled item plan"); }
		return new RunRecord(state, UUID.randomUUID(), previousRunId, snapshot, ownership, itemProgress);
	}

	/** The ledger head is also the new revision, linking one atomic item batch to one checkpoint. */
	public RunRecord withItems(AccountingPlan plan)
	{
		return new RunRecord(state, plan.getProgress().getLedgerHead(), previousRunId, snapshot, plan.getOwnership(), plan.getProgress());
	}
}

package com.fromscratch.model;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;
import lombok.EqualsAndHashCode;
import lombok.Getter;

/**
 * Immutable, versioned lifecycle header for a single character's run.
 *
 * <p>This is a domain object, not a Gson deserialization target. The storage
 * codec must pass through {@link #restore} after schema validation so
 * malformed data cannot bypass constructor validation. The separate RunRecord
 * envelope supplies the immutable legacy baseline introduced in Milestone 2.</p>
 */
@Getter
@EqualsAndHashCode
public final class RunState
{
	public static final int CURRENT_SCHEMA_VERSION = 1;

	private final int schemaVersion;
	// Verified opaque character identity; never use a display name as a save key.
	private final String characterKey;
	private final UUID runId;
	private final RunStatus status;
	private final Instant startedAt;
	private final Instant completedAt;

	private RunState(int schemaVersion, String characterKey, UUID runId,
		RunStatus status, Instant startedAt, Instant completedAt)
	{
		if (schemaVersion != CURRENT_SCHEMA_VERSION)
		{
			throw new IllegalArgumentException("Unsupported run schema; migrate before restoring");
		}
		if (characterKey == null || characterKey.trim().isEmpty())
		{
			throw new IllegalArgumentException("A character profile key is required");
		}
		Objects.requireNonNull(status, "Run status is required");
		if (status == RunStatus.NOT_STARTED)
		{
			if (runId != null || startedAt != null || completedAt != null)
			{
				throw new IllegalArgumentException("An unstarted run cannot contain active run identity or times");
			}
		}
		else
		{
			Objects.requireNonNull(runId, "An initialized run requires a run ID");
			if (status == RunStatus.INITIALIZING)
			{
				if (startedAt != null || completedAt != null)
				{
					throw new IllegalArgumentException("Initialization is not an activated run");
				}
			}
			else
			{
				Objects.requireNonNull(startedAt, "An activated run requires a start time");
				if (status == RunStatus.COMPLETED)
				{
					Objects.requireNonNull(completedAt, "A completed run requires an end time");
					if (completedAt.isBefore(startedAt))
					{
						throw new IllegalArgumentException("Run end precedes its start");
					}
				}
				else if (completedAt != null)
				{
					throw new IllegalArgumentException("An ongoing run cannot have an end time");
				}
			}
		}
		this.schemaVersion = schemaVersion;
		this.characterKey = characterKey;
		this.runId = runId;
		this.status = status;
		this.startedAt = startedAt;
		this.completedAt = completedAt;
	}

	/** Creates an explicit empty header only after a character has been identified. */
	public static RunState notStarted(String characterKey)
	{
		return restore(CURRENT_SCHEMA_VERSION, characterKey, null, RunStatus.NOT_STARTED, null, null);
	}

	/** Validates a migrated header without silently replacing invalid data with defaults. */
	public static RunState restore(int schemaVersion, String characterKey, UUID runId,
		RunStatus status, Instant startedAt, Instant completedAt)
	{
		return new RunState(schemaVersion, characterKey, runId, status, startedAt, completedAt);
	}
}

