		{
			JsonObject data = value.getAsJsonObject();
			if (deficits) { keys(data, "id", "time", "item", "quantity", "virtualChange", "locations", "source", "destination", "category", "confidence", "reason", "legacyWithdrawalChange"); }
			else { keys(data, "id", "time", "item", "quantity", "virtualChange", "locations", "source", "destination", "category", "confidence", "reason"); }
			Map<SnapshotLocation, Long> locations = new EnumMap<>(SnapshotLocation.class);
			data.getAsJsonObject("locations").entrySet().forEach(entry -> locations.put(SnapshotLocation.valueOf(entry.getKey()), signed(entry.getValue())));
			UUID id = uuid(data.get("id")); if (!ids.add(id)) { throw new IllegalArgumentException("Duplicate transaction ID"); }
			entries.add(new ItemTransaction(id, instant(data.get("time")), Math.toIntExact(signed(data.get("item"))), number(data.get("quantity")),
				signed(data.get("virtualChange")), locations, location(data.get("source")), location(data.get("destination")),
				ItemTransaction.Category.valueOf(string(data.get("category"))), ItemTransaction.Confidence.valueOf(string(data.get("confidence"))), string(data.get("reason")),
				deficits ? signed(data.get("legacyWithdrawalChange")) : 0));
		}
		return entries;
	}
	private static SnapshotLocation location(JsonElement value) { return value.isJsonNull() ? null : SnapshotLocation.valueOf(string(value)); }
	private static long signed(JsonElement value)
	{
		if (value == null || !value.isJsonPrimitive() || !value.getAsJsonPrimitive().isNumber() || !value.getAsString().matches("0|-?[1-9][0-9]*"))
		{ throw new IllegalArgumentException("Invalid signed integer"); }
		long result = Long.parseLong(value.getAsString());
		if (result == Long.MIN_VALUE) { throw new IllegalArgumentException("Unsupported signed endpoint"); }
		return result;
	}
}

package com.fromscratch.persistence;

import com.fromscratch.model.RunRecord;
import com.fromscratch.model.SnapshotLocation;
import com.fromscratch.model.VirtualLocation;
import com.fromscratch.tracking.ItemLedgerBatch;
import com.fromscratch.tracking.ItemTransaction;
import java.io.IOException;
import java.util.HashSet;
import java.util.Map;
import java.util.HashMap;
import java.util.Set;
import java.util.UUID;
import net.runelite.client.util.Filepath;

/** Historical M4 journal compatibility. The live bank repository only verifies/archives these segments. */
final class ItemJournalStore
{
	private final RunRecordCodec codec;
	ItemJournalStore(RunRecordCodec codec) { this.codec = codec; }
	void append(Filepath directory, RunRecord before, RunRecord after, java.util.List<ItemTransaction> entries) throws IOException
	{
		validateDeltas(before, after, entries);
		ItemLedgerBatch batch = new ItemLedgerBatch(after.getRevision(), before.getItemProgress().getLedgerHead(), before.getRevision(),
			after.getState().getCharacterKey(), after.getState().getRunId(), after.getItemProgress().getSessionId(),
			after.getItemProgress().getSequence(), after.getItemProgress().getObservedAt(), SaveIntegrity.sha256(codec.encode(after)), entries);
		if (batch.getSequence() != Math.incrementExact(before.getItemProgress().getSequence())) { throw new SaveException("Ledger sequence changed; reload before retrying."); }
		Filepath file = path(directory, batch.getRunId(), batch.getId());
		if (!file.exists()) { BankStorageFiles.writeNew(file, codec.journal.encode(batch)); }
		if (!read(file).equals(batch)) { throw new SaveException("Ledger batch conflicts with existing recovery evidence. Files were preserved."); }
	}
	void verifyHead(Filepath directory, RunRecord run) throws IOException
	{
		verifyHead(directory, run, RunRecordCodec.FORMAT_VERSION);
	}
	private void verifyHead(Filepath directory, RunRecord run, int format) throws IOException
	{
		if (run.getItemProgress() == null || run.getItemProgress().getLedgerHead() == null) { return; }
		ItemLedgerBatch batch = read(path(directory, run.getState().getRunId(), run.getItemProgress().getLedgerHead()));
		if (!batch.getId().equals(run.getRevision()) || batch.getSequence() != run.getItemProgress().getSequence()
			|| !batch.getCharacter().equals(run.getState().getCharacterKey()) || !batch.getRunId().equals(run.getState().getRunId())
			|| !batch.getSessionId().equals(run.getItemProgress().getSessionId()) || !batch.getTime().equals(run.getItemProgress().getObservedAt())
			|| !batch.getResultSha256().equals(SaveIntegrity.sha256(codec.encodeVersion(run, format))))
		{ throw new SaveException("Item ledger and checkpoint disagree. Files were preserved; reload is blocked."); }
	}
	void verifyChain(Filepath directory, RunRecord run) throws IOException
	{
		verifyChain(directory, run, RunRecordCodec.FORMAT_VERSION);
	}
	void verifyChain(Filepath directory, RunRecord run, int format) throws IOException
	{
		verifyHead(directory, run, format);
		if (run.getItemProgress() == null) { return; }
		UUID head = run.getItemProgress().getLedgerHead(); long sequence = run.getItemProgress().getSequence();
		Set<UUID> transactions = new HashSet<>();
		while (head != null)
		{
			ItemLedgerBatch batch = read(path(directory, run.getState().getRunId(), head));
			if (batch.getSequence() != sequence || !head.equals(batch.getId()) || !batch.getCharacter().equals(run.getState().getCharacterKey())
				|| !batch.getRunId().equals(run.getState().getRunId()) || (sequence > 1 && !batch.getPreviousRevision().equals(batch.getPreviousHead())))
			{ throw new SaveException("Item journal chain is incomplete or belongs to another run. Files were preserved."); }
			for (ItemTransaction entry : batch.getEntries()) { if (!transactions.add(entry.getId())) { throw new SaveException("Duplicate transaction in item journal; files were preserved."); } }
			head = batch.getPreviousHead(); sequence--;
		}
		if (sequence != 0) { throw new SaveException("Item journal chain is incomplete; files were preserved."); }
		for (ItemTransaction entry : run.getItemProgress().getRecent()) { if (!transactions.contains(entry.getId())) { throw new SaveException("Recent history has no journal entry."); } }
		for (ItemTransaction entry : run.getItemProgress().getAcquisitions()) { if (!transactions.contains(entry.getId())) { throw new SaveException("Acquisition history has no journal entry."); } }
	}
	private ItemLedgerBatch read(Filepath file) throws IOException
	{
		if (!file.exists()) { throw new SaveException("An item journal segment is missing. Files were preserved; restore its matching checkpoint and ledger."); }
		return codec.journal.decode(BankStorageFiles.readText(file));
	}
	private static Filepath path(Filepath directory, UUID run, UUID id) { return directory.joinSegment("ledger-" + run + "-" + id + ".json"); }
	private static void validateDeltas(RunRecord before, RunRecord after, java.util.List<ItemTransaction> entries) throws SaveException
	{
		Map<Integer, Long> totals = new HashMap<>(before.getOwnership().getTotals());
		Map<Integer, Long> withdrawals = new HashMap<>(before.getItemProgress().getLegacyDeficits().getItems());
		Map<Integer, Map<SnapshotLocation, Long>> locations = new HashMap<>();
		before.getOwnership().getItems().forEach((id, item) ->
		{
			Map<SnapshotLocation, Long> counts = new java.util.EnumMap<>(SnapshotLocation.class);
			for (SnapshotLocation location : SnapshotLocation.values()) { counts.put(location, item.at(VirtualLocation.valueOf(location.name()))); }
			locations.put(id, counts);
		});
		for (ItemTransaction entry : entries)
		{
			if (entry.getItemId() < 0) { continue; }
			totals.merge(entry.getItemId(), entry.getVirtualChange(), Math::addExact);
			withdrawals.merge(entry.getItemId(), entry.getLegacyWithdrawalChange(), Math::addExact);
			Map<SnapshotLocation, Long> counts = locations.computeIfAbsent(entry.getItemId(), ignored -> new java.util.EnumMap<>(SnapshotLocation.class));
			entry.getLocationChanges().forEach((location, delta) -> counts.merge(location, delta, Math::addExact));
		}
		Set<Integer> ids = new HashSet<>(totals.keySet()); ids.addAll(after.getOwnership().getItems().keySet());
		ids.addAll(withdrawals.keySet()); ids.addAll(after.getItemProgress().getLegacyDeficits().getItems().keySet());
		for (int id : ids)
		{
			if (totals.getOrDefault(id, 0L) != after.getOwnership().total(id)) { throw new SaveException("Transaction totals do not match the item checkpoint."); }
			if (withdrawals.getOrDefault(id, 0L) != after.getItemProgress().getLegacyDeficits().quantity(id)) { throw new SaveException("Legacy withdrawal deltas do not match the item checkpoint."); }
			for (SnapshotLocation location : SnapshotLocation.values())
			{
				long expected = locations.getOrDefault(id, java.util.Collections.emptyMap()).getOrDefault(location, 0L);
				if (expected != after.getOwnership().at(id, VirtualLocation.valueOf(location.name()))) { throw new SaveException("Transaction locations do not match the item checkpoint."); }
			}
		}
	}
}

package com.fromscratch.persistence;

import com.fromscratch.bank.BankRun;
import com.fromscratch.wealth.PriceQuote;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.math.BigInteger;
import java.nio.channels.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.util.Filepath;

/** One tiny run-scoped maximum, never a second economic ledger. All calls run on the storage worker. */
public final class PeakProgressRepository
{
	private final BankRunCodec codec;
	public PeakProgressRepository(BankRunCodec codec){this.codec=codec;}
	/** Paid equipment allowances have no market value. Raw signed B already includes coins once;
	 * subtracting committed GP for net worth and adding it as permanent spending cancel exactly. */
	public static Long candidate(BankRun run,Map<Integer,PriceQuote> prices)
	{
		BigInteger sum=BigInteger.valueOf(run.getFinancial().getExpenseGp());
		Map<Integer,Long> quantities=new TreeMap<>(run.getBalances());
		Set<Integer> pooled=com.fromscratch.potion.PotionWealth.pooledItems(run);pooled.forEach(quantities::remove);
		// A bag opening/closing is one physical item, not two oppositely priced variants.
		long bag=0;for(int id:com.fromscratch.buyback.BuybackCatalog.variants("looting_bag_family").keySet()){bag=Math.addExact(bag,quantities.getOrDefault(id,0L));quantities.remove(id);}if(bag!=0){quantities.put(ItemID.LOOTING_BAG,bag);}
		for(Map.Entry<Integer,Long> e:quantities.entrySet())
		{
			if(e.getValue()==0){continue;}
			PriceQuote p=e.getKey()==ItemID.COINS?PriceQuote.coins(Instant.now()):prices.get(e.getKey());
			if(p==null||!p.verifiedNow()){return null;}
			sum=sum.add(BigInteger.valueOf(e.getValue()).multiply(BigInteger.valueOf(p.getUnitGp())));
		}
		com.fromscratch.potion.PotionWealth.Value potions=com.fromscratch.potion.PotionWealth.calculate(run,prices);if(potions.getMissing()>0||potions.getStale()>0){return null;}sum=sum.add(potions.getGp());
		try{return Math.max(0,sum.longValueExact());}catch(ArithmeticException ex){return null;}
	}
	public Long checkpoint(Filepath root,BankRun run,Long candidate) throws IOException
	{
		Filepath base=root.join("characters",run.getCharacter());
		try(FileChannel channel=base.joinSegment("run.lock").openFileChannel(StandardOpenOption.CREATE,StandardOpenOption.WRITE);FileLock lock=channel.tryLock())
		{
			if(lock==null){throw new SaveException("Progress is being saved.");}
			Filepath d=ProgressBackup.directory(base,codec),file=d.joinSegment(file(run));
			Long previous=read(d,run);
			// Never checkpoint an obsolete client/worker result after another client or restore changed the head.
			BankRun head=codec.decode(BankStorageFiles.readText(d.joinSegment("current.json")),run.getCharacter());
			if(!head.getRevision().equals(run.getRevision())||candidate==null||previous!=null&&candidate<=previous){return previous;}
			JsonObject p=new JsonObject();p.addProperty("character",run.getCharacter());p.addProperty("run",run.getRunId().toString());p.addProperty("gp",candidate);
			p.addProperty("from",file.exists()?BankRunCodec.str(codec.payload(BankStorageFiles.readText(file),1),"from"):Instant.now().toString());
			Filepath pending=d.joinSegment("peak-"+run.getRunId()+"-pending-"+UUID.randomUUID()+".json");BankStorageFiles.writeNew(pending,codec.envelope(p,1));
			if(file.exists())
			{
				Filepath backup=d.joinSegment("peak-"+run.getRunId()+"-backup-pending-"+UUID.randomUUID()+".json");BankStorageFiles.writeNew(backup,BankStorageFiles.readText(file));
				backup.moveTo(d.joinSegment("peak-"+run.getRunId()+"-backup.json"),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);
			}
			pending.moveTo(file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);return read(d,run);
		}
		catch(OverlappingFileLockException ex){throw new SaveException("Progress is being saved.");}
	}
	Long read(Filepath directory,BankRun run) throws IOException
	{
		Filepath file=directory.joinSegment(file(run));
		if(!file.exists())
		{
			try(java.util.stream.Stream<Filepath> files=directory.walk(1)){if(files.anyMatch(f->f.getFileName().startsWith("peak-"+run.getRunId()+"-"))){throw new SaveException("Peak checkpoint is missing; recovery files were preserved.");}}
			return null;
		}
		try
		{
			JsonObject p=codec.payload(BankStorageFiles.readText(file),1);BankRunCodec.keys(p,"character","run","gp","from");
			long gp=BankRunCodec.number(p.get("gp"));Instant.parse(BankRunCodec.str(p,"from"));
			if(gp<0||!run.getCharacter().equals(BankRunCodec.str(p,"character"))||!run.getRunId().toString().equals(BankRunCodec.str(p,"run"))){throw new IllegalArgumentException();}return gp;
		}
		catch(RuntimeException ex){throw new SaveException("Peak Progress Value could not be verified; its files were preserved.");}
	}
	private static String file(BankRun run){return "peak-"+run.getRunId()+".json";}
}

package com.fromscratch.persistence;

import com.fromscratch.playtime.Playtime;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.nio.channels.*;
import java.nio.file.*;
import java.time.Instant;
import java.util.*;
import javax.inject.*;
import net.runelite.client.util.Filepath;

/** Small run-scoped forced checkpoint. Does not migrate or rewrite any bank save or journal. Worker only. */
@Singleton
public final class PlaytimeRepository
{
	private final BankRunCodec codec;
	@Inject public PlaytimeRepository(BankRunCodec codec) { this.codec=codec; }
	public Playtime load(Filepath root,String character,UUID run) throws IOException
	{
		return locked(root,character,run,d ->
		{
			Filepath current=d.joinSegment(file(run));
			if(current.exists()) { return read(current,character,run); }
			try(java.util.stream.Stream<Filepath> files=d.walk(1))
			{
				if(files.anyMatch(f->f.getFileName().startsWith("playtime-"+run+"-")))
				{ throw new SaveException("Playtime checkpoint is missing. Recovery files were preserved; restore the playtime backup before retrying."); }
			}
			Playtime initial=new Playtime(character,run,UUID.randomUUID(),Instant.now(),0);
			write(d,initial);return initial;
		});
	}
	/** A conflicting client wins: return its counter, discarding this overlapping interval rather than counting twice. */
	public Playtime add(Filepath root,Playtime expected,long ticks,UUID batch) throws IOException
	{
		if(ticks<0) { throw new IllegalArgumentException("Negative playtime interval"); }
		return locked(root,expected.getCharacter(),expected.getRun(),d ->
		{
			Playtime current=read(d.joinSegment(file(expected.getRun())),expected.getCharacter(),expected.getRun());
			if(current.getRevision().equals(batch)||!current.getRevision().equals(expected.getRevision())) { return current; }
			Playtime next=new Playtime(current.getCharacter(),current.getRun(),batch,current.getMeasuredFrom(),Math.addExact(current.getTicks(),ticks));
			write(d,next);return next;
		});
	}
	Playtime read(Filepath file,String character,UUID run) throws IOException
	{
		try
		{
			JsonObject p=codec.payload(BankStorageFiles.readText(file),1);
			BankRunCodec.keys(p,"character","run","revision","from","ticks");
			Playtime state=new Playtime(BankRunCodec.str(p,"character"),UUID.fromString(BankRunCodec.str(p,"run")),UUID.fromString(BankRunCodec.str(p,"revision")),Instant.parse(BankRunCodec.str(p,"from")),BankRunCodec.number(p.get("ticks")));
			if(!character.equals(state.getCharacter())||!run.equals(state.getRun())) { throw new IllegalArgumentException("Identity mismatch"); }
			return state;
		}
		catch(RuntimeException ex) { throw new SaveException("Playtime could not be verified. Its checkpoint and backup were preserved."); }
	}
	private void write(Filepath d,Playtime state) throws IOException
	{
		JsonObject p=new JsonObject();p.addProperty("character",state.getCharacter());p.addProperty("run",state.getRun().toString());
		p.addProperty("revision",state.getRevision().toString());p.addProperty("from",state.getMeasuredFrom().toString());p.addProperty("ticks",state.getTicks());
		Filepath current=d.joinSegment(file(state.getRun()));
		Filepath pending=d.joinSegment("playtime-"+state.getRun()+"-pending-"+state.getRevision()+".json");
		BankStorageFiles.writeNew(pending,codec.envelope(p,1));
		// Keep exact previous bytes. Atomic replacement failure leaves both the original and forced candidate.
		if(current.exists())
		{
			Filepath backup=d.joinSegment("playtime-"+state.getRun()+"-backup.json");
			Filepath backupPending=d.joinSegment("playtime-"+state.getRun()+"-backup-"+state.getRevision()+".json");
			BankStorageFiles.writeNew(backupPending,BankStorageFiles.readText(current));
			backupPending.moveTo(backup,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);
		}
		pending.moveTo(current,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);
		if(!read(current,state.getCharacter(),state.getRun()).equals(state)) { throw new SaveException("Playtime verification failed; recovery files were retained."); }
	}
	private static String file(UUID run) { return "playtime-"+run+".json"; }
	private <T>T locked(Filepath root,String character,UUID run,Work<T> work) throws IOException
	{
		if(character==null||!character.matches("[a-f0-9]{64}")||run==null) { throw new SaveException("Unverified playtime identity"); }
		// Separate directory: economic migration/reset archives cannot race this independent counter.
		// Run-specific old counters remain recoverable after reset and cannot attach to the new run.
		Filepath base=root.join("characters",character);Filepath locks=base.joinSegment("playtime");locks.createDirectories();
		try(FileChannel channel=locks.joinSegment("playtime.lock").openFileChannel(StandardOpenOption.CREATE,StandardOpenOption.WRITE);FileLock lock=channel.tryLock())
		{
			if(lock==null) { throw new SaveException("Another client is saving playtime. No interval was added."); }
			Filepath d=ProgressBackup.directory(base,codec).joinSegment("playtime");d.createDirectories();
			return work.run(d);
		}
		catch(OverlappingFileLockException ex) { throw new SaveException("Another client is saving playtime. No interval was added."); }
	}
	@FunctionalInterface private interface Work<T> { T run(Filepath directory) throws IOException; }
}

