			}
			if(!reviewed){bank=new TreeMap<>(ordinary);stored=new TreeMap<>(old.getBalances());remainder=new TreeMap<>(old.getRemainder());bo.clear();bvout.clear();so.clear();svout.clear();exclusions.clear();}
		}
		if(!reviewed&&input.getReview()==null)
		{
			// Unknown store stock must not turn a deposit from that store into earned bank bottles.
			// Preserve existing bank doses and once-consumed same-session returns; other gains await review.
			for(PotionType type:types.values())
			{
				int id=type.getId();long delta=Math.subtractExact(type.doses(physical),type.doses(run.getPhysical())),virtual=old.bankBalance(type,run.getBalances());
				if(delta<0){long q=Math.negateExact(delta);add(bo,id,q);add(bvout,id,Math.min(Math.max(0,virtual),q));virtual=Math.addExact(virtual,delta);}
				else if(delta>0){long q=Math.min(delta,bo.getOrDefault(id,0L));virtual=Math.addExact(virtual,q);take(bo,bvout,id,q,Math.min(q,bvout.getOrDefault(id,0L)));}
				allocate(type,virtual,physical,bank,remainder);for(int item:type.getItems().keySet()){long change=Math.subtractExact(bank.getOrDefault(item,0L),run.balance(item));if(change>0){exclusions.put(item,change);}}
			}
		}
		PotionState state=new PotionState(types,fresh&&first?seen.getQuantities():old.getInitial(),seen.getQuantities(),stored,remainder,bo,bvout,so,svout,fresh?seen.getAt():old.getObservedAt(),session,fresh?session:old.getObservedSession(),reviewed);
		return new Result(state,bank,exclusions);
	}
	private static void add(Map<Integer,Long> map,int id,long n){map.put(id,Math.addExact(map.getOrDefault(id,0L),n));}
	private static void take(Map<Integer,Long> units,Map<Integer,Long> owned,int id,long q,long v){units.put(id,units.getOrDefault(id,0L)-q);owned.put(id,owned.getOrDefault(id,0L)-v);}
	private static void allocate(PotionType type,long target,Map<Integer,Long> physical,Map<Integer,Long> bank,Map<Integer,Long> remainder)
	{
		if(type.doses(bank)==target&&remainder.getOrDefault(type.getId(),0L)==0){return;}
		if(target>type.doses(physical)){throw new IllegalArgumentException("Virtual potion doses exceed the physical bank.");}
		Map<Integer,Long> prior=new TreeMap<>(bank);for(int id:type.getItems().keySet()){bank.remove(id);}
		List<Integer> ids=new ArrayList<>(type.getItems().keySet());ids.sort(Comparator.<Integer>comparingInt(type.getItems()::get).reversed());long left=target;
		if(left>=0)
		{
			for(int pass=0;pass<2;pass++){for(int id:ids){int dose=type.getItems().get(id);long cap=pass==0?Math.max(0,prior.getOrDefault(id,0L)):physical.getOrDefault(id,0L)-bank.getOrDefault(id,0L);long q=Math.min(Math.min(cap,physical.getOrDefault(id,0L)-bank.getOrDefault(id,0L)),left/dose);if(q>0){add(bank,id,q);left-=q*dose;}}}
		}
		else{int id=ids.get(ids.size()-1),dose=type.getItems().get(id);long q=Math.floorDiv(left,dose);bank.put(id,q);left=Math.subtractExact(left,Math.multiplyExact(q,dose));}
		remainder.put(type.getId(),left);
	}
}

package com.fromscratch.potion;

import java.time.Instant;
import java.util.*;
import lombok.Value;

/** A complete, character-scoped value copy. Missing data is never an empty store. */
@Value
public class PotionObservation
{
	boolean verified;
	Map<Integer,PotionType> types;
	Map<Integer,Long> quantities;
	Instant at;
	public PotionObservation(boolean verified,Map<Integer,PotionType> types,Map<Integer,Long> quantities,Instant at)
	{
		this.verified=verified;this.types=Collections.unmodifiableMap(new TreeMap<>(types));this.quantities=PotionState.numbers(quantities,true);this.at=Objects.requireNonNull(at);
		if(types.size()>256||!types.keySet().containsAll(this.quantities.keySet())){throw new IllegalArgumentException("Incomplete potion observation");}
		Set<Integer> ids=new HashSet<>();for(PotionType type:types.values()){for(int id:type.getItems().keySet()){if(!ids.add(id)){throw new IllegalArgumentException("Ambiguous potion mapping");}}}
	}
	public static PotionObservation unknown(){return new PotionObservation(false,Collections.emptyMap(),Collections.emptyMap(),Instant.EPOCH);}
	public static PotionObservation unavailableStore(){return new PotionObservation(true,Collections.emptyMap(),Collections.emptyMap(),Instant.EPOCH);}
}

package com.fromscratch.potion;

import java.time.Instant;
import java.util.*;
import lombok.Value;

/** Part of the same atomic bank checkpoint, never a separately saved quantity ledger. */
@Value
public class PotionState
{
	Map<Integer,PotionType> types;
	Map<Integer,Long> initial,physical,balances,remainder,bankOut,bankOwnedOut,storeOut,storeOwnedOut;
	Instant observedAt;
	UUID session;
	UUID observedSession;
	boolean reviewed;
	public PotionState(Map<Integer,PotionType> types,Map<Integer,Long> initial,Map<Integer,Long> physical,Map<Integer,Long> balances,Map<Integer,Long> remainder,Map<Integer,Long> bankOut,Map<Integer,Long> bankOwnedOut,Map<Integer,Long> storeOut,Map<Integer,Long> storeOwnedOut,Instant observedAt,UUID session,boolean reviewed)
	{this(types,initial,physical,balances,remainder,bankOut,bankOwnedOut,storeOut,storeOwnedOut,observedAt,session,session,reviewed);}
	public PotionState(Map<Integer,PotionType> types,Map<Integer,Long> initial,Map<Integer,Long> physical,Map<Integer,Long> balances,Map<Integer,Long> remainder,Map<Integer,Long> bankOut,Map<Integer,Long> bankOwnedOut,Map<Integer,Long> storeOut,Map<Integer,Long> storeOwnedOut,Instant observedAt,UUID session,UUID observedSession,boolean reviewed)
	{
		this.types=Collections.unmodifiableMap(new TreeMap<>(types));this.initial=numbers(initial,true);this.physical=numbers(physical,true);this.balances=numbers(balances,false);this.remainder=numbers(remainder,true);this.bankOut=numbers(bankOut,true);this.bankOwnedOut=numbers(bankOwnedOut,true);this.storeOut=numbers(storeOut,true);this.storeOwnedOut=numbers(storeOwnedOut,true);this.observedAt=observedAt;this.session=session;this.observedSession=observedSession;this.reviewed=reviewed;
		for(Map<Integer,Long> map:Arrays.asList(this.initial,this.physical,this.balances,this.remainder,this.bankOut,this.bankOwnedOut,this.storeOut,this.storeOwnedOut)){if(!types.keySet().containsAll(map.keySet())){throw new IllegalArgumentException("Unknown stored potion");}}
		for(int id:types.keySet()){if(reviewed&&this.balances.getOrDefault(id,0L)>this.physical.getOrDefault(id,0L)||this.bankOwnedOut.getOrDefault(id,0L)>this.bankOut.getOrDefault(id,0L)||this.storeOwnedOut.getOrDefault(id,0L)>this.storeOut.getOrDefault(id,0L)||this.remainder.getOrDefault(id,0L)>3){throw new IllegalArgumentException("Invalid stored potion balance");}}
		if(types.size()>256||observedAt!=null&&session==null||(observedAt==null)!=(observedSession==null)||reviewed&&observedAt==null){throw new IllegalArgumentException("Invalid potion checkpoint");}
	}
	public static Map<Integer,Long> numbers(Map<Integer,Long> source,boolean positive)
	{TreeMap<Integer,Long> result=new TreeMap<>();source.forEach((id,q)->{if(id<0||q==null||q==Long.MIN_VALUE||positive&&q<0){throw new IllegalArgumentException("Invalid potion quantity");}if(q!=0){result.put(id,q);}});return Collections.unmodifiableMap(result);}
	public static PotionState unknown(){return new PotionState(Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),null,null,false);}
	public static PotionState baseline(PotionObservation observation,UUID session)
	{if(!observation.isVerified()){throw new IllegalArgumentException("Open Potion Storage before starting, then return to your full bank.");}return new PotionState(observation.getTypes(),observation.getQuantities(),observation.getQuantities(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),Collections.emptyMap(),observation.getAt(),session,true);}
	public long bankBalance(PotionType type,Map<Integer,Long> bank){return Math.addExact(type.doses(bank),remainder.getOrDefault(type.getId(),0L));}
	public long balance(int id){return balances.getOrDefault(id,0L);}
	public PotionState corrected(Set<Integer> itemIds)
	{
		Set<Integer> affected=new HashSet<>();types.forEach((id,type)->{if(!Collections.disjoint(type.getItems().keySet(),itemIds)){affected.add(id);}});if(affected.isEmpty()){return this;}
		List<Map<Integer,Long>> copies=new ArrayList<>();for(Map<Integer,Long> map:Arrays.asList(remainder,bankOut,bankOwnedOut,storeOut,storeOwnedOut)){Map<Integer,Long> copy=new TreeMap<>(map);affected.forEach(copy::remove);copies.add(copy);}
		return new PotionState(types,initial,physical,balances,copies.get(0),copies.get(1),copies.get(2),copies.get(3),copies.get(4),observedAt,session,observedSession,reviewed);
	}
}

package com.fromscratch.potion;

import java.util.*;
import lombok.Value;

/** Cache-derived storage enum identity; units are doses, or items for unfinished/single-unit entries. */
@Value
public class PotionType
{
	int id;
	String name;
	boolean unfinished;
	Map<Integer,Integer> items;
	public PotionType(int id,String name,boolean unfinished,Map<Integer,Integer> items)
	{
		if(id<0||name==null||name.length()>150||items.isEmpty()||items.size()>4){throw new IllegalArgumentException("Invalid potion mapping");}
		TreeMap<Integer,Integer> copy=new TreeMap<>();items.forEach((item,doses)->{if(item<0||doses<1||doses>4||unfinished&&doses!=1){throw new IllegalArgumentException("Invalid potion units");}copy.put(item,doses);});
		this.id=id;this.name=name;this.unfinished=unfinished;this.items=Collections.unmodifiableMap(copy);
	}
	public int displayId(){return items.entrySet().stream().max(Map.Entry.comparingByValue()).get().getKey();}
	public String unit(){return unfinished||items.size()==1&&items.values().iterator().next()==1?"items":"doses";}
	public long doses(Map<Integer,Long> quantities){long total=0;for(Map.Entry<Integer,Integer> e:items.entrySet()){total=Math.addExact(total,Math.multiplyExact(quantities.getOrDefault(e.getKey(),0L),e.getValue()));}return total;}
}

