/** Isolated real ledger/persistence and production observation boundary. No game or real profiles. */
public class PotionStorageTest
{
	private static final int TYPE=1,P4=ItemID._4DOSEPRAYERRESTORE,P3=ItemID._3DOSEPRAYERRESTORE,P2=ItemID._2DOSEPRAYERRESTORE,P1=ItemID._1DOSEPRAYERRESTORE;
	private static final PotionType PRAYER=new PotionType(TYPE,"Prayer potion",false,new TreeMap<Integer,Integer>(){{put(P1,1);put(P2,2);put(P3,3);put(P4,4);}});
	private final UUID session=UUID.randomUUID();private long clock;
	@Rule public TemporaryFolder temp=new TemporaryFolder();
	private PotionObservation store(long q){return new PotionObservation(true,Collections.singletonMap(TYPE,PRAYER),q==0?Collections.emptyMap():Collections.singletonMap(TYPE,q),SnapshotFixtures.TIME.plusSeconds(clock++));}
	private ContainerSnapshot bank(int id,long q){return new ContainerSnapshot(q==0?Collections.emptyMap():Collections.singletonMap(id,q),q==0?0:1);}
	private BankRun start(long physicalBank,long physicalStore){return BankEngine.start(SnapshotFixtures.CHARACTER_A,null,bank(P4,physicalBank),true,session,SnapshotFixtures.TIME,store(physicalStore));}
	private BankRun move(BankRun run,int item,long bank,long storage){return BankEngine.observe(run,bank(item,bank),session,SnapshotFixtures.TIME.plusSeconds(clock++),null,Collections.emptyMap(),store(storage));}
	private BankRun earned(){return move(start(0,0),P4,3,0);}
	@Test public void setupProgressesFromBankToStorageWithoutRedundantCards() throws Exception
	{
		javax.swing.SwingUtilities.invokeAndWait(()->{
