			mode.potionStorageSelected();access.coreClose();access.nativeTab=15;mode.bankBuilt();source.storageOpen=true;source.fullBank=false;source.items=null;source.observer.changed();source.observer.tick();controller.tick();worker.runAll();assertEquals(earned,repo.load(root,source.character).get());assertNotNull(controller.currentRun());assertEquals(3,overlay.getProjection().balance(potion,false));
			source.items=new net.runelite.api.Item[]{new net.runelite.api.Item(potion,3)};source.observer.tick();controller.tick();worker.runAll();source.storageOpen=false;source.fullBank=true;access.nativeTab=0;mode.bankBuilt();controller.tick();worker.runAll();assertTrue(access.predicate.contains(potion));assertEquals(opened,access.opened);assertFalse(mode.isFaulted());
			source.character=null;source.observer.reset();controller.tick();worker.runAll();source.character=SnapshotFixtures.CHARACTER_A;source.observer.reset();controller.tick();worker.runAll();source.observer.tick();controller.tick();worker.runAll();assertEquals(3,repo.load(root,source.character).get().balance(potion));assertTrue(access.predicate.contains(potion));assertTrue(alerts.isEmpty());
		}finally{controller.stop();mode.stop();}
	}
	@Test public void disablingWhilePotionStorageOpenDoesNotResumeFilter()
	{
		mode.setEnabled(true);mode.update(run(1),true);mode.potionStorageSelected();access.coreClose();access.nativeTab=15;mode.bankBuilt();mode.setEnabled(false);access.nativeTab=0;mode.bankBuilt();assertNull(access.predicate);int[] untouched={0};mode.script("bankBuildTab",untouched,1);assertEquals(0,untouched[0]);assertFalse(mode.isFaulted());
	}
	@Test public void closingPotionStorageThenReopeningBankRestoresSavedPreference()
	{
		BankRun run=BankEngine.observe(run(1),bank(2),UUID.randomUUID(),SnapshotFixtures.TIME);mode.setEnabled(true);mode.update(run,true);mode.potionStorageSelected();access.coreClose();access.nativeTab=15;mode.bankBuilt();mode.bankClosed();access.nativeTab=0;mode.update(run,true);assertNotNull(access.predicate);assertTrue(access.predicate.contains(SHIELD));assertFalse(mode.isFaulted());assertEquals(2,access.opened);
	}


	@Test public void searchUsesNativeResultIntersectionAcrossRepeatedOpenClearAndTabChanges()
	{
		BankRun a=run(1);a=BankEngine.observe(a,bank(3),UUID.randomUUID(),SnapshotFixtures.TIME);mode.setEnabled(true);mode.update(a,true);List<Boolean> choices=new ArrayList<>();mode.fullBankSelected(()->choices.add(false));
		for(int i=0;i<50;i++){
			mode.searchSelected();access.coreClose();mode.bankBuilt();
			for(int nativeResult:new int[]{0,1}){int[] owned={nativeResult,SHIELD};mode.script("bankSearchFilter",owned,2);assertEquals(nativeResult,owned[0]);int[] legacy={nativeResult,OTHER};mode.script("bankSearchFilter",legacy,2);assertEquals(0,legacy[0]);}
			mode.nativeTabSelected();access.nativeTab=i%2;mode.bankBuilt();mode.searchSelected();mode.bankBuilt();
		}
		assertTrue(choices.isEmpty());assertEquals(1,access.opened);assertFalse(mode.isFaulted());
		mode.setEnabled(false);int[] full={1,OTHER};mode.script("bankSearchFilter",full,2);assertEquals(1,full[0]);mode.searchSelected();assertEquals(1,access.opened);
	}
	@Test public void searchDoesNotOverrideIndependentTagOrReactivateDuringPotionStorage()
	{
		mode.setEnabled(true);mode.update(run(1),true);mode.searchSelected();access.coreClose();mode.bankBuilt();
		mode.potionStorageSelected();access.nativeTab=15;int[] storage={1,OTHER};mode.script("bankSearchFilter",storage,2);assertEquals(1,storage[0]);mode.bankBuilt();
		access.nativeTab=0;mode.bankBuilt();mode.update(run(1),true);mode.searchSelected();access.active="my_saved_tag";mode.bankBuilt();assertEquals("my_saved_tag",access.active);int[] user={1,OTHER};mode.script("bankSearchFilter",user,2);assertEquals(1,user[0]);
	}
}

package com.fromscratch.bank;

import com.fromscratch.SnapshotFixtures;
import com.fromscratch.overlay.*;
import com.fromscratch.persistence.*;
import com.fromscratch.wealth.*;
import java.util.*;
import java.util.concurrent.atomic.*;
import javax.swing.*;
import net.runelite.client.util.Filepath;
import org.junit.*;
import org.junit.rules.TemporaryFolder;
import static org.junit.Assert.*;
import static com.fromscratch.bank.BankFixtures.*;

/** Real observer/controller/Filepath commit/render projection/dashboard path, with a synthetic bulk price feed. */
public class WealthPipelineTest
{
	@Rule public TemporaryFolder temporary=new TemporaryFolder();
	private Filepath root;private BankRepository repository;private Source source;private Worker worker;private BankController controller;
	private final BankOverlayState overlay=new BankOverlayState();private final List<BankView> views=new ArrayList<>();
	private PriceService prices;private final AtomicLong price=new AtomicLong(100);private final AtomicInteger requests=new AtomicInteger();
	@Before public void setup()
	{
		root=Filepath.Unchecked.getRooted(temporary.getRoot().toPath());repository=new BankRepository(new BankRunCodec(SnapshotFixtures.gson()),SnapshotFixtures.codec());source=new Source();
		prices=new PriceService(()->{requests.incrementAndGet();return Collections.singletonMap(SHIELD,price.get());},()->SnapshotFixtures.TIME);prices.refresh();overlay.enable();launch();settle();controller.startRun(true,null,true);worker.runAll();settle();
	}
	@After public void stop(){controller.stop();}
	private void launch(){worker=new Worker();controller=new BankController(source,repository,Runnable::run,v->{views.add(v);overlay.updateBank(v);},prices);controller.start(()->root,worker);worker.runAll();}
	private void settle(){source.observer.tick();controller.tick();worker.runAll();source.observer.tick();controller.tick();worker.runAll();}
	private void change(long n){source.quantity(n);settle();}
	private BankView view(){return views.get(views.size()-1);}
	private BankRun saved()throws Exception{return repository.load(root,SnapshotFixtures.CHARACTER_A).get();}
	@Test public void automaticDepositCommitsHistoricalAndCurrentValueWithOverlay()throws Exception{change(3);assertEquals(200,saved().getFinancial().getGainedGp());assertEquals("2",overlay.getProjection().label(SHIELD));assertEquals(Long.valueOf(200),view().getValuation().getSubtotalGp());assertEquals(saved().getRevision(),view().getValuation().getRevision());}
	@Test public void withdrawalAndRedepositStayOneRecognizedGain()throws Exception{change(3);change(2);change(3);assertEquals(200,saved().getFinancial().getGainedGp());assertEquals(1,saved().getFinancial().getEventCount());assertEquals("2",overlay.getProjection().label(SHIELD));}
	@Test public void legacyReturnCannotManufactureGainOrExpense()throws Exception{change(0);assertEquals("-1",overlay.getProjection().label(SHIELD));change(1);assertEquals(0,saved().getFinancial().getGainedGp());assertEquals(0,saved().getFinancial().getExpenseRecords());}
	@Test public void finalWithdrawalKeepsNegativeMarketValueAcrossPlaceholderAndRestart()throws Exception
	{
		// A second synthetic run establishes four legacy copies, without resetting any real save.
		controller.stop(); source.character=SnapshotFixtures.CHARACTER_B; source.quantity(4); source.observer.reset(); launch(); settle(); controller.startRun(true,null,true); worker.runAll(); settle();
		source.quantity(1); settle(); assertEquals(Long.valueOf(-300),view().getValuation().getSubtotalGp());
		source.placeholders.add(net.runelite.api.gameval.ItemID.Placeholder.WOODEN_SHIELD);
		source.items=new net.runelite.api.Item[]{new net.runelite.api.Item(net.runelite.api.gameval.ItemID.Placeholder.WOODEN_SHIELD,0)};source.observer.changed();settle();
		assertEquals(-4,view().getRun().balance(SHIELD));assertEquals(Long.valueOf(-400),view().getValuation().getSubtotalGp());
		FinancialState financial=view().getRun().getFinancial();controller.stop();source.observer.reset();launch();settle();
		assertEquals(-4,view().getRun().balance(SHIELD));assertEquals(Long.valueOf(-400),view().getValuation().getSubtotalGp());assertEquals(financial,view().getRun().getFinancial());
	}
	@Test public void correctionUpdatesCounterWithoutManufacturingIncome()throws Exception{controller.correct(view().getRun().getRevision(),SHIELD,1);worker.runAll();assertEquals("1",overlay.getProjection().label(SHIELD));assertEquals(0,saved().getFinancial().getGainedGp());change(0);change(1);assertEquals(0,saved().getFinancial().getGainedGp());}
	@Test public void priceRefreshUpdatesDashboardWithoutChangingCheckpointOrHistory()throws Exception{change(2);BankRun before=saved();price.set(200);prices.refresh();settle();assertEquals(Long.valueOf(200),view().getValuation().getSubtotalGp());assertEquals(100,view().getRun().getFinancial().getGainedGp());assertEquals(before,saved());assertEquals(2,requests.get());}
	@Test public void bankPipelineNeverFetchesPriceFeedDuringRapidChanges()throws Exception{for(int i=0;i<30;i++){change(2);change(1);}assertEquals(1,requests.get());assertEquals(100,saved().getFinancial().getGainedGp());assertEquals(0,saved().balance(SHIELD));}
	@Test public void restartDoesNotReplayFinancialEvents()throws Exception{change(3);BankRun before=saved();controller.stop();source.observer.reset();launch();settle();assertEquals(before.getFinancial(),saved().getFinancial());assertEquals(before.getRunId(),saved().getRunId());assertEquals("2",overlay.getProjection().label(SHIELD));}
	@Test public void returningOfflineBankGainRecognizesOnlyNewHighWater()throws Exception{change(3);controller.stop();source.quantity(4);source.observer.reset();launch();settle();assertEquals(300,saved().getFinancial().getGainedGp());assertEquals("3",overlay.getProjection().label(SHIELD));}
	@Test public void noProgressPublishesBeforeDurabilityAcknowledgment()throws Exception{source.quantity(2);source.observer.tick();controller.tick();assertEquals("0",overlay.getProjection().label(SHIELD));assertEquals(0,saved().getFinancial().getGainedGp());worker.runAll();assertEquals("1",overlay.getProjection().label(SHIELD));assertEquals(100,saved().getFinancial().getGainedGp());}
	@Test public void failedSavePreservesFinancialAnchorThenRetryCreditsExactlyOnce()throws Exception
	{
		controller.stop();AtomicBoolean fail=new AtomicBoolean();worker=new Worker();controller=new BankController(source,repository,Runnable::run,v->{views.add(v);overlay.updateBank(v);},prices);controller.start(()->{if(fail.get()){throw new java.io.IOException("Synthetic storage failure");}return root;},worker);worker.runAll();settle();BankRun before=saved();fail.set(true);change(2);assertTrue(view().isError());assertEquals(before,saved());fail.set(false);controller.retry();worker.runAll();settle();assertEquals(100,saved().getFinancial().getGainedGp());assertEquals("1",overlay.getProjection().label(SHIELD));
	}
	@Test public void explicitExpenseIsDurableWithoutChangingBankBalances()throws Exception{change(2);Map<Integer,Long> before=saved().getBalances();controller.recordExpense(view().getRun().getRevision(),300,"Verified death fee");worker.runAll();assertEquals(300,saved().getFinancial().getExpenseGp());assertEquals(before,saved().getBalances());assertEquals("1",overlay.getProjection().label(SHIELD));}
	@Test public void staleExpenseIntentCannotOverwriteNewerProgress()throws Exception{UUID old=view().getRun().getRevision();change(2);controller.recordExpense(old,300,"Fee");worker.runAll();assertEquals(0,saved().getFinancial().getExpenseGp());assertEquals(100,saved().getFinancial().getGainedGp());}
	@Test public void characterSwitchDoesNotMixFinancialState()throws Exception{change(2);source.character=SnapshotFixtures.CHARACTER_B;source.observer.reset();controller.tick();worker.runAll();settle();assertNull(view().getRun());assertNull(overlay.getProjection());assertEquals(100,repository.load(root,SnapshotFixtures.CHARACTER_A).get().getFinancial().getGainedGp());}
	@Test public void dashboardShowsCommittedWealthAndManualCorrectionPurpose()throws Exception
	{
		change(3);BankView committed=view();SwingUtilities.invokeAndWait(()->{BankPanel panel=new BankPanel();panel.render(committed,controller);JPanel grid=(JPanel)BankPolishTest.all(panel).stream().filter(c->"statisticTiles".equals(c.getName())).findFirst().get();assertEquals(2,((java.awt.GridLayout)grid.getLayout()).getColumns());assertEquals(6,grid.getComponentCount());java.util.List<String> labels=new ArrayList<>();for(java.awt.Component c:BankPolishTest.all(panel)){if(c instanceof JLabel){labels.add(((JLabel)c).getText());}}String text=String.join(" ",labels);assertTrue(text.contains("200 GP"));assertTrue(text.contains("Bank GP"));assertTrue(text.contains("0 GP"));assertFalse(text.contains("Coming soon"));assertTrue(text.contains("Manual<br>Bank<br>Corrections"));assertTrue(text.contains("Fix an incorrect"));assertEquals("Correct an incorrectly recorded virtual balance.",BankCorrectionDialog.PURPOSE);});
	}
	@Test public void pricedSubtotalFitsNarrowTilesAndExplainsUnknowns()throws Exception
	{
		change(2);BankView committed=view();BankValuation partial=new BankValuation(committed.getRun().getRevision(),-1_740_000L,3,1,SnapshotFixtures.TIME,1);BankView display=new BankView(committed.getRun(),committed.getObservation(),committed.getNames(),false,false,committed.getMessage(),null,partial);
		SwingUtilities.invokeAndWait(()->{BankPanel panel=new BankPanel();panel.render(display,controller);panel.setSize(225,960);layout(panel);JLabel subtotal=(JLabel)BankPolishTest.all(panel).stream().filter(c->c instanceof JLabel&&((JLabel)c).getText()!=null&&((JLabel)c).getText().contains("Priced subtotal")).findFirst().get();assertTrue(BankPolishTest.all(panel).stream().anyMatch(c->c instanceof JLabel&&"~-1740K GP*".equals(((JLabel)c).getText())));assertTrue(subtotal.getToolTipText().contains("3 item types have no available price"));assertTrue(subtotal.getToolTipText().contains("1 item type uses an older price"));assertTrue(subtotal.getPreferredSize().height<=subtotal.getHeight());assertTrue(subtotal.getPreferredSize().width<=subtotal.getWidth());try{java.awt.image.BufferedImage image=new java.awt.image.BufferedImage(225,960,java.awt.image.BufferedImage.TYPE_INT_RGB);java.awt.Graphics2D g=image.createGraphics();panel.paint(g);g.dispose();java.nio.file.Path file=java.nio.file.Paths.get("build/reports/dashboard-wealth.png");java.nio.file.Files.createDirectories(file.getParent());javax.imageio.ImageIO.write(image,"png",file.toFile());}catch(java.io.IOException ex){throw new AssertionError(ex);}});
	}
	private static void layout(java.awt.Container parent){parent.doLayout();for(java.awt.Component c:parent.getComponents()){if(c instanceof java.awt.Container){layout((java.awt.Container)c);}}}
}

package com.fromscratch.buyback;

import com.fromscratch.SnapshotFixtures;
import com.fromscratch.bank.*;
import com.fromscratch.model.ContainerSnapshot;
import com.fromscratch.wealth.*;
import java.util.*;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

/** Explicit copy budgets, prices, family substitutions and zero physical game mutations. */
public class BuybackModelTest
{
	private static final int P=ItemID.BH_RUNE_POUCH,D=ItemID.DIVINE_RUNE_POUCH,F=ItemID.TZHAAR_CAPE_FIRE,C=ItemID.COINS;
	public static ContainerSnapshot bank(int...ids){Map<Integer,Long> q=new TreeMap<>();for(int id:ids){q.merge(id,1L,Math::addExact);}return new ContainerSnapshot(q,ids.length);}
	public static BankRun funded(long gp,int...legacy){BankRun r=BankEngine.start(SnapshotFixtures.CHARACTER_A,null,bank(legacy),true,UUID.randomUUID(),SnapshotFixtures.TIME);Map<Integer,Long> q=new TreeMap<>(r.getPhysical());q.put(C,gp);r=BankEngine.observe(r,new ContainerSnapshot(q,q.size()),UUID.randomUUID(),SnapshotFixtures.TIME);return BuybackCatalog.variants("rune_pouch_family").keySet().stream().anyMatch(q::containsKey)?emptyPouch(r):r;}
	public static BankRun emptyPouch(BankRun r){return BankEngine.pouch(r,new com.fromscratch.pouch.PouchAction(com.fromscratch.pouch.PouchAction.Kind.FINISH,Collections.emptyMap(),true,false,"Fixture player explicitly verified empty pouch and accounted for earlier deposits."),UUID.randomUUID(),SnapshotFixtures.TIME,Collections.emptyMap());}
 public static BankRun buy(BankRun r,String id){if(id.equals("looting_bag_family")){int bag=BuybackCatalog.variants(id).keySet().stream().filter(i->r.physical(i)>0).findFirst().orElse(ItemID.LOOTING_BAG);return BankEngine.buyBag(r,UUID.randomUUID(),UUID.randomUUID(),SnapshotFixtures.TIME,new BagObservation(bag,Collections.emptyMap(),Collections.emptyMap(),SnapshotFixtures.TIME));}int pouch=BuybackCatalog.variants("rune_pouch_family").keySet().stream().filter(i->r.physical(i)>0).findFirst().orElse(ItemID.BH_RUNE_POUCH);return BankEngine.buyback(r,id,UUID.randomUUID(),UUID.randomUUID(),SnapshotFixtures.TIME,new com.fromscratch.pouch.PouchObservation(true,Collections.emptyMap(),SnapshotFixtures.TIME,pouch));}
	private static BankRun observe(BankRun r,int...ids){Map<Integer,Long> q=new TreeMap<>(bank(ids).getQuantities());q.put(C,r.physical(C));return BankEngine.observe(r,new ContainerSnapshot(q,q.size()),UUID.randomUUID(),SnapshotFixtures.TIME);}
	private static long visible(BankRun r,int id){return BuybackEngine.balances(r).getOrDefault(id,0L);}
	private static void rejected(Runnable r){try{r.run();fail("Expected rejection");}catch(IllegalArgumentException|ArithmeticException expected){}}
	@Test public void fireCapeUsesExactlyOneMillionWithoutMovingPhysicalCoins(){BankRun a=funded(1500000,F),b=buy(a,"fire_cape");assertEquals(a.getPhysical(),b.getPhysical());assertEquals(a.getBalances(),b.getBalances());assertEquals(500000,BuybackEngine.available(b));assertEquals(1,visible(b,F));assertEquals(a.getFinancial(),b.getFinancial());}
	@Test public void insufficientFundsRejectEntirePurchase(){BankRun r=funded(999999,F);rejected(()->buy(r,"fire_cape"));assertTrue(r.getBuybacks().getPurchases().isEmpty());}
	@Test public void exactPriceLeavesNoAvailableGp(){assertEquals(0,BuybackEngine.available(buy(funded(1000000,F),"fire_cape")));}
	@Test public void missingPhysicalItemRejectsPurchase(){rejected(()->buy(funded(2000000),"fire_cape"));}
	@Test public void duplicateEntitlementRejectsEvenWithMoreMoney(){BankRun r=buy(funded(3000000,F),"fire_cape");rejected(()->buy(r,"fire_cape"));}
	@Test public void standardPouchQualifies(){assertEquals(1,visible(buy(funded(1000000,P),"rune_pouch_family"),P));}
	@Test public void divinePouchQualifies(){assertEquals(1,visible(buy(funded(1000000,D),"rune_pouch_family"),D));}
	@Test public void runeNoteDoesNotQualify(){rejected(()->buy(funded(2000000,ItemID.PROMISSORY_NOTE_RUNEPOUCH),"rune_pouch_family"));}
	@Test public void pouchFamilyIsOneRecordAndOneCopy(){BankRun r=buy(funded(2000000,P),"rune_pouch_family");assertEquals(1,r.getBuybacks().getEntitlements().size());assertEquals(1,r.getBuybacks().getPurchases().size());assertEquals(1000000,r.getBuybacks().getCommittedGp());assertEquals(1,visible(r,P)+visible(r,D));assertEquals(1,r.unlocked()-1);}
	@Test public void upgradingPouchPreservesPaidCopy(){BankRun r=observe(buy(funded(1000000,P),"rune_pouch_family"),D);assertEquals(0,visible(r,P));assertEquals(1,visible(r,D));assertEquals(1000000,r.getBuybacks().getCommittedGp());}
	@Test public void revertingPouchPreservesPaidCopy(){BankRun r=observe(buy(funded(1000000,D),"rune_pouch_family"),P);assertEquals(1,visible(r,P));assertEquals(0,visible(r,D));assertEquals(1,r.getBuybacks().getPurchases().size());}
	@Test public void withdrawingAndReturningDoesNotLoseEntitlement(){BankRun r=buy(funded(1000000,P),"rune_pouch_family");r=observe(r);assertEquals(0,visible(r,P));assertEquals(1,r.getBuybacks().getEntitlements().size());r=observe(r,P);assertEquals(1,visible(r,P));}
	@Test public void multiplePouchesDoNotGrantUnlimitedCopies(){BankRun r=funded(1000000,P,P,D);rejected(()->buy(r,"rune_pouch_family"));assertEquals(0,r.getBuybacks().getCommittedGp());}
	@Test public void genuinelyNewCopyRemainsIndependent(){BankRun r=buy(funded(1000000,P),"rune_pouch_family");r=observe(r,P,P);assertEquals(2,visible(r,P));assertEquals(1,r.getBuybacks().getEntitlements().size());}
	@Test public void naturalFireCapeDoesNotUnlockOriginalCopy(){BankRun r=observe(funded(1000000,F),F,F);assertEquals(1,visible(r,F));r=buy(r,"fire_cape");assertEquals(2,visible(r,F));}
	@Test public void newUntradeableAloneDoesNotRequireBuyback(){BankRun r=observe(funded(1000000),F);assertEquals(1,visible(r,F));rejected(()->buy(r,"fire_cape"));}
	@Test public void trouverPouchesAreTheSameSingleFamily(){BankRun r=buy(funded(1000000,ItemID.BH_RUNE_POUCH_TROUVER),"rune_pouch_family");r=observe(r,ItemID.DIVINE_RUNE_POUCH_TROUVER);assertEquals(1,visible(r,ItemID.DIVINE_RUNE_POUCH_TROUVER));assertEquals(4,BuybackCatalog.variants("rune_pouch_family").size());}
	@Test public void pouchRunesAreNeverTouched(){BankRun r=buy(funded(1000000,P,ItemID.MINDRUNE),"rune_pouch_family");assertEquals(0,visible(r,ItemID.MINDRUNE));assertEquals(1,r.physical(ItemID.MINDRUNE));}
	@Test public void infernalIsFifteenMillion(){assertEquals(15000000,BuybackCatalog.entry("infernal_cape").getPrice());}
	@Test public void ancientSceptreHasNoComponentFee(){assertEquals(500000,buy(funded(500000,ItemID.ANCIENT_SCEPTRE),"ancient_sceptre").getBuybacks().getCommittedGp());}
	@Test public void exclusionsAndArbitraryItemsAreNotCatalogEntries(){rejected(()->BuybackCatalog.entry("barrows_gloves"));rejected(()->BuybackCatalog.entry("royal_seed_pod"));rejected(()->BuybackCatalog.entry("wooden_shield"));}
	@Test public void regularVoidOneHelmTotalsTwoPointOneMillion(){long sum=0;for(String k:new String[]{"void_melee","void_top","void_robe","void_gloves"}){sum+=BuybackCatalog.entry(k).getPrice();}assertEquals(2100000,sum);}
	@Test public void eliteOneHelmTotalsFourPointOneMillion(){assertEquals(4100000,BuybackCatalog.entry("void_mage").getPrice()+BuybackCatalog.entry("elite_void_top").getPrice()+BuybackCatalog.entry("elite_void_robe").getPrice()+BuybackCatalog.entry("void_gloves").getPrice());}
	@Test public void eliteOutrightIncludesBase(){BankRun r=buy(funded(1800000,ItemID.ELITE_VOID_KNIGHT_TOP),"elite_void_top");assertEquals(1800000,r.getBuybacks().getCommittedGp());assertEquals(1,visible(r,ItemID.ELITE_VOID_KNIGHT_TOP));rejected(()->buy(r,"void_top"));}
	@Test public void eliteUpgradeChargesOnlyDifferenceAndSelectsEliteCopy(){BankRun r=buy(funded(1800000,ItemID.PEST_VOID_KNIGHT_TOP,ItemID.ELITE_VOID_KNIGHT_TOP),"void_top");r=buy(r,"elite_void_top");assertEquals(1800000,r.getBuybacks().getCommittedGp());assertEquals(0,visible(r,ItemID.PEST_VOID_KNIGHT_TOP));assertEquals(1,visible(r,ItemID.ELITE_VOID_KNIGHT_TOP));}
	@Test public void baseVoidDoesNotUnlockEliteBeforeUpgrade(){BankRun r=observe(buy(funded(1800000,ItemID.PEST_VOID_KNIGHT_TOP),"void_top"),ItemID.ELITE_VOID_KNIGHT_TOP);assertEquals(0,visible(r,ItemID.ELITE_VOID_KNIGHT_TOP));assertEquals("Available",BuybackEngine.status(r,BuybackCatalog.entry("elite_void_top")));}
	@Test public void gracefulIsSixPieceAtomicSet(){int[] ids={ItemID.GRACEFUL_HOOD,ItemID.GRACEFUL_CAPE,ItemID.GRACEFUL_TOP,ItemID.GRACEFUL_LEGS,ItemID.GRACEFUL_GLOVES,ItemID.GRACEFUL_BOOTS};BankRun r=buy(funded(1000000,ids),"graceful");assertEquals(6,r.getBuybacks().getEntitlements().size());assertEquals(1,r.getBuybacks().getPurchases().size());for(int id:ids){assertEquals(1,visible(r,id));}}
	@Test public void incompleteOutfitChargesNothing(){BankRun r=funded(1000000,ItemID.GRACEFUL_HOOD,ItemID.GRACEFUL_CAPE);rejected(()->buy(r,"graceful"));assertEquals(0,r.getBuybacks().getCommittedGp());}
	@Test public void eachOutfitHasVerifiedDistinctRoles(){for(String key:new String[]{"graceful","prospector","angler","rogue","lumberjack","farmer"}){BuybackEntry e=BuybackCatalog.entry(key);int[] ids=e.getRoles().keySet().stream().mapToInt(k->BuybackCatalog.variants(k).keySet().iterator().next()).toArray();BankRun r=buy(funded(e.getPrice(),ids),key);assertEquals(ids.length,r.getBuybacks().getEntitlements().size());assertEquals(0,BuybackEngine.available(r));}}
	@Test public void spendingReducesWorthOnceAndNeverCreatesGains(){BankRun a=funded(2000000,F);BankRun b=buy(a,"fire_cape");Map<Integer,PriceQuote> prices=Collections.singletonMap(F,new PriceQuote(F,0L,SnapshotFixtures.TIME,PriceQuote.Source.RUNELITE_GE_GUIDE,false));assertEquals(Long.valueOf(1000000),BankValuation.calculate(b,prices).getSubtotalGp());assertEquals(a.getFinancial().getGainedGp(),b.getFinancial().getGainedGp());}
	@Test public void bankCorrectionsNeverRefundSpentGp(){BankRun r=buy(funded(1000000,F),"fire_cape");r=BankEngine.correct(r,C,0,UUID.randomUUID(),SnapshotFixtures.TIME);assertEquals(-1000000,BuybackEngine.available(r));assertEquals(1000000,r.getBuybacks().getCommittedGp());}
	@Test public void immutableLegacySnapshotRemainsUnchanged(){BankRun r=funded(1000000,F,P);assertEquals(r.getInitialBank(),buy(r,"fire_cape").getInitialBank());}
