/** Login/hop packets, late arrays and mutable API fields at the actual source boundary. */
public class GeSourceLifecycleTest
{
	private static class Packet implements GrandExchangeOffer
	{
		GrandExchangeOfferState state=GrandExchangeOfferState.BUYING;int item=ItemID.WOODEN_SHIELD,total=10,filled;long price=100,gp;
		public int getItemId(){return item;}public int getTotalQuantity(){return total;}public int getQuantitySold(){return filled;}public long getPrice(){return price;}public long getSpent(){return gp;}public GrandExchangeOfferState getState(){return state;}
	}
	private static class Access implements RuneLiteGeSource.Access
	{
		boolean logged=true;GrandExchangeOffer[] offers;
		public boolean loggedIn(){return logged;}public GrandExchangeOffer[] offers(){return offers;}public String itemName(int id){return "Wooden shield";}
	}
	private static Packet empty(){Packet p=new Packet();p.state=GrandExchangeOfferState.EMPTY;p.item=-1;p.total=0;p.price=0;return p;}
	@Test public void initialLoggedInEmptyEventsAreIgnored(){Access a=new Access();RuneLiteGeSource s=new RuneLiteGeSource(a);for(int slot=0;slot<8;slot++){s.changed(slot,empty());}assertTrue(s.drain().isEmpty());}
	@Test public void nonLoggedInClearCannotDeleteAnOffer(){Access a=new Access();RuneLiteGeSource s=new RuneLiteGeSource(a);s.changed(0,new Packet());s.drain();a.logged=false;s.changed(0,empty());a.logged=true;assertTrue(s.drain().isEmpty());}
	@Test public void lateCurrentOfferArraySeedsOnlyNonemptySlots(){Access a=new Access();RuneLiteGeSource s=new RuneLiteGeSource(a);assertTrue(s.drain().isEmpty());a.offers=new GrandExchangeOffer[]{empty(),new Packet(),empty(),empty(),empty(),empty(),empty(),empty()};List<GeObservation> rows=s.drain();assertEquals(1,rows.size());assertEquals(1,rows.get(0).getSlot());assertTrue(rows.get(0).isInitial());assertTrue(s.drain().isEmpty());}
	@Test public void confirmedSameSessionClearIsDeliveredAsUnknownCollection(){Access a=new Access();RuneLiteGeSource s=new RuneLiteGeSource(a);s.changed(0,new Packet());s.drain();s.changed(0,empty());GeObservation clear=s.drain().get(0);assertFalse(clear.isInitial());assertEquals(GrandExchangeOfferState.EMPTY,clear.getState());}
	@Test public void reconnectStartsNewObservationSession(){Access a=new Access();RuneLiteGeSource s=new RuneLiteGeSource(a);s.changed(0,new Packet());UUID session=s.drain().get(0).getSession();s.resetSession();s.changed(0,empty());assertTrue(s.drain().isEmpty());s.changed(0,new Packet());assertNotEquals(session,s.drain().get(0).getSession());}
	@Test public void missingOrMalformedOfferIsUnknownAndNeverEmpty(){Access a=new Access();RuneLiteGeSource s=new RuneLiteGeSource(a);s.changed(0,null);Packet p=new Packet();p.filled=11;p.gp=1100;s.changed(0,p);assertTrue(s.drain().isEmpty());assertTrue(s.takeObservationGap());assertFalse(s.takeObservationGap());}
	@Test public void invalidSlotAndNegativeItemAreRejected(){Access a=new Access();RuneLiteGeSource s=new RuneLiteGeSource(a);s.changed(-1,new Packet());s.changed(8,new Packet());Packet p=new Packet();p.item=-1;s.changed(0,p);assertTrue(s.drain().isEmpty());assertTrue(s.takeObservationGap());}
	@Test public void sourcePreservesBeyondMaxCashLongs(){Access a=new Access();RuneLiteGeSource s=new RuneLiteGeSource(a);Packet p=new Packet();p.price=3_000_000_000L;p.total=1;p.filled=1;p.gp=2_900_000_000L;s.changed(0,p);GeObservation o=s.drain().get(0);assertEquals(3_000_000_000L,o.getLimitPrice());assertEquals(2_900_000_000L,o.getReportedGp());}
}

package com.fromscratch.model;

import com.fromscratch.SnapshotFixtures;
import java.util.UUID;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

public class InitializationSessionTest
{
	private InitializationSession session;

	@Before
	public void setUp() { session = new InitializationSession(SnapshotFixtures.CHARACTER_A, null); }

	@Test
	public void completeEmptyBankCanBeExplicitlyActivatedWithZeroVirtualWealth()
	{
		session.begin();
		LegacySnapshot empty = SnapshotFixtures.snapshot(0);
		session.observe(empty);
		RunRecord candidate = session.prepareActivation(session.getReviewToken(), empty, SnapshotFixtures.TIME.plusSeconds(1));
		session.committed(candidate);
		assertTrue(session.getSaved().getSnapshot().at(SnapshotLocation.BANK).getQuantities().isEmpty());
		assertEquals(RunStatus.ACTIVE, session.getSaved().getState().getStatus());
		assertEquals(0, session.getSaved().getEconomy().getNetWorth());
	}

	@Test
	public void previewDoesNotActivateOrSaveARun()
	{
		session.begin();
		session.observe(SnapshotFixtures.snapshot(1000));
		assertTrue(session.isInitializing());
		assertNull(session.getSaved());
	}

	@Test(expected = IllegalStateException.class)
	public void duplicateBeginDuringSetupIsRejected() { session.begin(); session.begin(); }

	@Test(expected = IllegalStateException.class)
	public void duplicateInitializationOfActiveRunIsRejected()
	{
		new InitializationSession(SnapshotFixtures.CHARACTER_A, SnapshotFixtures.active(SnapshotFixtures.CHARACTER_A, 1)).begin();
	}

	@Test(expected = IllegalStateException.class)
	public void activationWithoutACompletePreviewIsRejected()
	{
		session.begin();
		session.prepareActivation(null, SnapshotFixtures.snapshot(0), SnapshotFixtures.TIME.plusSeconds(1));
	}

	@Test(expected = IllegalStateException.class)
	public void confirmationOfAnExpiredReviewIsRejected()
	{
		session.begin();
		session.observe(SnapshotFixtures.snapshot(1));
		session.prepareActivation(UUID.randomUUID(), SnapshotFixtures.snapshot(1), SnapshotFixtures.TIME.plusSeconds(1));
	}

	@Test
	public void changedPhysicalContentsRequireAnotherExplicitConfirmation()
	{
		session.begin();
		session.observe(SnapshotFixtures.snapshot(1));
		UUID token = session.getReviewToken();
		try
		{
			session.prepareActivation(token, SnapshotFixtures.snapshot(2), SnapshotFixtures.TIME.plusSeconds(1));
			fail("Changed snapshot must not activate");
		}
		catch (IllegalStateException expected) { assertTrue(expected.getMessage().contains("changed")); }
		assertNull(session.getSaved());
		assertNotEquals(token, session.getReviewToken());
	}

	@Test
	public void unchangedContainersKeepTheirReviewTokenAcrossBankDisplayChanges()
	{
		session.begin();
		session.observe(SnapshotFixtures.snapshot(1));
		UUID token = session.getReviewToken();
		session.observe(SnapshotFixtures.snapshot(1));
		assertEquals(token, session.getReviewToken());
	}

	@Test
	public void cancellingIncompleteSetupLeavesNoRun()
	{
		session.begin();
		session.cancel();
		assertFalse(session.isInitializing());
		assertNull(session.getPreview());
		assertNull(session.getSaved());
	}

	@Test
	public void onlyCommittedActivationBecomesTheSavedRun()
	{
		session.begin();
		session.observe(SnapshotFixtures.snapshot(1000000));
		RunRecord candidate = session.prepareActivation(session.getReviewToken(), SnapshotFixtures.snapshot(1000000), SnapshotFixtures.TIME.plusSeconds(1));
		assertNull(session.getSaved());
		session.committed(candidate);
		assertEquals(RunStatus.ACTIVE, session.getSaved().getState().getStatus());
		assertFalse(session.isInitializing());
	}

	@Test
	public void initialVirtualEconomyIsCompletelyEmptyDespiteLegacyCoins()
	{
		VirtualEconomy economy = SnapshotFixtures.active(SnapshotFixtures.CHARACTER_A, Long.MAX_VALUE).getEconomy();
		assertEquals(0, economy.getSpendableGp());
		assertEquals(0, economy.getNetWorth());
		assertEquals(0, economy.getTotalValueGained());
		assertEquals(0, economy.getItemsUnlocked());
		assertTrue(economy.getItems().isEmpty());
	}

	@Test
	public void resetReturnsNotStartedWithoutAutomaticallyCreatingANewRun()
	{
		RunRecord reset = RunRecord.reset(SnapshotFixtures.active(SnapshotFixtures.CHARACTER_A, 1));
		assertEquals(RunStatus.NOT_STARTED, reset.getState().getStatus());
		assertNull(reset.getState().getRunId());
		assertNull(reset.getSnapshot());
		assertNotNull(reset.getPreviousRunId());
	}

	@Test(expected = IllegalArgumentException.class)
	public void loadedRunFromAnotherCharacterIsRejected()
	{
		new InitializationSession(SnapshotFixtures.CHARACTER_A, SnapshotFixtures.active(SnapshotFixtures.CHARACTER_B, 1));
	}

	@Test(expected = IllegalArgumentException.class)
	public void anotherCharactersCommitCannotChangeTheSession()
	{
		session.committed(SnapshotFixtures.active(SnapshotFixtures.CHARACTER_B, 1));
	}
}

package com.fromscratch.model;

import java.time.Instant;
import java.util.UUID;
import org.junit.Test;

import static org.junit.Assert.*;

/** Header boundary tests; snapshot and accounting invariants enter in later milestones. */
public class RunStateTest
{
	private static final String CHARACTER = "test-character-a";
	private static final UUID RUN_ID = UUID.fromString("00000000-0000-0000-0000-000000000001");
	private static final Instant START = Instant.parse("2026-01-01T00:00:00Z");

	@Test
	public void unstartedHeaderHasCurrentVersionAndNoActiveRun()
	{
		RunState state = RunState.notStarted(CHARACTER);
		assertEquals(1, state.getSchemaVersion());
		assertEquals(CHARACTER, state.getCharacterKey());
		assertEquals(RunStatus.NOT_STARTED, state.getStatus());
		assertNull(state.getRunId());
		assertNull(state.getStartedAt());
		assertNull(state.getCompletedAt());
	}

	@Test
	public void everyPersistedLifecycleStatusHasAValidHeader()
	{
		for (RunStatus status : RunStatus.values())
		{
			boolean activated = status != RunStatus.NOT_STARTED && status != RunStatus.INITIALIZING;
			RunState state = RunState.restore(1, CHARACTER,
				status == RunStatus.NOT_STARTED ? null : RUN_ID, status,
				activated ? START : null, status == RunStatus.COMPLETED ? START.plusSeconds(1) : null);
			assertEquals(status, state.getStatus());
		}
	}

	@Test
	public void validatedRestorePreservesHeaderValues()
	{
		RunState state = RunState.restore(1, CHARACTER, RUN_ID, RunStatus.COMPLETED, START, START.plusSeconds(30));
		assertEquals(RUN_ID, state.getRunId());
		assertEquals(START, state.getStartedAt());
		assertEquals(START.plusSeconds(30), state.getCompletedAt());
		assertEquals(state, RunState.restore(1, CHARACTER, RUN_ID, RunStatus.COMPLETED, START, START.plusSeconds(30)));
	}

	@Test
	public void characterIdentityIsPartOfStateEquality()
	{
		assertNotEquals(RunState.notStarted(CHARACTER), RunState.notStarted("test-character-b"));
	}

	@Test(expected = IllegalArgumentException.class)
	public void futureSchemasRequireExplicitMigration()
	{
		RunState.restore(2, CHARACTER, null, RunStatus.NOT_STARTED, null, null);
	}

	@Test(expected = IllegalArgumentException.class)
	public void oldSchemasRequireExplicitMigration()
	{
		RunState.restore(0, CHARACTER, null, RunStatus.NOT_STARTED, null, null);
	}

	@Test(expected = IllegalArgumentException.class)
	public void blankCharacterKeyIsRejected()
	{
		RunState.notStarted("  ");
	}

	@Test(expected = IllegalArgumentException.class)
	public void missingCharacterKeyIsRejected()
	{
		RunState.notStarted(null);
	}

	@Test(expected = NullPointerException.class)
	public void missingStatusIsRejected()
	{
		RunState.restore(1, CHARACTER, null, null, null, null);
	}

	@Test(expected = NullPointerException.class)
	public void activatedRunRequiresIdentity()
	{
		RunState.restore(1, CHARACTER, null, RunStatus.ACTIVE, START, null);
	}

	@Test(expected = NullPointerException.class)
	public void activatedRunRequiresStartTime()
	{
		RunState.restore(1, CHARACTER, RUN_ID, RunStatus.ACTIVE, null, null);
	}

	@Test(expected = IllegalArgumentException.class)
	public void unstartedRunCannotContainAnOldRunId()
	{
		RunState.restore(1, CHARACTER, RUN_ID, RunStatus.NOT_STARTED, null, null);
	}

	@Test(expected = IllegalArgumentException.class)
	public void initializingRunIsNotYetActivated()
	{
		RunState.restore(1, CHARACTER, RUN_ID, RunStatus.INITIALIZING, START, null);
	}

	@Test(expected = IllegalArgumentException.class)
	public void ongoingRunCannotContainAnEndTime()
	{
		RunState.restore(1, CHARACTER, RUN_ID, RunStatus.NEEDS_RECONCILIATION, START, START);
	}

	@Test(expected = NullPointerException.class)
	public void completedRunRequiresEndTime()
	{
		RunState.restore(1, CHARACTER, RUN_ID, RunStatus.COMPLETED, START, null);
	}

	@Test(expected = IllegalArgumentException.class)
	public void completedRunCannotEndBeforeItStarts()
	{
		RunState.restore(1, CHARACTER, RUN_ID, RunStatus.COMPLETED, START, START.minusSeconds(1));
	}
}

