		assertFalse(reader.progress().ready(SnapshotLocation.INVENTORY));
	}

	@Test
	public void resetBetweenSessionsDiscardsAllCachedPersonalObservations()
	{
		open();
		reader.capture();
		reader.reset();
		access.containers.put(InventoryID.INV, null);
		reader.gameTick();
		expectUnavailable("Inventory container data is unavailable");
	}

	@Test
	public void copiedObservationIsImmutableWhenTheSourceListChanges()
	{
		List<ObservedItem> inventory = new ArrayList<>();
		inventory.add(new ObservedItem(ItemID.SHARK, 4, false));
		access.containers.put(InventoryID.INV, inventory);
		expectUnavailable("Open the normal bank");
		inventory.clear();
		access.containers.put(InventoryID.INV, null);
		open();
		assertEquals(4, reader.capture().at(SnapshotLocation.INVENTORY).quantity(ItemID.SHARK));
	}

	@Test
	public void diagnosticsExposeSizesAgesAndPredicateWithoutAccountItems()
	{
		open();
		access.containers.put(InventoryID.INV, null);
		expectUnavailable("Inventory container data is unavailable");
		String diagnostic = reader.diagnostics();
		assertTrue(diagnostic.contains("bankMounted=true"));
		assertTrue(diagnostic.contains("predicate=INVENTORY_UNAVAILABLE_OR_STALE"));
		assertTrue(diagnostic.contains("inventory={liveSize=-1,observed=false,ageMs=unknown}"));
		assertTrue(diagnostic.contains("equipment={liveSize=0,observed=true,ageMs=0}"));
		assertFalse(diagnostic.contains("quantity"));
	}

	@Test
	public void backwardsClockDoesNotMakeAnObservationTrustworthy()
	{
		expectUnavailable("Open the normal bank");
		access.containers.put(InventoryID.INV, null);
		clock.seconds(-1);
		open();
		expectUnavailable("Inventory container data is unavailable");
	}

	private static final class TestClock extends Clock
	{
		private Instant now = Instant.parse("2026-01-01T00:00:00Z");
		void seconds(long seconds) { now = now.plusSeconds(seconds); }
		public ZoneId getZone() { return ZoneOffset.UTC; }
		public Clock withZone(ZoneId zone) { return this; }
		public Instant instant() { return now; }
	}

	private void expectUnavailable(String message)
	{
		try { reader.capture(); fail("Unavailable bank must not produce a preview"); }
		catch (IllegalStateException expected) { assertTrue(expected.getMessage(), expected.getMessage().contains(message)); }
	}

	private static final class FakeAccess implements BankSnapshotReader.Access
	{
		private final Set<Integer> interfaces = new HashSet<>();
		private final Set<Integer> visible = new HashSet<>();
		private final Map<Integer, List<ObservedItem>> containers = new HashMap<>();
		private final List<Integer> containerReads = new ArrayList<>();

		FakeAccess()
		{
			containers.put(InventoryID.BANK, Collections.emptyList());
			containers.put(InventoryID.INV, Collections.emptyList());
			containers.put(InventoryID.WORN, Collections.emptyList());
		}

		public boolean isInterfaceOpen(int interfaceId) { return interfaces.contains(interfaceId); }
		public boolean isVisible(int componentId) { return visible.contains(componentId); }
		public List<ObservedItem> items(int inventoryId) { containerReads.add(inventoryId); return containers.get(inventoryId); }
	}
}

package com.fromscratch.observation;

import com.fromscratch.model.ContainerSnapshot;
import com.fromscratch.model.LegacySnapshot;
import com.fromscratch.model.SnapshotLocation;
import java.util.Collections;
import java.util.EnumMap;
import java.util.Map;
import lombok.Value;

/** Immutable partial setup results; absent locations are unknown, never empty. */
@Value
public class CaptureProgress
{
	Map<SnapshotLocation, ContainerSnapshot> containers;

	public CaptureProgress(Map<SnapshotLocation, ContainerSnapshot> containers)
	{
		EnumMap<SnapshotLocation, ContainerSnapshot> copy = new EnumMap<>(SnapshotLocation.class);
		copy.putAll(containers);
		this.containers = Collections.unmodifiableMap(copy);
	}

	public boolean ready(SnapshotLocation location) { return containers.containsKey(location); }

	public static CaptureProgress from(LegacySnapshot snapshot)
	{
		EnumMap<SnapshotLocation, ContainerSnapshot> result = new EnumMap<>(SnapshotLocation.class);
		if (snapshot != null)
		{
			for (SnapshotLocation location : SnapshotLocation.values()) { result.put(location, snapshot.at(location)); }
		}
		return new CaptureProgress(result);
	}
}

package com.fromscratch.observation;

import java.util.Arrays;
import java.util.Collections;
import java.util.Optional;
import net.runelite.client.config.RuneScapeProfile;
import net.runelite.client.config.RuneScapeProfileType;
import org.junit.Test;

import static org.junit.Assert.*;

public class CharacterIdentityTest
{
	private static final long HASH = 12345;
	private static final String PROFILE = "rsprofile.synthetic";

	private Optional<String> verify(boolean loggedIn, long hash, RuneScapeProfileType type, String selected)
	{
		return CharacterIdentity.verify(loggedIn, hash, type, selected,
			Collections.singletonList(new RuneScapeProfile("Synthetic", RuneScapeProfileType.STANDARD, HASH, PROFILE)));
	}

	@Test
	public void loggedOutIdentityIsUnavailable() { assertFalse(verify(false, HASH, RuneScapeProfileType.STANDARD, PROFILE).isPresent()); }

	@Test
	public void unknownAccountHashIsUnavailable() { assertFalse(verify(true, RuneScapeProfile.ACCOUNT_HASH_INVALID, RuneScapeProfileType.STANDARD, PROFILE).isPresent()); }

	@Test
	public void staleSelectedCharacterProfileIsRejected() { assertFalse(verify(true, HASH + 1, RuneScapeProfileType.STANDARD, PROFILE).isPresent()); }

	@Test
	public void staleWorldProfileTypeIsRejected() { assertFalse(verify(true, HASH, RuneScapeProfileType.DEADMAN, PROFILE).isPresent()); }

	@Test
	public void absentSelectedProfileIsRejected() { assertFalse(verify(true, HASH, RuneScapeProfileType.STANDARD, null).isPresent()); }

	@Test
	public void duplicateMatchingProfilesAreAmbiguous()
	{
		RuneScapeProfile profile = new RuneScapeProfile("Synthetic", RuneScapeProfileType.STANDARD, HASH, PROFILE);
		assertFalse(CharacterIdentity.verify(true, HASH, RuneScapeProfileType.STANDARD, PROFILE, Arrays.asList(profile, profile)).isPresent());
	}

	@Test
	public void displayNameAndConfigurationProfileKeyChangesPreserveIdentity()
	{
		String original = verify(true, HASH, RuneScapeProfileType.STANDARD, PROFILE).get();
		String changed = CharacterIdentity.verify(true, HASH, RuneScapeProfileType.STANDARD, "rsprofile.new",
			Collections.singletonList(new RuneScapeProfile("Renamed", RuneScapeProfileType.STANDARD, HASH, "rsprofile.new"))).get();
		assertEquals(original, changed);
		assertTrue(original.matches("[a-f0-9]{64}"));
	}

	@Test
	public void accountAndWorldProfileTypeProduceSeparateNamespaces()
	{
		String original = verify(true, HASH, RuneScapeProfileType.STANDARD, PROFILE).get();
		for (RuneScapeProfile profile : Arrays.asList(
			new RuneScapeProfile("Other", RuneScapeProfileType.STANDARD, HASH + 1, "rsprofile.other"),
			new RuneScapeProfile("Synthetic", RuneScapeProfileType.DEADMAN, HASH, "rsprofile.deadman")))
		{
			assertNotEquals(original, CharacterIdentity.verify(true, profile.getAccountHash(), profile.getType(), profile.getKey(), Collections.singletonList(profile)).get());
		}
	}
}

package com.fromscratch.observation;

import java.util.concurrent.TimeUnit;

/** Monotonic, client-thread-only throttle shared by success and failure diagnostics. */
final class DiagnosticRateLimit
{
	private static final long INTERVAL_NANOS = TimeUnit.SECONDS.toNanos(10);
	private boolean logged;
	private long last;

	boolean allow(long now)
	{
		if (logged && now - last < INTERVAL_NANOS) { return false; }
		logged = true;
		last = now;
		return true;
	}
}

package com.fromscratch.observation;

import java.util.concurrent.TimeUnit;
import org.junit.Test;
import static org.junit.Assert.*;

public class DiagnosticRateLimitTest
{
	@Test
	public void repeatedTicksAndStateChangesShareOneTenSecondLimit()
	{
		DiagnosticRateLimit limit = new DiagnosticRateLimit();
		assertTrue(limit.allow(0));
		for (int second = 0; second < 10; second++) { assertFalse(limit.allow(TimeUnit.SECONDS.toNanos(second))); }
		assertTrue(limit.allow(TimeUnit.SECONDS.toNanos(10)));
		assertFalse(limit.allow(TimeUnit.SECONDS.toNanos(10)));
	}

	@Test
	public void monotonicCounterMayStartAtAnArbitraryNegativeValue()
	{
		DiagnosticRateLimit limit = new DiagnosticRateLimit();
		assertTrue(limit.allow(-100));
		assertFalse(limit.allow(-99));
		assertTrue(limit.allow(TimeUnit.SECONDS.toNanos(10) - 100));
	}
}

package com.fromscratch.observation;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.WidgetType;

/**
 * Positive evidence for null personal containers, never a null-to-empty default.
 * The normal inventory builds all 28 children, including hidden BLANKOBJECT slots.
 * wear_initslot builds an item child (1) and empty-slot icon (2); wear_updateslot
 * toggles them in opposite directions. Every logical equipment slot must agree.
 * Two different game ticks with a complete visible view guard transient UI builds.
 * This verifier never reads bank item widgets or derives populated quantities.
 */
public final class EmptyContainerVerifier
{
	public enum Result { UNKNOWN, NON_EMPTY, SETTLING, EMPTY }
	private static final int INVENTORY_SLOTS = 28;
	// ARMS, HAIR and JAW in EquipmentInventorySlot are appearance positions, not item slots.
	private static final int[] EQUIPMENT_COMPONENTS = {
		InterfaceID.Wornitems.SLOT0, InterfaceID.Wornitems.SLOT1, InterfaceID.Wornitems.SLOT2,
		InterfaceID.Wornitems.SLOT3, InterfaceID.Wornitems.SLOT4, InterfaceID.Wornitems.SLOT5,
		InterfaceID.Wornitems.SLOT7, InterfaceID.Wornitems.SLOT9, InterfaceID.Wornitems.SLOT10,
		InterfaceID.Wornitems.SLOT12, InterfaceID.Wornitems.SLOT13
	};
	private final Access access;
	private final Map<Integer, Candidate> candidates = new HashMap<>();
	private final Map<Integer, Result> results = new HashMap<>();
	private long tick;

	public EmptyContainerVerifier(Access access) { this.access = access; }
	public void gameTick() { tick++; }
	public void reset() { candidates.clear(); results.clear(); }
	public void invalidate(int id) { candidates.remove(id); results.remove(id); }

	public Result verify(int id)
	{
		int view = -1;
		Result evidence = Result.UNKNOWN;
		if (id == InventoryID.INV)
		{
			if (open(InterfaceID.INVENTORY, InterfaceID.Inventory.ITEMS)) { view = InterfaceID.Inventory.ITEMS; }
			else if (open(InterfaceID.BANKSIDE, InterfaceID.Bankside.ITEMS)) { view = InterfaceID.Bankside.ITEMS; }
			if (view != -1) { evidence = inventory(access.widget(view)); }
		}
		else if (id == InventoryID.WORN && open(InterfaceID.WORNITEMS, InterfaceID.Wornitems.UNIVERSE))
		{
			view = InterfaceID.Wornitems.UNIVERSE;
			evidence = equipment();
		}
		Result result = evidence;
		if (evidence == Result.EMPTY)
		{
			Candidate prior = candidates.get(id);
			if (prior == null || prior.view != view)
			{
				candidates.put(id, new Candidate(view, tick));
				result = Result.SETTLING;
			}
			else if (tick <= prior.tick) { result = Result.SETTLING; }
		}
		else { candidates.remove(id); }
		results.put(id, result);
		return result;
	}

	private boolean open(int group, int component)
	{
		Node root = access.widget(component);
		return access.isInterfaceOpen(group) && root != null && !root.hidden();
	}

	private Result inventory(Node root)
	{
		boolean complete = true;
		for (int index = 0; index < INVENTORY_SLOTS; index++)
		{
			Node slot = root.child(index);
			if (slot == null || slot.type() != WidgetType.GRAPHIC) { complete = false; continue; }
			if (!slot.selfHidden() && slot.itemId() >= 0 && slot.itemId() != ItemID.BLANKOBJECT)
			{
				return Result.NON_EMPTY;
			}
			// A default itemId=-1 widget is not proof that inventory_drawitem ran.
			if (!slot.selfHidden() || slot.itemId() != ItemID.BLANKOBJECT || slot.quantity() != 1)
			{
				complete = false;
			}
		}
		return complete ? Result.EMPTY : Result.UNKNOWN;
	}

	private Result equipment()
	{
		boolean complete = true;
		for (int component : EQUIPMENT_COMPONENTS)
		{
			Node parent = access.widget(component);
			if (parent == null || parent.hidden()) { complete = false; continue; }
			Node item = parent.child(1);
			Node emptyIcon = parent.child(2);
			if (item != null && item.type() == WidgetType.GRAPHIC && !item.selfHidden() && item.itemId() >= 0)
			{
				return Result.NON_EMPTY;
			}
			if (item == null || emptyIcon == null || item.type() != WidgetType.GRAPHIC
				|| emptyIcon.type() != WidgetType.GRAPHIC) { complete = false; continue; }
			// Item ID can retain the previous item after unequipping. The empty
			// branch explicitly hides that child and shows the initialized icon.
			if (!item.selfHidden() || emptyIcon.selfHidden() || emptyIcon.spriteId() < 0)
			{
				complete = false;
			}
		}
		return complete ? Result.EMPTY : Result.UNKNOWN;
	}

	public String diagnostics()
	{
		return "emptyVerification[INV=" + results.getOrDefault(InventoryID.INV, Result.UNKNOWN)
			+ ",WORN=" + results.getOrDefault(InventoryID.WORN, Result.UNKNOWN) + "]";
	}

	/** Small supported widget-read boundary, also usable without a game client in tests. */
	public interface Access
	{
		boolean isInterfaceOpen(int group);
		Node widget(int component);
	}

	public interface Node
	{
		boolean hidden();
		boolean selfHidden();
		int type();
		int itemId();
		int quantity();
		int spriteId();
		Node child(int index);
	}

	private static final class Candidate
	{
		private final int view;
		private final long tick;
		private Candidate(int view, long tick) { this.view = view; this.tick = tick; }
	}
}

