		openBank();
		tick();
		assertEquals(0, bank.capture().at(SnapshotLocation.INVENTORY).getTotalQuantity());
		assertEquals(0, bank.capture().at(SnapshotLocation.EQUIPMENT).getTotalQuantity());
	}

