	private static List<ObservedItem> contents(boolean populated, boolean nullWhenEmpty, int id)
	{
		return populated ? Collections.singletonList(new ObservedItem(id, 1, false)) : nullWhenEmpty ? null : Collections.emptyList();
	}

	private void showInventory()
	{
		mounted.add(InterfaceID.INVENTORY);
		Node root = new Node();
		for (int index = 0; index < 28; index++)
		{
			Node slot = new Node();
			slot.id = ItemID.BLANKOBJECT;
			slot.quantity = 1;
			slot.selfHidden = true;
			root.children.put(index, slot);
		}
		widgets.put(InterfaceID.Inventory.ITEMS, root);
	}

	private void showEquipment()
	{
		mounted.add(InterfaceID.WORNITEMS);
		widgets.put(InterfaceID.Wornitems.UNIVERSE, new Node());
		int[] components = {InterfaceID.Wornitems.SLOT0, InterfaceID.Wornitems.SLOT1, InterfaceID.Wornitems.SLOT2,
			InterfaceID.Wornitems.SLOT3, InterfaceID.Wornitems.SLOT4, InterfaceID.Wornitems.SLOT5, InterfaceID.Wornitems.SLOT7,
			InterfaceID.Wornitems.SLOT9, InterfaceID.Wornitems.SLOT10, InterfaceID.Wornitems.SLOT12, InterfaceID.Wornitems.SLOT13};
		for (int component : components)
		{
			Node parent = new Node();
			Node item = new Node();
			item.selfHidden = true;
			Node icon = new Node();
			icon.sprite = 1; // Synthetic initialized empty-slot sprite; not a game item.
			parent.children.put(1, item);
			parent.children.put(2, icon);
			widgets.put(component, parent);
		}
	}

	private void openBank()
	{
		mounted.clear();
		mounted.add(InterfaceID.BANKMAIN);
		widgets.put(InterfaceID.Bankmain.ITEMS_CONTAINER, new Node());
		bank.interfaceChanged();
	}

	private void tick() { verifier.gameTick(); bank.gameTick(); }
	private void pollBeforeBank()
	{
		tick();
		try { bank.capture(); fail("Bank is still closed"); }
		catch (IllegalStateException expected) { assertTrue(expected.getMessage().contains("Open the normal bank")); }
	}
	private void assertSettling(int id)
	{
		try { personal.items(id); fail("One sample is insufficient"); }
		catch (IllegalStateException expected) { assertTrue(expected.getMessage().contains("settling")); }
	}
	private void assertUnknown(int id)
	{
		assertNull(personal.items(id));
		tick();
		assertNull(personal.items(id));
	}
	private void assertShowsItem(int id)
	{
		try { personal.items(id); fail("Populated UI with a missing container must remain blocked"); }
		catch (IllegalStateException expected) { assertTrue(expected.getMessage().contains("shows an item")); }
	}

	private static final class Node implements EmptyContainerVerifier.Node
	{
		private final Map<Integer, Node> children = new HashMap<>();
		private boolean hidden;
		private boolean selfHidden;
		private int id = -1;
		private int quantity;
		private int sprite = -1;
		public boolean hidden() { return hidden; }
		public boolean selfHidden() { return selfHidden; }
		public int type() { return WidgetType.GRAPHIC; }
		public int itemId() { return id; }
		public int quantity() { return quantity; }
		public int spriteId() { return sprite; }
		public Node child(int index) { return children.get(index); }
	}
}

package com.fromscratch.observation;

import com.fromscratch.model.LegacySnapshot;
import java.util.ArrayList;
import java.util.List;
import java.util.Objects;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.WidgetNode;
import net.runelite.api.HashTable;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneScapeProfileType;

/** Client-thread-only observation adapter. It never sends game actions or reads special storage. */
@Singleton
@Slf4j
public final class RuneLiteSnapshotObserver implements SnapshotSource
{
	private final Client client;
	private final ConfigManager configManager;
	private final BankSnapshotReader bankReader;
	private final EmptyContainerVerifier emptyVerifier;
	private final ItemObservationCollector itemCollector;
	private long verifiedHash;
	private RuneScapeProfileType verifiedType;
	private String verifiedProfile;
	private String verifiedCharacter;
	private boolean initializing;
	private final DiagnosticRateLimit diagnosticRateLimit = new DiagnosticRateLimit();

	@Inject
	public RuneLiteSnapshotObserver(Client client, ConfigManager configManager)
	{
		this.client = client;
		this.configManager = configManager;
		emptyVerifier = new EmptyContainerVerifier(new EmptyContainerVerifier.Access()
		{
			public boolean isInterfaceOpen(int id) { return interfaceOpen(id); }
			public EmptyContainerVerifier.Node widget(int id) { return WidgetReadNode.of(client.getWidget(id)); }
		});
		PersonalContainerReader containerReader = new PersonalContainerReader(
			id -> copy(id, id == InventoryID.BANK), emptyVerifier);
		BankSnapshotReader.Access access = new BankSnapshotReader.Access()
		{
			public boolean isInterfaceOpen(int interfaceId)
			{
				// getWidget alone can return a cached definition after closure. The
				// component table contains mounted interfaces, including an already
				// open bank whose WidgetLoaded event preceded plugin enablement.
				return interfaceOpen(interfaceId);
			}

			public boolean isVisible(int componentId)
			{
				Widget widget = client.getWidget(componentId);
				return widget != null && !widget.isHidden();
			}

			public List<ObservedItem> items(int inventoryId)
			{
				return containerReader.items(inventoryId);
			}
		};
		bankReader = new BankSnapshotReader(access);
		itemCollector = new ItemObservationCollector(access);
	}

	public void resetSession()
	{
		endInitialization();
		itemCollector.reset();
		verifiedCharacter = null;
	}

	public void beginInitialization()
	{
		emptyVerifier.reset();
		bankReader.reset();
		initializing = true;
	}

	public void endInitialization()
	{
		emptyVerifier.reset();
		initializing = false;
		bankReader.reset();
	}

	public CaptureProgress progress() { return bankReader.progress(); }

	public void containerChanged(int id, ItemContainer container)
	{
		emptyVerifier.reset();
		List<ObservedItem> items = null;
		try { items = copy(container, id == InventoryID.BANK); }
		catch (IllegalStateException ex) { /* A malformed payload must still invalidate the old observation. */ }
		itemCollector.changed(id, items);
		if (initializing) { bankReader.containerChanged(id, items); }
	}

	public void bankOpened() { bankReader.interfaceChanged(); itemCollector.bankInterfaceChanged(); }
	public void bankClosed() { bankReader.interfaceChanged(); itemCollector.bankInterfaceChanged(); }
	public void gameTick() { emptyVerifier.gameTick(); bankReader.gameTick(); itemCollector.gameTick(); }
	public boolean supportsTracking() { return true; }
	// Login/identity boundaries already reset the collector. Keep observations made
	// while a background load or the initial confirmation was in progress.
	public void beginTracking() { }
	public void confirmedSnapshot(LegacySnapshot snapshot) { itemCollector.seedConfirmed(snapshot); }
	public void acknowledgeItems(long tick) { itemCollector.acknowledge(tick); }
	public void acknowledgeItems(ItemObservation observation) { itemCollector.acknowledge(observation); }
	public String itemName(int id)
	{
		try
		{
			String name = client.getItemDefinition(id).getName(); return name == null ? "Unknown item #" + id : name;
		}
		catch (RuntimeException ex) { return "Unknown item #" + id; }
	}
	public int noteBase(int id)
	{
		try
		{
			net.runelite.api.ItemComposition item = client.getItemDefinition(id);
			return item.getNote() != -1 && item.getLinkedNoteId() >= 0 ? item.getLinkedNoteId() : id;
		}
		catch (RuntimeException ex) { return id; } // unknown definitions never create an inferred equivalence
	}
	public void itemAction(int id, ItemObservation.Action action) { itemCollector.action(id, action); }
	public void unsupportedItemAction() { itemCollector.unsupportedAction(); }
	public ItemObservation observeItems(boolean preparing)
	{
		ItemObservation observation = itemCollector.poll(preparing);
		if (log.isDebugEnabled() && diagnosticRateLimit.allow(System.nanoTime()))
		{
			log.debug("From Scratch items: preparing={} observedLocations={} stable={} bankOpen={} uncertainBank={} {}",
				preparing, observation.getProgress().getContainers().size(), observation.isStable(), observation.isBankOpen(), observation.isUncertainBankChange(), itemCollector.diagnostics());
		}
		return observation;
	}

	/** UI loading/closure invalidates verification candidates, not earlier valid setup observations. */
	public void personalInterfaceChanged() { emptyVerifier.reset(); }

	public String characterKey()
	{
		if (!client.isClientThread()) { throw new IllegalStateException("Snapshot observations require the client thread"); }
		if (client.getGameState() != GameState.LOGGED_IN || client.getLocalPlayer() == null) { return null; }
		long hash = client.getAccountHash();
		RuneScapeProfileType type = RuneScapeProfileType.getCurrent(client);
		String profile = configManager.getRSProfileKey();
		if (verifiedCharacter != null && hash == verifiedHash && type == verifiedType && Objects.equals(profile, verifiedProfile))
		{
			return verifiedCharacter;
		}
		String key = CharacterIdentity.verify(true, hash, type, profile, configManager.getRSProfiles()).orElse(null);
		if (!Objects.equals(key, verifiedCharacter)) { endInitialization(); itemCollector.reset(); }
		verifiedHash = hash;
		verifiedType = type;
		verifiedProfile = profile;
		verifiedCharacter = key;
		return key;
	}

	public LegacySnapshot capture(String expectedCharacter)
	{
		if (expectedCharacter == null || !expectedCharacter.equals(characterKey()))
		{
			throw new IllegalStateException("Log in and wait for a verified character identity before initializing");
		}
		try { return bankReader.capture(); }
		finally
		{
			if (log.isDebugEnabled() && diagnosticRateLimit.allow(System.nanoTime()))
			{
				log.debug("From Scratch capture: loggedIn={} initializing={} liveSizes[BANK={},INV={},WORN={}] {} {}",
					client.getGameState() == GameState.LOGGED_IN, initializing,
					liveSize(InventoryID.BANK), liveSize(InventoryID.INV), liveSize(InventoryID.WORN), bankReader.diagnostics(), emptyVerifier.diagnostics());
			}
		}
	}

	private boolean interfaceOpen(int id)
	{
		HashTable<WidgetNode> components = client.getComponentTable();
		if (components == null) { return false; }
		for (WidgetNode node : components) { if (node.getId() == id) { return true; } }
		return false;
	}

	private int liveSize(int id)
	{
		ItemContainer container = client.getItemContainer(id);
		return container == null ? -1 : container.getItems() == null ? -2 : container.getItems().length;
	}

	private List<ObservedItem> copy(int containerId, boolean bank)
	{
		return copy(client.getItemContainer(containerId), bank);
	}

	private List<ObservedItem> copy(ItemContainer container, boolean bank)
	{
		if (container == null || container.getItems() == null) { return null; }
		List<ObservedItem> result = new ArrayList<>();
		for (Item item : container.getItems())
		{
			if (item == null) { throw new IllegalStateException("A container is incomplete; reopen the bank and retry"); }
			int id = item.getId();
			boolean placeholder = id >= 0 && item.getQuantity() > 0
				&& ((bank && id == ItemID.BANK_FILLER) || client.getItemDefinition(id).getPlaceholderTemplateId() != -1);
			result.add(new ObservedItem(id, item.getQuantity(), placeholder));
		}
		return result;
	}
}

package com.fromscratch.observation;

import com.fromscratch.model.ContainerSnapshot;
import com.fromscratch.model.LegacySnapshot;
import com.fromscratch.model.SnapshotLocation;
import java.time.Instant;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

/** Pure validation/aggregation, independent of RuneLite widgets and persistence. */
public final class SnapshotAssembler
{
	private SnapshotAssembler() { }

	public static LegacySnapshot capture(boolean bankOpen, boolean completeBankData,
		Map<SnapshotLocation, List<ObservedItem>> observations, Instant capturedAt)
	{
		if (!bankOpen || !completeBankData)
		{
			throw new IllegalStateException("The normal bank must be open with complete current bank data");
		}
		EnumMap<SnapshotLocation, ContainerSnapshot> containers = new EnumMap<>(SnapshotLocation.class);
		for (SnapshotLocation location : SnapshotLocation.values())
		{
			List<ObservedItem> slots = observations.get(location);
			if (slots == null)
			{
				throw new IllegalStateException("Bank, inventory and equipment must all be available");
			}
			containers.put(location, container(slots));
		}
		return new LegacySnapshot(capturedAt, containers);
	}

	/** Validates a single complete observation before it can enter the setup cache. */
	public static ContainerSnapshot container(List<ObservedItem> slots)
	{
		if (slots == null) { throw new IllegalStateException("Container data is unavailable"); }
		Map<Integer, Long> quantities = new TreeMap<>();
		int occupied = 0;
		for (ObservedItem item : slots)
		{
			if (item == null || item.getQuantity() < 0)
			{
				throw new IllegalStateException("An incomplete or invalid item slot was observed. Wait for bank data or close and reopen the bank.");
			}
			if (item.getItemId() < 0 || item.getQuantity() == 0 || item.isPlaceholder()) { continue; }
			quantities.merge(item.getItemId(), item.getQuantity(), Math::addExact);
			occupied = Math.incrementExact(occupied);
		}
		return new ContainerSnapshot(quantities, occupied);
	}
}

package com.fromscratch.observation;

import com.fromscratch.SnapshotFixtures;
import com.fromscratch.model.LegacySnapshot;
import com.fromscratch.model.SnapshotLocation;
import java.util.EnumMap;
import java.util.List;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.*;

public class SnapshotAssemblerTest
{
	private EnumMap<SnapshotLocation, List<ObservedItem>> observations;

	@Before
	public void setUp() { observations = SnapshotFixtures.observations(); }

	private LegacySnapshot capture() { return SnapshotAssembler.capture(true, true, observations, SnapshotFixtures.TIME); }
	private void item(SnapshotLocation location, int id, long quantity) { observations.get(location).add(new ObservedItem(id, quantity, false)); }

	@Test
	public void emptyBankIsACompleteValidSnapshot()
	{
		assertTrue(capture().at(SnapshotLocation.BANK).getQuantities().isEmpty());
	}

	@Test
	public void populatedBankPreservesEveryTypeAndQuantity()
	{
		item(SnapshotLocation.BANK, ItemID.SHARK, 100);
		item(SnapshotLocation.BANK, ItemID.ABYSSAL_WHIP, 1);
		assertEquals(2, capture().at(SnapshotLocation.BANK).getQuantities().size());
		assertEquals(100, capture().at(SnapshotLocation.BANK).quantity(ItemID.SHARK));
	}

	@Test
	public void inventoryItemsRemainInInventoryBaseline()
	{
		item(SnapshotLocation.INVENTORY, ItemID.SHARK, 5);
		assertEquals(5, capture().at(SnapshotLocation.INVENTORY).quantity(ItemID.SHARK));
		assertEquals(0, capture().at(SnapshotLocation.BANK).quantity(ItemID.SHARK));
	}

	@Test
	public void equippedItemsRemainInEquipmentBaseline()
	{
		item(SnapshotLocation.EQUIPMENT, ItemID.ABYSSAL_WHIP, 1);
		assertEquals(1, capture().at(SnapshotLocation.EQUIPMENT).getOccupiedSlots());
		assertEquals(1, capture().at(SnapshotLocation.EQUIPMENT).quantity(ItemID.ABYSSAL_WHIP));
	}

	@Test
	public void coinsArePreservedSeparatelyInAllThreeLegacyLocations()
	{
		for (SnapshotLocation location : SnapshotLocation.values()) { item(location, ItemID.COINS, 100); }
		for (SnapshotLocation location : SnapshotLocation.values()) { assertEquals(100, capture().at(location).quantity(ItemID.COINS)); }
	}

	@Test
	public void placeholdersAndEmptySlotsAreNotOwnedItems()
	{
		observations.get(SnapshotLocation.BANK).add(new ObservedItem(ItemID.Placeholder.ABYSSAL_WHIP, 1, true));
		observations.get(SnapshotLocation.BANK).add(new ObservedItem(ItemID.BANK_FILLER, 1, true));
		item(SnapshotLocation.BANK, -1, 0);
		item(SnapshotLocation.BANK, ItemID.SHARK, 0);
		assertEquals(0, capture().at(SnapshotLocation.BANK).getOccupiedSlots());
		assertTrue(capture().at(SnapshotLocation.BANK).getQuantities().isEmpty());
	}

	@Test
	public void largeStacksAggregateBeyondSignedIntegerRange()
	{
		item(SnapshotLocation.BANK, ItemID.COINS, Integer.MAX_VALUE);
		item(SnapshotLocation.BANK, ItemID.COINS, Integer.MAX_VALUE);
		assertEquals(4294967294L, capture().at(SnapshotLocation.BANK).quantity(ItemID.COINS));
	}

	@Test
	public void multipleUnstackableCopiesAggregateWithoutLosingSlotCount()
	{
		for (int copy = 0; copy < 3; copy++) { item(SnapshotLocation.INVENTORY, ItemID.ABYSSAL_WHIP, 1); }
		assertEquals(3, capture().at(SnapshotLocation.INVENTORY).quantity(ItemID.ABYSSAL_WHIP));
		assertEquals(3, capture().at(SnapshotLocation.INVENTORY).getOccupiedSlots());
	}

	@Test
	public void distinctNotedVariantsKeepTheirExactIds()
	{
		item(SnapshotLocation.BANK, ItemID.ABYSSAL_WHIP, 1);
		item(SnapshotLocation.INVENTORY, ItemID.Cert.ABYSSAL_WHIP, 2);
		assertEquals(0, capture().at(SnapshotLocation.INVENTORY).quantity(ItemID.ABYSSAL_WHIP));
		assertEquals(2, capture().at(SnapshotLocation.INVENTORY).quantity(ItemID.Cert.ABYSSAL_WHIP));
	}

	@Test(expected = IllegalStateException.class)
	public void initializationWithoutAnOpenBankIsRejected()
	{
		SnapshotAssembler.capture(false, true, observations, SnapshotFixtures.TIME);
	}

	@Test(expected = IllegalStateException.class)
	public void staleOrIncompleteBankObservationIsRejected()
	{
		SnapshotAssembler.capture(true, false, observations, SnapshotFixtures.TIME);
	}

	@Test(expected = IllegalStateException.class)
	public void absentBankCannotBeInterpretedAsAnEmptyBank()
	{
		observations.remove(SnapshotLocation.BANK);
		capture();
	}

	@Test(expected = IllegalStateException.class)
	public void absentInventoryIsNotAssumedEmpty()
	{
		observations.remove(SnapshotLocation.INVENTORY);
		capture();
	}

	@Test(expected = IllegalStateException.class)
	public void absentEquipmentIsNotAssumedEmpty()
	{
		observations.remove(SnapshotLocation.EQUIPMENT);
		capture();
	}

	@Test(expected = IllegalStateException.class)
	public void incompleteItemSlotIsRejected()
	{
		observations.get(SnapshotLocation.BANK).add(null);
		capture();
	}

	@Test(expected = IllegalStateException.class)
	public void negativeQuantityIsRejected()
	{
		item(SnapshotLocation.BANK, ItemID.SHARK, -1);
		capture();
	}

	@Test(expected = ArithmeticException.class)
	public void quantityOverflowCannotWrapIntoAValidSnapshot()
	{
		item(SnapshotLocation.BANK, ItemID.COINS, Long.MAX_VALUE);
		item(SnapshotLocation.BANK, ItemID.COINS, 1);
		capture();
	}

	@Test
	public void subsequentPhysicalChangesCannotModifyTheOriginalBaseline()
	{
		item(SnapshotLocation.BANK, ItemID.SHARK, 10);
		LegacySnapshot original = capture();
		observations.get(SnapshotLocation.BANK).clear();
		assertEquals(10, original.at(SnapshotLocation.BANK).quantity(ItemID.SHARK));
		assertEquals(0, capture().at(SnapshotLocation.BANK).quantity(ItemID.SHARK));
	}

	@Test(expected = UnsupportedOperationException.class)
	public void legacyQuantityMapsAreImmutable()
	{
		capture().at(SnapshotLocation.BANK).getQuantities().put(ItemID.SHARK, 1L);
	}

	@Test(expected = UnsupportedOperationException.class)
	public void legacyContainerMapsAreImmutable()
	{
		capture().getContainers().clear();
	}
}

