package com.fromscratch.tracking;

import com.fromscratch.model.VirtualItemOwnership;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import lombok.Getter;

/** Explicit player decisions bound by the review token; these never mutate a live run themselves. */
@Getter
public final class ItemReviewEdits
{
	private final Map<Integer, VirtualItemOwnership> ownership;
	private final Set<Integer> returned;
	private final Set<Integer> permanentlyRemoved;
	private final String reason;
	private final Map<Integer, String> decisions;
	public ItemReviewEdits(Map<Integer, VirtualItemOwnership> ownership, Map<Integer, Long> legacyDeficits,
		Set<Integer> returned, Set<Integer> permanentlyRemoved, String reason)
	{
		this(ownership, legacyDeficits, returned, permanentlyRemoved, reason, Collections.emptyMap());
	}
	public ItemReviewEdits(Map<Integer, VirtualItemOwnership> ownership, Map<Integer, Long> legacyDeficits,
		Set<Integer> returned, Set<Integer> permanentlyRemoved, String reason, Map<Integer, String> decisions)
	{
		this.ownership = Collections.unmodifiableMap(new HashMap<>(ownership));
		new LegacyBankDeficits(legacyDeficits); // Validate IDs/ranges, while retaining meaningful zero overrides below.
		// Zero overrides are meaningful, so keep them rather than normalizing them away.
		Map<Integer, Long> overrides = new HashMap<>(legacyDeficits);
		this.deficitOverrides = Collections.unmodifiableMap(overrides);
		this.returned = Collections.unmodifiableSet(new HashSet<>(returned));
		this.permanentlyRemoved = Collections.unmodifiableSet(new HashSet<>(permanentlyRemoved));
		if (reason == null || reason.isBlank() || reason.length() > 300) { throw new IllegalArgumentException("A short explanation is required for item decisions"); }
		this.reason = reason;
		Map<Integer, String> choices = new HashMap<>();
		decisions.forEach((id, choice) ->
		{
			if (id == null || id < 0 || choice == null || choice.isBlank() || choice.length() > 60) { throw new IllegalArgumentException("Invalid item decision"); }
			choices.put(id, choice);
		});
		this.decisions = Collections.unmodifiableMap(choices);
	}
	private final Map<Integer, Long> deficitOverrides;
}

package com.fromscratch.tracking;

import com.fromscratch.FromScratchConfig;
import com.fromscratch.model.RunRecord;
import com.fromscratch.model.SnapshotLocation;
import com.fromscratch.model.VirtualLocation;
import com.fromscratch.observation.ItemObservation;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/** Opt-in single-item DEBUG trace. Never logs a whole snapshot, character, path or account identifier. */
@Singleton
@Slf4j
public final class ItemTrackingDiagnostics
{
	private static final long INTERVAL_NANOS = 2_000_000_000L;
	private volatile boolean enabled;
	private volatile int itemId;
	private final Map<String, Long> last = new HashMap<>();
	public synchronized void configure(FromScratchConfig config)
	{
		enabled = config.developmentItemTrace(); itemId = config.developmentTraceItemId(); last.clear();
	}
	public void observe(RunRecord run, ItemObservation observation, boolean gate)
	{
		if (!enabled || !log.isDebugEnabled()) { return; }
		StringBuilder after = new StringBuilder();
		for (SnapshotLocation location : SnapshotLocation.values())
		{
			com.fromscratch.model.ContainerSnapshot container = observation.getProgress().getContainers().get(location);
			after.append(location).append('=').append(container == null ? "unknown" : container.quantity(itemId)).append(' ');
		}
		write("OBSERVE", "before=" + quantities(run.getItemProgress().getPhysical()) + " after=" + after
			+ " gate=" + gate + " stable=" + observation.isStable() + " bankOpen=" + observation.isBankOpen()
			+ " bankContext=" + observation.isBankInteraction() + " receipt=" + observation.getOrdinaryReceipts().getOrDefault(itemId, 0L));
	}
	private String quantities(Holdings holdings)
	{
		StringBuilder text = new StringBuilder();
		for (SnapshotLocation location : SnapshotLocation.values()) { text.append(location).append('=').append(holdings.at(itemId, location)).append(' '); }
		return text.toString();
	}
	public void plan(AccountingPlan plan, boolean pending)
	{
		if (!enabled || !log.isDebugEnabled()) { return; }
		StringBuilder classifications = new StringBuilder();
		for (ItemTransaction entry : plan.getTransactions())
		{ if (entry.getItemId() == itemId) { classifications.append(entry.getCategory()).append(' '); } }
		write("PLAN", "class=" + classifications + " pendingReview=" + pending + " reason=" + plan.getExplanation()
			+ " earnedBank=" + plan.getOwnership().at(itemId, VirtualLocation.BANK) + " deficit=" + plan.getProgress().getLegacyDeficits().quantity(itemId));
	}
	public void pending(boolean pending, String reason) { if (enabled) { write("REVIEW", "pending=" + pending + " reason=" + reason); } }
	public void committed(RunRecord run)
	{
		if (!enabled || !log.isDebugEnabled()) { return; }
		long bank = run.getOwnership().at(itemId, VirtualLocation.BANK);
		write("COMMIT", "success=true earnedBank=" + bank + " deficit=" + run.getItemProgress().getLegacyDeficits().quantity(itemId)
			+ " display=" + run.getItemProgress().getLegacyDeficits().display(itemId, bank));
	}
	public void failed(String reason) { if (enabled) { write("COMMIT", "success=false reason=" + reason); } }
	public void rendered(int id, long earnedBank, long balance)
	{
		if (enabled && id == itemId) { write("RENDER", "earnedBank=" + earnedBank + " display=" + balance); }
	}
	private synchronized void write(String stage, String message)
	{
		if (!enabled || !log.isDebugEnabled()) { return; }
		long now = System.nanoTime(); Long previous = last.get(stage);
		if (previous != null && now - previous < INTERVAL_NANOS) { return; }
		last.put(stage, now);
		log.debug("From Scratch item trace: item={} stage={} {}", itemId, stage, message);
	}
}

package com.fromscratch.tracking;

import com.fromscratch.model.RunRecord;
import com.fromscratch.model.VirtualItemOwnership;
import com.fromscratch.observation.ItemObservation;
import com.fromscratch.ui.ItemReview;
import java.util.Collections;
import java.util.Map;
import java.util.UUID;
import java.util.function.IntUnaryOperator;
import lombok.Getter;

/** Client-confined host-session gate. Merely observing a restored run never commits a reconciliation. */
public final class ItemTrackingSession
{
	private final ItemAccountingEngine engine = new ItemAccountingEngine();
	private final IntUnaryOperator noteBase;
	@Getter private RunRecord run;
	@Getter private boolean preparing = true;
	@Getter private ItemReview review;
	@Getter private boolean reviewRequested;
	private UUID reviewSession;
	private boolean cancellableReview;
	@Getter private AccountingPlan lastPlan;
	@Getter private String message = "Checking saved item holdings when your bank is available.";
	public ItemTrackingSession(RunRecord run, IntUnaryOperator noteBase, boolean freshActivation)
	{
		this.run = run; this.noteBase = noteBase;
	}
	public void requestReview()
	{
		cancellableReview = !preparing;
		preparing = true; reviewRequested = true; review = null; message = "Review your item changes in Account Tools.";
	}
	public void cancelReview(UUID token)
	{
		if (review != null && !review.getToken().equals(token)) { return; }
		if (cancellableReview) { preparing = false; reviewRequested = false; message = "Item tracking active."; }
		review = null; cancellableReview = false;
	}
	public void changed() { review = null; }
	/** Return only automatic candidates; review proposals remain inert until confirm(). */
	public AccountingPlan observe(ItemObservation observation)
	{
		lastPlan = null;
		if (observation == null || observation.getHoldings() == null || !observation.isStable())
		{
			review = null;
			if (preparing && observation != null)
			{
				message = observation.isBankOpen() && !observation.getProgress().ready(com.fromscratch.model.SnapshotLocation.BANK)
					? "Keep the normal bank open while its contents load."
					: !observation.isStable() ? "Let item movements finish, then review the settled comparison."
					: "Complete the remaining observation steps. Empty containers are valid.";
			}
			else if (observation != null && observation.getHoldings() == null)
			{
				message = com.fromscratch.ui.PreparationChecklist.instruction(observation.getProgress()) + " Previously saved ownership is preserved.";
			}
			return null;
		}
		if (!preparing) { message = "Item tracking active."; }
		if (preparing)
		{
			if (!observation.isBankOpen()) { review = null; return null; }
			if (review != null && observation.getSessionId().equals(reviewSession) && review.getCurrent().equals(observation.getHoldings())) { return null; }
			AccountingPlan plan = engine.plan(run, observation, noteBase, true, false, Collections.emptyMap(), "");
			lastPlan = plan;
			boolean transfersOnly = plan.getTransactions().stream().allMatch(entry -> entry.getCategory() == ItemTransaction.Category.TRANSFER
				|| entry.getLegacyWithdrawalChange() != 0 || entry.getItemId() == -1);
			if (!reviewRequested && !observation.isUncertainBankChange() && (transfersOnly
				|| run.getItemProgress().getPhysical().equals(observation.getHoldings()) && plan.getOwnership().equals(run.getOwnership())))
			{ return plan; } // unchanged sessions can safely reopen tracking without an approval or speculative credit
			review = new ItemReview(UUID.randomUUID(), run.getItemProgress().getPhysical(), observation.getHoldings(),
				run.getOwnership(), run.getItemProgress().getLegacyDeficits(), plan);
			reviewSession = observation.getSessionId();
			reviewRequested = true;
			message = plan.getExplanation(); return null;
		}
		if (run.getItemProgress().getPhysical().equals(observation.getHoldings()) && !observation.isUncertainBankChange()) { return null; }
		AccountingPlan plan = engine.plan(run, observation, noteBase, false, false, Collections.emptyMap(), "");
		lastPlan = plan;
		if (plan.isReviewRequired()) { preparing = true; reviewRequested = true; review = null; message = plan.getExplanation(); return null; }
		return plan;
	}
	public AccountingPlan confirm(UUID token, ItemObservation observation, Map<Integer, VirtualItemOwnership> corrections,
		String reason, boolean permanentlyRemoved)
	{
		return confirm(token, observation, corrections, reason, permanentlyRemoved, null);
	}
	public AccountingPlan confirm(UUID token, ItemObservation observation, ItemReviewEdits edits)
	{
		return confirm(token, observation, edits.getOwnership(), edits.getReason(), false, edits);
	}
	private AccountingPlan confirm(UUID token, ItemObservation observation, Map<Integer, VirtualItemOwnership> corrections,
		String reason, boolean permanentlyRemoved, ItemReviewEdits edits)
	{
		if (!preparing || review == null || !review.getToken().equals(token) || observation == null || !observation.isStable()
			|| !observation.getSessionId().equals(reviewSession) || !observation.isBankOpen() || observation.getHoldings() == null || !review.getCurrent().equals(observation.getHoldings()))
		{ review = null; throw new IllegalStateException("The observed items changed. Review a fresh comparison before confirming."); }
		return engine.plan(run, observation, noteBase, true, permanentlyRemoved, corrections, reason, edits);
	}
	public void committed(RunRecord saved)
	{
		if (!run.getState().getRunId().equals(saved.getState().getRunId())) { throw new IllegalArgumentException("Run changed during item commit"); }
		run = saved; preparing = false; reviewRequested = false; cancellableReview = false; review = null; message = "Item tracking active.";
	}
}

package com.fromscratch.tracking;

import com.fromscratch.SnapshotFixtures;
import com.fromscratch.model.RunRecord;
import com.fromscratch.model.VirtualItemOwnership;
import com.fromscratch.model.VirtualLocation;
import com.fromscratch.observation.ItemObservation;
import java.util.*;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;
import static com.fromscratch.tracking.TrackingFixtures.*;

public class ItemTrackingSessionTest
{
	private ItemTrackingSession ready()
	{
		ItemTrackingSession session = new ItemTrackingSession(run(100, 0, 0, 0, 0, 0), id -> id, false);
		ItemObservation observation = observation(holdings(100, 0, 0), 2);
		AccountingPlan confirmed = session.observe(observation); assertNotNull(confirmed); assertNull(session.getReview());
		session.committed(session.getRun().withItems(confirmed)); return session;
	}
	@Test public void restoredRunNeverCreditsBeforeHostReviewConfirmation()
	{
		ItemTrackingSession session = new ItemTrackingSession(run(100, 0, 0, 0, 0, 0), id -> id, false);
		assertNull(session.observe(observation(holdings(130, 0, 0), 2)));
		assertEquals(0, session.getRun().getOwnership().total(ItemID.SHARK)); assertNotNull(session.getReview());
		assertEquals(30, session.getReview().getProposed().total(ItemID.SHARK));
	}
	@Test public void unchangedSessionAutomaticallyReopensTrackingAndNeverRepeatsDuringPlay()
	{
		ItemTrackingSession session = ready(); assertFalse(session.isPreparing());
		assertNull(session.observe(observation(holdings(100, 0, 0), 3))); assertNull(session.getReview());
		assertFalse(session.isPreparing());
	}
	@Test public void normalAcquisitionProposesDurableUpdateOnlyAfterBaselineIsEstablished()
	{
		ItemTrackingSession session = ready(); AccountingPlan plan = session.observe(observation(holdings(100, 20, 0), 3));
		assertNotNull(plan); assertFalse(plan.isReviewRequired()); assertEquals(0, session.getRun().getOwnership().total(ItemID.SHARK));
		session.committed(session.getRun().withItems(plan)); assertEquals(20, session.getRun().getOwnership().total(ItemID.SHARK));
	}
	@Test public void ambiguousLossReturnsToGuidedReview()
	{
		ItemTrackingSession session = ready(); assertNull(session.observe(observation(holdings(99, 0, 0), 3)));
		assertTrue(session.isPreparing()); assertEquals(100, session.getRun().getItemProgress().getPhysical().total(ItemID.SHARK));
	}
	@Test(expected = IllegalStateException.class) public void changedContentsInvalidateTheConfirmationToken()
	{
		ItemTrackingSession session = ready(); session.requestReview(); session.observe(observation(holdings(100, 0, 0), 3));
		session.confirm(session.getReview().getToken(), observation(holdings(101, 0, 0), 4), Collections.emptyMap(), "", false);
	}
	@Test public void tabChangesDoNotReplaceAnUnchangedReviewToken()
	{
		ItemTrackingSession session = ready(); session.requestReview(); session.observe(observation(holdings(100, 0, 0), 3));
		UUID token = session.getReview().getToken(); session.observe(observation(holdings(100, 0, 0), 4));
		assertEquals(token, session.getReview().getToken());
	}
	@Test public void freshIdenticalInitialSnapshotNeedsNoSecondUserApproval()
	{
		RunRecord run = RunRecord.activate(SnapshotFixtures.CHARACTER_A, UUID.randomUUID(), snapshot(holdings(100, 0, 0)), TIME);
		ItemTrackingSession session = new ItemTrackingSession(run, id -> id, true);
		assertNotNull(session.observe(observation(holdings(100, 0, 0), 1)));
	}
	@Test public void freshActivationWithInterveningChangesRequiresReview()
	{
		RunRecord run = RunRecord.activate(SnapshotFixtures.CHARACTER_A, UUID.randomUUID(), snapshot(holdings(100, 0, 0)), TIME);
		ItemTrackingSession session = new ItemTrackingSession(run, id -> id, true);
		assertNull(session.observe(observation(holdings(101, 0, 0), 1))); assertNotNull(session.getReview());
	}
	@Test public void manualCorrectionIsBoundedAndAuditable()
	{
		ItemTrackingSession session = ready(); session.requestReview(); ItemObservation observation = observation(holdings(100, 0, 0), 3); session.observe(observation);
		VirtualItemOwnership correction = new VirtualItemOwnership(1, Collections.singletonMap(VirtualLocation.BANK, 1L));
		AccountingPlan plan = session.confirm(session.getReview().getToken(), observation, Collections.singletonMap(ItemID.SHARK, correction), "Correcting an ambiguous earned copy", false);
		assertEquals(1, plan.getOwnership().total(ItemID.SHARK));
		assertEquals(ItemTransaction.Confidence.MANUAL, plan.getTransactions().get(0).getConfidence());
	}
	@Test(expected = IllegalArgumentException.class) public void manualCorrectionsCannotExceedPhysicalQuantities()
	{
		ItemTrackingSession session = ready(); session.requestReview(); ItemObservation observation = observation(holdings(100, 0, 0), 3); session.observe(observation);
		session.confirm(session.getReview().getToken(), observation, Collections.singletonMap(ItemID.SHARK,
			new VirtualItemOwnership(101, Collections.singletonMap(VirtualLocation.BANK, 101L))), "Invalid", false);
	}
}

package com.fromscratch.tracking;

import com.fromscratch.model.*;
import com.fromscratch.overlay.VirtualQuantityFormatter;
import java.util.*;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;
import static com.fromscratch.tracking.TrackingFixtures.*;

public class LegacyBankDeficitsTest
{
	@Test public void legacyDeficitDoesNotUseOrPermitNegativeOwnership()
	{
		RunRecord old = run(100, 0, 0, 0, 0, 0); AccountingPlan next = plan(old, holdings(99, 1, 0), 2);
		assertEquals(-1, next.getProgress().getLegacyDeficits().display(ItemID.SHARK, 0));
		assertEquals(0, next.getOwnership().total(ItemID.SHARK)); assertEquals(0, old.getItemProgress().getLegacyDeficits().quantity(ItemID.SHARK));
	}
	@Test public void earnedCopiesDoNotRepayOutstandingLegacyWithdrawals()
	{
		RunRecord old = run(100, 0, 0, 0, 0, 0); RunRecord withdrawn = old.withItems(plan(old, holdings(98, 2, 0), 2));
		RunRecord earned = withdrawn.withItems(plan(withdrawn, holdings(98, 5, 0), 3));
		AccountingPlan depositEarned = plan(earned, holdings(101, 2, 0), 4);
		assertEquals(3, depositEarned.getOwnership().at(ItemID.SHARK, VirtualLocation.BANK));
		assertEquals(2, depositEarned.getProgress().getLegacyDeficits().quantity(ItemID.SHARK));
		assertEquals(1, depositEarned.getProgress().getLegacyDeficits().display(ItemID.SHARK, 3));
		assertEquals(1, depositEarned.getProgress().getAcquisitions().size());
	}
	@Test public void legacyReturnDoesNotAlterLifetimeAcquisitions()
	{
		RunRecord old = run(100, 0, 0, 0, 0, 0); RunRecord withdrawn = old.withItems(plan(old, holdings(98, 2, 0), 2));
		RunRecord earned = withdrawn.withItems(plan(withdrawn, holdings(98, 5, 0), 3));
		RunRecord deposited = earned.withItems(plan(earned, holdings(101, 2, 0), 4));
		AccountingPlan returned = plan(deposited, holdings(103, 0, 0), 5);
		assertEquals(0, returned.getProgress().getLegacyDeficits().quantity(ItemID.SHARK)); assertEquals(3, returned.getOwnership().total(ItemID.SHARK));
		assertEquals(deposited.getItemProgress().getUnlocked(), returned.getProgress().getUnlocked());
		assertEquals(deposited.getItemProgress().getAcquisitions(), returned.getProgress().getAcquisitions());
	}
	@Test public void normalSessionLocationOnlyChangesAutomaticallyReopenTracking()
	{
		ItemTrackingSession session = new ItemTrackingSession(run(100, 0, 0, 0, 0, 0), id -> id, false);
		AccountingPlan automatic = session.observe(observation(holdings(99, 1, 0), 2));
		assertNotNull(automatic); assertNull(session.getReview()); assertEquals(0, automatic.getOwnership().total(ItemID.SHARK));
		session.committed(session.getRun().withItems(automatic)); assertFalse(session.isPreparing());
	}
	@Test public void explicitNotedLegacyWithdrawalAndReturnUseOneDeficitIdentity()
	{
		int noted = ItemID.SHARK + 1; RunRecord run = run(100, 0, 0, 0, 0, 0);
		AccountingPlan withdrawal = ENGINE.plan(run, observation(holdings(items(ItemID.SHARK, 98), items(noted, 2), Collections.emptyMap()), 2),
			id -> id == noted ? ItemID.SHARK : id, false, false, Collections.emptyMap(), "");
		assertEquals(2, withdrawal.getProgress().getLegacyDeficits().quantity(ItemID.SHARK));
		AccountingPlan returned = ENGINE.plan(run.withItems(withdrawal), observation(holdings(100, 0, 0), 3),
			id -> id == noted ? ItemID.SHARK : id, false, false, Collections.emptyMap(), "");
		assertEquals(0, returned.getProgress().getLegacyDeficits().quantity(ItemID.SHARK)); assertEquals(0, returned.getOwnership().total(ItemID.SHARK));
	}
	@Test public void checkedExtremeSignedDisplayHasAMinusWithoutOverflow()
	{
		LegacyBankDeficits deficits = new LegacyBankDeficits(Collections.singletonMap(ItemID.SHARK, Long.MAX_VALUE));
		assertEquals(-Long.MAX_VALUE, deficits.display(ItemID.SHARK, 0));
		assertEquals("-1", VirtualQuantityFormatter.signed(-1)); assertEquals("-2500", VirtualQuantityFormatter.signed(-2500));
		assertEquals("-9223372036854M", VirtualQuantityFormatter.signed(-Long.MAX_VALUE));
	}
	@Test(expected = IllegalArgumentException.class) public void negativeDeficitsAreRejected() { new LegacyBankDeficits(Collections.singletonMap(ItemID.SHARK, -1L)); }
	@Test(expected = ArithmeticException.class) public void accumulatingBeyondLongRangeCannotWrap()
	{
		RunRecord run = run(100, 0, 0, 0, 0, 0); ItemProgress p = run.getItemProgress();
		ItemProgress max = new ItemProgress(p.getPhysical(), p.getReturns(), p.getUnlocked(), p.getRecent(), p.getAcquisitions(), p.getSessionId(), p.getTick(),
			p.getObservedAt(), p.getLedgerHead(), p.getSequence(), true, new LegacyBankDeficits(Collections.singletonMap(ItemID.SHARK, Long.MAX_VALUE)));
		RunRecord fixture = new RunRecord(run.getState(), run.getRevision(), null, run.getSnapshot(), run.getOwnership(), max);
		plan(fixture, holdings(99, 1, 0), 2);
	}
}

package com.fromscratch.tracking;

import com.fromscratch.SnapshotFixtures;
import com.fromscratch.model.*;
import com.fromscratch.observation.CaptureProgress;
import com.fromscratch.observation.ItemObservation;
import java.time.Instant;
import java.util.*;
import net.runelite.api.gameval.ItemID;

/** Synthetic character/run/container state only; never reads local account data. */
public final class TrackingFixtures
{
	public static final Instant TIME = Instant.parse("2026-10-21T12:00:00Z");
	public static final UUID SESSION = UUID.fromString("00000000-0000-0000-0000-000000000004");
	public static final ItemAccountingEngine ENGINE = new ItemAccountingEngine();
	private TrackingFixtures() { }
	public static Holdings holdings(long bank, long inventory, long equipment)
	{
		return holdings(items(ItemID.SHARK, bank), items(ItemID.SHARK, inventory), items(ItemID.SHARK, equipment));
	}
	public static Map<Integer, Long> items(int id, long quantity) { return quantity == 0 ? Collections.emptyMap() : Collections.singletonMap(id, quantity); }
	public static Holdings holdings(Map<Integer, Long> bank, Map<Integer, Long> inventory, Map<Integer, Long> equipment)
	{
		Map<SnapshotLocation, Map<Integer, Long>> locations = new EnumMap<>(SnapshotLocation.class);
		locations.put(SnapshotLocation.BANK, bank); locations.put(SnapshotLocation.INVENTORY, inventory); locations.put(SnapshotLocation.EQUIPMENT, equipment);
		return new Holdings(locations);
	}
	public static LegacySnapshot snapshot(Holdings holdings)
	{
		Map<SnapshotLocation, ContainerSnapshot> locations = new EnumMap<>(SnapshotLocation.class);
		holdings.getLocations().forEach((location, items) -> locations.put(location, new ContainerSnapshot(items, items.size())));
		return new LegacySnapshot(TIME, locations);
	}
	public static ItemObservation observation(Holdings holdings, long tick)
	{
		return observation(holdings, tick, Collections.emptyMap(), SESSION);
	}
	public static ItemObservation observation(Holdings holdings, long tick, Map<Integer, ItemObservation.Action> actions, UUID session)
	{
		return new ItemObservation(session, tick, TIME.plusSeconds(tick), CaptureProgress.from(snapshot(holdings)), holdings, true, true, false, actions);
	}
	public static RunRecord run(long bank, long inventory, long equipment, long vb, long vi, long ve)
	{
		RunRecord run = RunRecord.activate(SnapshotFixtures.CHARACTER_A, UUID.randomUUID(), snapshot(holdings(bank, inventory, equipment)), TIME);
		Map<VirtualLocation, Long> locations = new EnumMap<>(VirtualLocation.class);
		locations.put(VirtualLocation.BANK, vb); locations.put(VirtualLocation.INVENTORY, vi); locations.put(VirtualLocation.EQUIPMENT, ve);
		run = run.withOwnership(VirtualOwnership.empty().withItem(ItemID.SHARK, new VirtualItemOwnership(vb + vi + ve, locations)));
		return run.withItems(ENGINE.plan(run, observation(holdings(bank, inventory, equipment), 1), id -> id, true, false, Collections.emptyMap(), ""));
	}
	public static AccountingPlan plan(RunRecord run, Holdings next, long tick)
	{
		return ENGINE.plan(run, observation(next, tick), id -> id, false, false, Collections.emptyMap(), "");
	}
}

package com.fromscratch.ui;

import com.fromscratch.model.ContainerSnapshot;
import com.fromscratch.model.LegacySnapshot;
import com.fromscratch.model.SnapshotLocation;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Font;
import java.awt.GridLayout;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.time.format.FormatStyle;
import java.text.NumberFormat;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JOptionPane;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.DynamicGridLayout;
import net.runelite.client.ui.PluginPanel;
import net.runelite.api.gameval.ItemID;

/** Setup previews and the progression dashboard. Rendering and accounting stay outside Swing. */
public final class FromScratchPanel extends PluginPanel
{
	static final Color PURPLE = new Color(0xB450FF);
	static final Color GOLD = new Color(0xFFD54F);

	private static final String SETUP_TEXT = "Open your bank to capture existing bank, inventory, and equipped items. Special storage is excluded.";
	private static final String SETUP_DETAILS = "All captured items and coins become legacy. POH, seed vault, death storage, minigame rewards and other special storage are excluded. Nothing moves automatically.";
	private boolean showSetupDetails;
	private boolean beforeInitialization;
	private final JPanel setup = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
	private final JPanel tools = new JPanel(new DynamicGridLayout(0, 1, 0, 4));
	private boolean historyExpanded;
	private final JLabel durationValue = new JLabel("0h 00m");
	private final JLabel unlockedValue = new JLabel("0");
	private final JLabel recentValue = new JLabel("No acquisitions recorded.");

	public FromScratchPanel(boolean showHelp)
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			throw new IllegalStateException("Create the From Scratch panel on the EDT");
		}
		JLabel title = new JLabel("From Scratch");
		title.setForeground(PURPLE);
		title.setFont(title.getFont().deriveFont(Font.BOLD, 20f));
		add(title);
		add(new JLabel("Dashboard"));
		setup.setBackground(ColorScheme.DARK_GRAY_COLOR);
		add(setup);

		add(metric("Total Value Gained", "0 GP", GOLD));
		add(metric("Current Net Worth", "0 GP", GOLD));
		add(metric("Spendable GP", "0 GP", GOLD));
		add(metric("Active run duration", durationValue, Color.WHITE));
		add(metric("Items Unlocked", unlockedValue, PURPLE));
		add(new JLabel("Recent acquisitions")); add(recentValue);
		add(new JLabel("GP and value metrics are not tracked yet."));
		tools.setBackground(ColorScheme.DARK_GRAY_COLOR); add(tools);

		setFoundationHelpVisible(showHelp);
		render(SetupView.signedOut(), SetupActions.NONE);
	}

	/** Replaces presentation only; button callbacks return local requests to the controller. */
	void render(SetupView view, SetupActions actions)
	{
		setup.removeAll();
		tools.removeAll();
		durationValue.setText(RunDuration.format(view.getElapsedMinutes()));
		durationValue.setToolTipText("Elapsed time since run start, including time away.");
		unlockedValue.setText(view.getSaved() == null ? "0" : Long.toString(view.getSaved().getEconomy().getItemsUnlocked()));
		recentValue.setText(recentAcquisitions(view));
		String status;
		switch (view.getMode())
		{
			case ACTIVE: status = "Active"; break;
			case RECONCILING: status = "Active — item changes need review"; break;
			case INITIALIZING: status = "Initializing"; break;
			case SAVING: status = view.getSaved() != null && view.getSaved().getSnapshot() != null
				? "Active (resetting)" : "Initializing (saving)"; break;
			case LOADING: status = "Loading"; break;
			case ERROR: status = "Storage error"; break;
			default: status = "Not Started";
		}
		setup.add(new JLabel("Status: " + status));
		if (view.getMode() != SetupView.Mode.ACTIVE)
		{
			setup.add(message("Run status", view.getMode() == SetupView.Mode.INITIALIZING
				? PreparationChecklist.instruction(view.getProgress()) : view.getMode() == SetupView.Mode.RECONCILING
				? "Review item changes in Account Tools below." : view.getMessage()));
		}
		beforeInitialization = view.getMode() == SetupView.Mode.NOT_STARTED || view.getMode() == SetupView.Mode.SIGNED_OUT;
		if (beforeInitialization)
		{
			setup.add(message("Setup", SETUP_TEXT));
		}
		refreshSetupTooltip();
		LegacySnapshot summary = view.getMode() == SetupView.Mode.INITIALIZING ? view.getPreview() : null;
		if (view.getSaved() != null && view.getSaved().getSnapshot() != null && view.getMode() != SetupView.Mode.INITIALIZING)
		{
			String started = DateTimeFormatter.ofLocalizedDateTime(FormatStyle.MEDIUM).withLocale(Locale.getDefault())
				.withZone(ZoneId.systemDefault()).format(view.getSaved().getState().getStartedAt());
			setup.add(message("Run started", started));
		}
		if (view.getMode() == SetupView.Mode.INITIALIZING)
		{
			setup.add(new JLabel("Prepare Your Account"));
			for (String step : PreparationChecklist.steps(view.getProgress())) { setup.add(new JLabel(step)); }
			setup.add(new JLabel(PreparationChecklist.step(false, "Review and confirm your snapshot.")));
			if (summary == null)
			{
				for (SnapshotLocation location : SnapshotLocation.values())
				{
					ContainerSnapshot partial = view.getProgress().getContainers().get(location);
					if (partial != null) { addSummary("Observed " + location.name().toLowerCase(Locale.ROOT), partial); }
				}
			}
		}
		if (summary != null)
		{
			addSummary("Legacy bank", summary.at(SnapshotLocation.BANK));
			addSummary("Legacy inventory", summary.at(SnapshotLocation.INVENTORY));
			addSummary("Legacy equipment", summary.at(SnapshotLocation.EQUIPMENT));
		}
		if (view.getMode() == SetupView.Mode.NOT_STARTED || view.getMode() == SetupView.Mode.SIGNED_OUT)
		{
			JButton begin = button("Begin From Scratch", actions::begin);
			begin.setEnabled(view.getMode() == SetupView.Mode.NOT_STARTED);
			setup.add(begin);
		}
		if (view.getMode() == SetupView.Mode.INITIALIZING)
		{
			JButton confirm = button("Confirm Snapshot", () ->
			{
				if (JOptionPane.showConfirmDialog(this, "Activate this run using the displayed bank, inventory and equipment?\n"
					+ "All captured items and coins become legacy; virtual ownership and GP start at zero.",
					"Confirm From Scratch snapshot", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION)
				{
					actions.confirm(view.getReviewToken());
				}
			});
			confirm.setEnabled(view.getPreview() != null && view.getReviewToken() != null
				&& view.getProgress().getContainers().size() == SnapshotLocation.values().length);
			setup.add(confirm);
			setup.add(button("Cancel Setup", actions::cancel));
		}
		if (view.getMode() == SetupView.Mode.ACTIVE || view.getMode() == SetupView.Mode.RECONCILING)
		{
			tools.add(new JLabel("Account Tools"));
			tools.add(message("Update Progress", "Played on mobile or another computer? Update your From Scratch progress when you return to this PC."));
			tools.add(button("Update Progress", () ->
			{
				if (view.getItemReview() != null) { ItemReviewDialog.show(this, view, actions); }
				else { actions.reviewItems(); }
			}));
			if (view.getMode() == SetupView.Mode.ACTIVE && view.getProgress().getContainers().size() < SnapshotLocation.values().length)
			{ tools.add(message("Item observation", PreparationChecklist.instruction(view.getProgress()))); }
			if (view.getMode() == SetupView.Mode.RECONCILING)
			{
				for (String step : PreparationChecklist.steps(view.getProgress())) { tools.add(new JLabel(step)); }
				tools.add(message("Next step", view.getItemReview() == null ? PreparationChecklist.instruction(view.getProgress()) : "Review the changed items, then apply your decisions."));
				JButton review = button("Review changes", () -> ItemReviewDialog.show(this, view, actions));
				review.setEnabled(view.getItemReview() != null); tools.add(review);
			}
			addLegacyDeficits(view);
			tools.add(button("Reset From Scratch", () ->
			{
				if (JOptionPane.showConfirmDialog(this, "Back up and reset this From Scratch run?\n"
					+ "You must begin again and confirm a fresh snapshot. Real OSRS items are unchanged.",
					"Confirm From Scratch reset", JOptionPane.YES_NO_OPTION, JOptionPane.WARNING_MESSAGE) == JOptionPane.YES_OPTION)
				{
					actions.reset(view.getSaved().getState().getRunId());
				}
			}));
			tools.add(button((historyExpanded ? "▼ " : "▶ ") + "Transaction History", () -> { historyExpanded = !historyExpanded; render(view, actions); }));
			if (historyExpanded) { tools.add(button("View recent transactions", () -> showHistory(view))); }
		}
		if (view.getMode() == SetupView.Mode.ERROR) { setup.add(button("Retry Load", actions::retry)); }
		if (view.isWriting())
		{
			for (java.awt.Component component : setup.getComponents()) { if (component instanceof JButton) { component.setEnabled(false); } }
			for (java.awt.Component component : tools.getComponents()) { if (component instanceof JButton) { component.setEnabled(false); } }
		}
		revalidate();
		repaint();
	}

	private static String recentAcquisitions(SetupView view)
	{
		if (view.getSaved() == null || view.getSaved().getItemProgress() == null || view.getSaved().getItemProgress().getAcquisitions().isEmpty()) { return "No acquisitions recorded."; }
		StringBuilder text = new StringBuilder("<html>"); int count = 0;
		for (com.fromscratch.tracking.ItemTransaction entry : view.getSaved().getItemProgress().getAcquisitions())
		{
			if (count++ == 5) { break; }
			String name = view.getItemNames().getOrDefault(entry.getItemId(), "Item #" + entry.getItemId());
			text.append(name.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;"))
				.append(" × ").append(entry.getVirtualChange()).append("<br>");
		}
		return text.append("</html>").toString();
	}
	private void showHistory(SetupView view)
	{
		StringBuilder text = new StringBuilder("Most recent 50 item changes. Full history is saved locally on this PC.\n\n");
		for (com.fromscratch.tracking.ItemTransaction entry : view.getSaved().getItemProgress().getRecent())
		{
			text.append(entry.getTime()).append(" | ").append(entry.getCategory()).append(" | ")
				.append(entry.getItemId() < 0 ? "Progress check" : view.getItemNames().getOrDefault(entry.getItemId(), "Item #" + entry.getItemId()))
				.append(" | quantity ").append(entry.getQuantity()).append(" | virtual change ").append(entry.getVirtualChange())
				.append(" | ").append(entry.getConfidence()).append("\n").append(entry.getReason()).append("\n\n");
		}
		javax.swing.JTextArea area = new javax.swing.JTextArea(text.toString()); area.setEditable(false);
		javax.swing.JScrollPane scroll = new javax.swing.JScrollPane(area); scroll.setPreferredSize(new java.awt.Dimension(800, 400));
		JOptionPane.showMessageDialog(this, scroll, "From Scratch transaction history", JOptionPane.PLAIN_MESSAGE);
	}
	private void addLegacyDeficits(SetupView view)
	{
		if (view.getSaved() == null || view.getSaved().getItemProgress() == null) { return; }
		view.getSaved().getItemProgress().getLegacyDeficits().getItems().forEach((id, quantity) ->
		{
			String name = view.getItemNames().getOrDefault(id, "Unknown item #" + id);
			boolean absent = view.getSaved().getItemProgress().getPhysical().at(id, SnapshotLocation.BANK) == 0;
			tools.add(message("Legacy withdrawal", name + ": -" + quantity + (absent ? " (not currently in bank)" : " outstanding")
				+ ". Return legacy copies or resolve this in Update Progress."));
		});
	}

	private void addSummary(String title, ContainerSnapshot container)
	{
		NumberFormat numbers = NumberFormat.getIntegerInstance(Locale.US);
		setup.add(message(title, numbers.format(container.getQuantities().size()) + " item types; "
			+ numbers.format(container.getOccupiedSlots()) + " occupied slots; " + numbers.format(container.getTotalQuantity())
			+ " units. Legacy coins: " + numbers.format(container.quantity(ItemID.COINS)) + " GP."));
	}

	private static JButton button(String title, Runnable action)
	{
		JButton button = new JButton(title);
		button.addActionListener(event -> action.run());
		return button;
	}

	/** Preserves the existing config key; optional detail uses a tooltip, never a second instruction section. */
	void setFoundationHelpVisible(boolean visible)
	{
		showSetupDetails = visible;
		refreshSetupTooltip();
	}

	private void refreshSetupTooltip()
	{
		setToolTipText(beforeInitialization && showSetupDetails ? SETUP_DETAILS : null);
	}

	private static JPanel metric(String name, String value, Color color)
	{
		return metric(name, new JLabel(value), color);
	}

	private static JPanel metric(String name, JLabel amount, Color color)
	{
		JPanel card = new JPanel(new GridLayout(0, 1, 0, 4));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(8, 8, 8, 8));
		card.add(new JLabel(name));
		amount.setForeground(color);
		amount.setFont(amount.getFont().deriveFont(Font.BOLD, 18f));
		card.add(amount);
		return card;
	}

	private static JPanel message(String title, String text)
	{
		JPanel section = new JPanel(new BorderLayout(0, 4));
		section.setBackground(ColorScheme.DARK_GRAY_COLOR);
		section.setBorder(BorderFactory.createEmptyBorder(8, 2, 8, 2));
		section.add(new JLabel(title), BorderLayout.NORTH);
		String escaped = text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
		section.add(new JLabel("<html><body style='width: 153px'>" + escaped + "</body></html>"), BorderLayout.CENTER);
		return section;
	}
}

package com.fromscratch.ui;

import com.fromscratch.FromScratchPlugin;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

/** Owns exactly one navigation registration while enabled. All state is EDT-confined. */
@Singleton
public final class FromScratchSidebar
{
	private final Consumer<NavigationButton> addNavigation;
	private final Consumer<NavigationButton> removeNavigation;
	private NavigationButton navigation;
	private FromScratchPanel panel;
	private SetupView view = SetupView.signedOut();
	private SetupActions actions = SetupActions.NONE;

	public void bind(SetupActions actions)
	{
		requireEdt();
		this.actions = actions;
		if (panel != null) { panel.render(view, actions); }
	}

	/** Client callbacks deliver immutable data; Swing never reads game state directly. */
	public void update(SetupView updated)
	{
		SwingUtilities.invokeLater(() ->
		{
			view = updated;
			if (panel != null) { panel.render(view, actions); }
		});
	}

	@Inject
	public FromScratchSidebar(ClientToolbar toolbar)
	{
		this(toolbar::addNavigation, toolbar::removeNavigation);
	}

	// The narrow toolbar boundary permits lifecycle tests without a game client.
	FromScratchSidebar(Consumer<NavigationButton> addNavigation, Consumer<NavigationButton> removeNavigation)
	{
		this.addNavigation = addNavigation;
		this.removeNavigation = removeNavigation;
	}

	public void show(boolean showHelp)
	{
		requireEdt();
		if (navigation != null)
		{
			refresh(showHelp);
			return;
		}
		panel = new FromScratchPanel(showHelp);
		panel.render(view, actions);
		navigation = NavigationButton.builder()
			.tooltip("From Scratch")
			.icon(ImageUtil.loadImageResource(FromScratchPlugin.class, "icon.png"))
			.priority(6)
			.panel(panel)
			.build();
		addNavigation.accept(navigation);
	}

	public void refresh(boolean showHelp)
	{
		requireEdt();
		if (panel != null)
		{
			panel.setFoundationHelpVisible(showHelp);
		}
	}

	public void hide()
	{
		requireEdt();
		view = SetupView.signedOut();
		if (navigation != null)
		{
			removeNavigation.accept(navigation);
			navigation = null;
			panel = null;
		}
	}

	private static void requireEdt()
	{
		if (!SwingUtilities.isEventDispatchThread())
		{
			throw new IllegalStateException("Sidebar operations require the EDT");
		}
	}
}

package com.fromscratch.ui;

import java.awt.Component;
import java.awt.Container;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.SwingUtilities;
import net.runelite.client.ui.NavigationButton;
import org.junit.Test;

import static org.junit.Assert.*;

/** Exercises real Swing components and the navigation boundary, without starting RuneScape. */
public class FromScratchSidebarTest
{
	@Test
	public void repeatedShowRegistersOnlyOneButton() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			List<NavigationButton> added = new ArrayList<>();
			FromScratchSidebar sidebar = new FromScratchSidebar(added::add, button -> fail("Unexpected removal"));
			sidebar.show(true);
			sidebar.show(false);
			assertEquals(1, added.size());
			assertEquals("From Scratch", added.get(0).getTooltip());
			assertNotNull(added.get(0).getPanel());
			assertEquals(24, added.get(0).getIcon().getWidth());
		});
	}

	@Test
	public void disableRemovesTheRegisteredButtonExactlyOnce() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			List<NavigationButton> added = new ArrayList<>();
			List<NavigationButton> removed = new ArrayList<>();
			FromScratchSidebar sidebar = new FromScratchSidebar(added::add, removed::add);
			sidebar.hide();
			sidebar.show(true);
			sidebar.hide();
			sidebar.hide();
			sidebar.refresh(false);
			assertEquals(1, added.size());
			assertEquals(added, removed);
		});
	}

	@Test
	public void reenableCreatesOneFreshRegistration() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			List<NavigationButton> added = new ArrayList<>();
			List<NavigationButton> removed = new ArrayList<>();
			FromScratchSidebar sidebar = new FromScratchSidebar(added::add, removed::add);
			sidebar.show(true);
			sidebar.hide();
			sidebar.show(true);
			assertEquals(2, added.size());
			assertEquals(1, removed.size());
			assertNotSame(added.get(0), added.get(1));
		});
	}

	@Test
	public void helpSettingOnlyChangesSetupTooltip() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			FromScratchPanel panel = new FromScratchPanel(true);
			assertTrue(visibleText(panel).contains("Setup"));
			assertNotNull(panel.getToolTipText());
			panel.setFoundationHelpVisible(false);
			List<String> text = visibleText(panel);
			assertTrue(text.contains("Setup"));
			assertNull(panel.getToolTipText());
			assertFalse(text.contains("Milestone 2"));
			panel.setFoundationHelpVisible(true);
			assertTrue(visibleText(panel).contains("Setup"));
			assertNotNull(panel.getToolTipText());
		});
	}

	@Test
	public void dashboardDisplaysRequestedPrimaryMetrics() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
			List<String> text = visibleText(new FromScratchPanel(true));
			for (String label : new String[]{"Total Value Gained", "Current Net Worth", "Spendable GP",
				"Active run duration", "Items Unlocked", "Recent acquisitions"})
			{
				assertTrue(label, text.contains(label));
			}
			assertEquals(3, text.stream().filter("0 GP"::equals).count());
			assertTrue(text.contains("0"));
			assertTrue(text.contains("0h 00m"));
		});
	}

	@Test(expected = IllegalStateException.class)
	public void sidebarRejectsUiWorkOutsideTheEdt()
	{
		new FromScratchSidebar(button -> fail(), button -> fail()).show(true);
	}

	private static List<String> visibleText(Container container)
	{
		List<String> result = new ArrayList<>();
		for (Component component : container.getComponents())
		{
			if (!component.isVisible())
			{
				continue;
			}
			if (component instanceof JLabel)
			{
				result.add(((JLabel) component).getText());
			}
			if (component instanceof Container)
			{
				result.addAll(visibleText((Container) component));
			}
		}
		return result;
	}
}

package com.fromscratch.ui;

import com.fromscratch.model.VirtualOwnership;
import com.fromscratch.tracking.Holdings;
import java.util.UUID;
import lombok.Value;
import com.fromscratch.tracking.AccountingPlan;
import com.fromscratch.tracking.ItemTransaction;
import com.fromscratch.tracking.LegacyBankDeficits;
import java.util.List;
import java.util.Collections;

/** Immutable proposal presented on Swing; its token expires when observed holdings change. */
@Value
public class ItemReview
{
	UUID token;
	Holdings before;
	Holdings current;
	VirtualOwnership proposed;
	VirtualOwnership previous;
	String explanation;
	List<ItemTransaction> transactions;
	LegacyBankDeficits previousDeficits;
	LegacyBankDeficits proposedDeficits;
	public ItemReview(UUID token, Holdings before, Holdings current, VirtualOwnership proposed, VirtualOwnership previous, String explanation)
	{
		this(token, before, current, proposed, previous, explanation, Collections.emptyList(), LegacyBankDeficits.empty(), LegacyBankDeficits.empty());
	}
	public ItemReview(UUID token, Holdings before, Holdings current, VirtualOwnership previous,
		LegacyBankDeficits previousDeficits, AccountingPlan plan)
	{
		this(token, before, current, plan.getOwnership(), previous, plan.getExplanation(), plan.getTransactions(), previousDeficits, plan.getProgress().getLegacyDeficits());
	}
	private ItemReview(UUID token, Holdings before, Holdings current, VirtualOwnership proposed, VirtualOwnership previous,
		String explanation, List<ItemTransaction> transactions, LegacyBankDeficits previousDeficits, LegacyBankDeficits proposedDeficits)
	{
		this.token = token; this.before = before; this.current = current; this.proposed = proposed; this.previous = previous;
		this.explanation = explanation; this.transactions = Collections.unmodifiableList(new java.util.ArrayList<>(transactions));
		this.previousDeficits = previousDeficits; this.proposedDeficits = proposedDeficits;
	}
}

package com.fromscratch.ui;

import java.awt.BorderLayout;
import java.awt.Component;
import java.awt.Dimension;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.swing.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import javax.swing.table.TableColumn;
import javax.swing.table.TableRowSorter;

/** Player-only local decisions. Cancel never submits quantities; Apply revalidates on the client thread. */
final class ItemReviewDialog
{
	private ItemReviewDialog() { }
	static void show(Component parent, SetupView view, SetupActions actions)
	{
		ItemReview review = view.getItemReview(); if (review == null) { return; }
		ItemReviewTable model = new ItemReviewTable(review, view.getItemNames());
		JTable table = new JTable(model)
		{
			@Override public javax.swing.table.TableCellEditor getCellEditor(int row, int column)
			{
				return convertColumnIndexToModel(column) == 3
					? new DefaultCellEditor(new JComboBox<>(model.choices(convertRowIndexToModel(row)))) : super.getCellEditor(row, column);
			}
		};
		table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);
		for (int i = 0; i < model.getColumnCount(); i++) { table.getColumnModel().getColumn(i).setPreferredWidth(i == 0 ? 180 : i == 4 ? 330 : 145); }
		table.getColumnModel().getColumn(3).setCellEditor(new DefaultCellEditor(new JComboBox<>(ItemReviewTable.Decision.values())));
		TableRowSorter<ItemReviewTable> sorter = new TableRowSorter<>(model); table.setRowSorter(sorter);
		sorter.setSortKeys(java.util.Collections.singletonList(new RowSorter.SortKey(0, SortOrder.ASCENDING)));
		List<TableColumn> advancedColumns = new ArrayList<>();
		while (table.getColumnCount() > 5) { TableColumn column = table.getColumnModel().getColumn(5); advancedColumns.add(column); table.removeColumn(column); }
		JTextField search = new JTextField(); search.setToolTipText("Search item names");
		JComboBox<ItemReviewTable.Filter> filter = new JComboBox<>(ItemReviewTable.Filter.values());
		JCheckBox unchanged = new JCheckBox("Show unchanged items"); JCheckBox advanced = new JCheckBox("Advanced quantities");
		JLabel empty = new JLabel(); empty.setForeground(FromScratchPanel.PURPLE);
		Runnable refresh = () ->
		{
			if (table.isEditing()) { table.getCellEditor().stopCellEditing(); }
			model.filter((ItemReviewTable.Filter) filter.getSelectedItem(), search.getText(), unchanged.isSelected());
			empty.setText(!model.hasChanges() ? "No item changes detected." : model.getRowCount() == 0 ? "No changes match this filter." : model.getRowCount() + " items shown.");
		};
		search.getDocument().addDocumentListener(new DocumentListener()
		{
			public void insertUpdate(DocumentEvent e) { refresh.run(); }
			public void removeUpdate(DocumentEvent e) { refresh.run(); }
			public void changedUpdate(DocumentEvent e) { refresh.run(); }
		});
		filter.addActionListener(e -> refresh.run()); unchanged.addActionListener(e -> refresh.run());
		advanced.addActionListener(e ->
		{
			if (table.isEditing()) { table.getCellEditor().stopCellEditing(); }
			for (TableColumn column : advancedColumns) { if (advanced.isSelected()) { table.addColumn(column); } else { table.removeColumn(column); } }
		});
		JPanel filters = new JPanel(new java.awt.GridLayout(0, 2, 6, 4));
		filters.add(new JLabel("Search items")); filters.add(search); filters.add(filter); filters.add(unchanged); filters.add(advanced); filters.add(empty);
		JTextArea help = new JTextArea("Played on mobile or another computer? Update your From Scratch progress when you return to this PC.\n"
			+ "Only changed items are shown. Newly Earned uses the net gain, or one copy for an unchanged item; use Advanced quantities for a different amount.\n"
			+ "Gameplay completed entirely away from this PC may not be reconstructable. Only final holdings can be compared.");
		help.setEditable(false); help.setLineWrap(true); help.setWrapStyleWord(true); help.setOpaque(false);
		JPanel top = new JPanel(new BorderLayout(4, 8)); top.add(help, BorderLayout.NORTH); top.add(filters, BorderLayout.SOUTH);
		JPanel panel = new JPanel(new BorderLayout(8, 8)); panel.add(top, BorderLayout.NORTH);
		JScrollPane scroll = new JScrollPane(table); scroll.setPreferredSize(new Dimension(980, 300)); panel.add(scroll, BorderLayout.CENTER);
		JComboBox<ItemReviewTable.Decision> bulk = new JComboBox<>(ItemReviewTable.Decision.values());
		JButton selected = new JButton("Apply to selected items");
		selected.addActionListener(e ->
		{
			if (table.isEditing()) { table.getCellEditor().stopCellEditing(); }
			int[] rows = Arrays.stream(table.getSelectedRows()).map(table::convertRowIndexToModel).toArray();
			if (rows.length == 0) { JOptionPane.showMessageDialog(parent, "Select one or more items first."); return; }
			try { model.decide(rows, (ItemReviewTable.Decision) bulk.getSelectedItem()); refresh.run(); }
			catch (IllegalArgumentException ex) { JOptionPane.showMessageDialog(parent, ex.getMessage(), "Choose applicable items", JOptionPane.WARNING_MESSAGE); }
		});
		JTextField reason = new JTextField(); reason.setToolTipText("Optional explanation; selected decisions are recorded in item history");
		JPanel bottom = new JPanel(new java.awt.GridLayout(0, 2, 6, 4));
		bottom.add(bulk); bottom.add(selected); bottom.add(new JLabel("Explanation (optional)")); bottom.add(reason); panel.add(bottom, BorderLayout.SOUTH);
		refresh.run();
		while (JOptionPane.showOptionDialog(parent, panel, "Update Progress", JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE,
			null, new String[]{"Review and apply", "Cancel"}, "Review and apply") == JOptionPane.OK_OPTION)
		{
			try
			{
				if (table.isEditing() && !table.getCellEditor().stopCellEditing()) { continue; }
				if (!model.hasChanges()) { JOptionPane.showMessageDialog(parent, "No item changes detected."); continue; }
				com.fromscratch.tracking.ItemReviewEdits edits = model.edits(reason.getText());
				JTextArea summary = new JTextArea(model.details()); summary.setEditable(false);
				JScrollPane preview = new JScrollPane(summary); preview.setPreferredSize(new Dimension(850, 260));
				if (JOptionPane.showConfirmDialog(parent, preview, "Apply these item changes?", JOptionPane.YES_NO_OPTION, JOptionPane.QUESTION_MESSAGE) != JOptionPane.YES_OPTION) { continue; }
				actions.confirmUpdate(review.getToken(), edits); return;
			}
			catch (IllegalArgumentException | ArithmeticException ex) { JOptionPane.showMessageDialog(parent, ex.getMessage(), "Check item decisions", JOptionPane.WARNING_MESSAGE); }
		}
		actions.cancelUpdate(review.getToken());
	}
}

package com.fromscratch.ui;

import com.fromscratch.model.SnapshotLocation;
import com.fromscratch.model.VirtualItemOwnership;
import com.fromscratch.model.VirtualLocation;
import com.fromscratch.tracking.ItemReviewEdits;
import com.fromscratch.tracking.ItemTransaction;
import java.util.*;
import javax.swing.table.AbstractTableModel;
import net.runelite.api.gameval.ItemID;

/** Difference-focused local decisions. Exact IDs identify rows; names are presentation only. */
public final class ItemReviewTable extends AbstractTableModel
{
	public enum Filter
	{
		ALL("All Changes"), GAINS("Gains"), LOSSES("Losses"), REVIEW("Needs Review");
		private final String label;
		Filter(String label) { this.label = label; }
		@Override public String toString() { return label; }
	}
	public enum Decision
	{
		DETECTED("Use detected change"), EARNED("Newly Earned"), LEGACY("Existing Legacy"), RETURNED("Returned Item"),
		LOST("Lost / Consumed"), RESOLVE_DEFICIT("Resolve legacy withdrawal"), CUSTOM("Custom quantities");
		private final String label;
		Decision(String label) { this.label = label; }
		@Override public String toString() { return label; }
	}
	private static final String[] COLUMNS = {"Item", "Change", "Category", "Decision", "Result", "Earned in bank", "Earned in inventory", "Earned worn", "Earned elsewhere", "Legacy withdrawn"};
	private final ItemReview review;
	private final List<Row> all = new ArrayList<>();
	private final List<Row> visible = new ArrayList<>();
	public ItemReviewTable(ItemReview review, Map<Integer, String> names)
	{
		this.review = review;
		Set<Integer> ids = new TreeSet<>(review.getBefore().ids()); ids.addAll(review.getCurrent().ids());
		ids.addAll(review.getPrevious().getItems().keySet()); ids.addAll(review.getProposed().getItems().keySet());
		ids.addAll(review.getPreviousDeficits().getItems().keySet()); ids.addAll(review.getProposedDeficits().getItems().keySet()); ids.remove(ItemID.COINS);
		for (int id : ids) { all.add(new Row(id, names.getOrDefault(id, "Unknown item #" + id))); }
		filter(Filter.ALL, "", false);
	}
	public int getRowCount() { return visible.size(); }
	public int getColumnCount() { return COLUMNS.length; }
	public String getColumnName(int column) { return COLUMNS[column]; }
	@Override public Class<?> getColumnClass(int column) { return column == 1 ? Long.class : column == 3 ? Decision.class : Object.class; }
	public Object getValueAt(int row, int column)
	{
		Row item = visible.get(row);
		switch (column)
		{
			case 0: return item.name;
			case 1: return item.delta;
			case 2: return !item.changed ? "Unchanged" : item.delta > 0 ? "Gained — confirm source" : item.delta < 0 ? "Missing — review loss" : item.needsReview ? "Review ownership" : "Moved between containers";
			case 3: return item.decision;
			case 4: return "Bank " + item.quantities[0] + "; inventory " + item.quantities[1] + "; worn " + item.quantities[2] + "; legacy withdrawn " + item.quantities[4];
			default: return item.quantities[column - 5];
		}
	}
	public boolean isCellEditable(int row, int column) { return column == 3 || column >= 5; }
	@Override public void setValueAt(Object value, int row, int column)
	{
		Row item = visible.get(row);
		if (column == 3) { item.decide((Decision) value); }
		else if (column >= 5) { item.quantities[column - 5] = value; item.decision = Decision.CUSTOM; }
		fireTableRowsUpdated(row, row);
	}
	public int itemId(int row) { return visible.get(row).id; }
	public void filter(Filter filter, String search, boolean showUnchanged)
	{
		String query = search.toLowerCase(Locale.ROOT).strip(); visible.clear();
		for (Row row : all)
		{
			if (!showUnchanged && !row.changed || !row.name.toLowerCase(Locale.ROOT).contains(query)) { continue; }
			if (filter == Filter.GAINS && row.delta <= 0 || filter == Filter.LOSSES && row.delta >= 0
				|| filter == Filter.REVIEW && (!row.needsReview || row.decision != Decision.DETECTED)) { continue; }
			visible.add(row);
		}
		fireTableDataChanged();
	}
	/** Model indices must be converted from the JTable's current sorted view by the dialog. */
	public void decide(int[] rows, Decision decision)
	{
		for (int row : rows)
		{
			if (!Arrays.asList(choices(row)).contains(decision)) { throw new IllegalArgumentException(decision + " is not applicable to " + visible.get(row).name); }
		}
		for (int row : rows) { visible.get(row).decide(decision); } fireTableDataChanged();
	}
	public Decision[] choices(int row)
	{
		Row item = visible.get(row); List<Decision> choices = new ArrayList<>(); choices.add(Decision.DETECTED);
		if (review.getCurrent().total(item.id) > 0) { choices.add(Decision.EARNED); choices.add(Decision.LEGACY); choices.add(Decision.RETURNED); }
		if (item.delta < 0) { choices.add(Decision.LOST); }
		if (review.getProposedDeficits().quantity(item.id) > 0) { choices.add(Decision.RESOLVE_DEFICIT); }
		choices.add(Decision.CUSTOM); return choices.toArray(new Decision[0]);
	}
	public boolean hasChanges() { return all.stream().anyMatch(row -> row.changed || row.decision != Decision.DETECTED); }
	public Map<Integer, VirtualItemOwnership> corrections() { return edits("Reviewed item changes.").getOwnership(); }
	public ItemReviewEdits edits(String reason)
	{
		Map<Integer, VirtualItemOwnership> changes = new HashMap<>(); Map<Integer, Long> deficits = new HashMap<>();
		Set<Integer> returned = new HashSet<>(); Set<Integer> permanent = new HashSet<>();
		Map<Integer, String> decisions = new HashMap<>();
		for (Row row : all)
		{
			VirtualItemOwnership item = row.ownership();
			if (!item.equals(review.getProposed().item(row.id))) { changes.put(row.id, item); }
			long deficit = number(row.quantities[4], row.name);
			if (deficit != review.getProposedDeficits().quantity(row.id)) { deficits.put(row.id, deficit); }
			if (row.decision == Decision.RETURNED) { returned.add(row.id); }
			if (row.decision == Decision.LOST) { permanent.add(row.id); }
			if (row.decision != Decision.DETECTED) { decisions.put(row.id, row.decision.toString()); }
		}
		return new ItemReviewEdits(changes, deficits, returned, permanent, reason.isBlank() ? "Reviewed item decisions in Update Progress." : reason, decisions);
	}
	public String summary()
	{
		int changed = 0; int decided = 0; long units = 0;
		for (Row row : all)
		{
			if (row.changed || row.decision != Decision.DETECTED) { changed++; }
			if (row.decision != Decision.DETECTED) { decided++; }
			units = Math.addExact(units, Math.subtractExact(row.ownership().getTotal(), review.getPrevious().total(row.id)));
		}
		return changed + " changed item types; " + decided + " explicit decisions. Net earned copies: " + (units > 0 ? "+" : "") + units
			+ ". Only these confirmed observations and decisions will be applied.";
	}
	public String details()
	{
		StringBuilder text = new StringBuilder(summary()).append("\n\n");
		for (Row row : all)
		{
			if (!row.changed && row.decision == Decision.DETECTED) { continue; }
			text.append(row.name).append(" — ").append(row.decision).append("; physical change ")
				.append(row.delta).append("; earned copies ").append(review.getPrevious().total(row.id)).append(" → ")
				.append(row.ownership().getTotal()).append("; legacy withdrawn ").append(review.getPreviousDeficits().quantity(row.id))
				.append(" → ").append(row.quantities[4]).append('\n');
		}
		return text.toString();
	}
	private static long number(Object value, String name)
	{
		String text = String.valueOf(value);
		if (!text.matches("0|[1-9][0-9]*")) { throw new IllegalArgumentException("Enter whole, nonnegative quantities for " + name); }
		try { return Long.parseLong(text); } catch (NumberFormatException ex) { throw new IllegalArgumentException("Quantity is too large for " + name); }
	}
	private final class Row
	{
		final int id; final String name; final long delta; final boolean changed; final boolean needsReview;
		Decision decision = Decision.DETECTED; Object[] quantities = new Object[5];
		Row(int id, String name)
		{
			this.id = id; this.name = name; delta = review.getCurrent().total(id) - review.getBefore().total(id);
			boolean physical = false;
			for (SnapshotLocation location : SnapshotLocation.values()) { physical |= review.getCurrent().at(id, location) != review.getBefore().at(id, location); }
			changed = physical || !review.getPrevious().item(id).equals(review.getProposed().item(id))
				|| review.getPreviousDeficits().quantity(id) != review.getProposedDeficits().quantity(id);
			needsReview = delta != 0 || review.getPrevious().total(id) != review.getProposed().total(id)
				|| review.getTransactions().stream().anyMatch(entry -> entry.getItemId() == id && entry.getCategory() == ItemTransaction.Category.RECONCILIATION_ADJUSTMENT
				&& entry.getLegacyWithdrawalChange() == 0 && entry.getQuantity() > 0 && entry.getVirtualChange() == 0);
			set(review.getProposed().item(id)); quantities[4] = review.getProposedDeficits().quantity(id);
		}
		void set(VirtualItemOwnership item)
		{
			quantities[0] = item.at(VirtualLocation.BANK); quantities[1] = item.at(VirtualLocation.INVENTORY);
			quantities[2] = item.at(VirtualLocation.EQUIPMENT); quantities[3] = item.unallocated();
		}
		void decide(Decision next)
		{
			decision = next; quantities[4] = review.getProposedDeficits().quantity(id); set(review.getProposed().item(id));
			if (next == Decision.RESOLVE_DEFICIT) { quantities[4] = 0L; }
			long elsewhere = review.getProposed().item(id).unallocated();
			long previousHere = Math.min(review.getCurrent().total(id), Math.max(0, review.getPrevious().total(id) - elsewhere));
			if (next == Decision.LEGACY) { allocate(Math.addExact(elsewhere, previousHere)); }
			if (next == Decision.EARNED)
			{
				long extra = Math.min(delta > 0 ? delta : 1, review.getCurrent().total(id) - previousHere);
				allocate(Math.addExact(elsewhere, Math.addExact(previousHere, extra)));
			}
			if (next == Decision.RETURNED)
			{
				long acquired = review.getTransactions().stream().filter(entry -> entry.getItemId() == id && entry.getCategory() == ItemTransaction.Category.ACQUISITION)
					.mapToLong(ItemTransaction::getVirtualChange).reduce(0, Math::addExact);
				long returningHere = Math.min(review.getCurrent().total(id), Math.max(0, review.getProposed().total(id) - acquired - elsewhere));
				allocate(Math.addExact(elsewhere, returningHere));
				long bankReturn = Math.max(0, review.getCurrent().at(id, SnapshotLocation.BANK) - review.getBefore().at(id, SnapshotLocation.BANK));
				long earnedReturn = Math.min(bankReturn, Math.max(0, number(quantities[0], name) - review.getPrevious().at(id, VirtualLocation.BANK)));
				quantities[4] = Math.min(review.getProposedDeficits().quantity(id), Math.max(0, review.getPreviousDeficits().quantity(id) - (bankReturn - earnedReturn)));
			}
		}
		private void allocate(long total)
		{
			long left = total - Math.min(total, review.getProposed().item(id).unallocated());
			Map<VirtualLocation, Long> locations = new EnumMap<>(VirtualLocation.class);
			for (SnapshotLocation location : SnapshotLocation.values())
			{
				VirtualLocation virtual = VirtualLocation.valueOf(location.name());
				long value = Math.min(left, Math.min(review.getProposed().at(id, virtual), review.getCurrent().at(id, location)));
				locations.put(virtual, value); left -= value;
			}
			for (SnapshotLocation location : SnapshotLocation.values())
			{
				VirtualLocation virtual = VirtualLocation.valueOf(location.name()); long value = locations.get(virtual);
				long increase = Math.max(0, review.getCurrent().at(id, location) - review.getBefore().at(id, location));
				long add = Math.min(left, Math.min(increase, review.getCurrent().at(id, location) - value));
				locations.put(virtual, value + add); left -= add;
			}
			for (SnapshotLocation location : SnapshotLocation.values())
			{
				VirtualLocation virtual = VirtualLocation.valueOf(location.name()); long value = locations.get(virtual);
				long add = Math.min(left, review.getCurrent().at(id, location) - value); locations.put(virtual, value + add); left -= add;
			}
			set(new VirtualItemOwnership(total, locations));
		}
		VirtualItemOwnership ownership()
		{
			Map<VirtualLocation, Long> locations = new EnumMap<>(VirtualLocation.class); long total = 0;
			for (int index = 0; index < 4; index++)
			{
				long q = number(quantities[index], name);
				try { total = Math.addExact(total, q); } catch (ArithmeticException ex) { throw new IllegalArgumentException("Quantity is too large for " + name); }
				if (index < 3)
				{
					SnapshotLocation location = SnapshotLocation.values()[index];
					if (q > review.getCurrent().at(id, location)) { throw new IllegalArgumentException("Earned quantity exceeds observed " + location.name().toLowerCase(Locale.ROOT) + " for " + name); }
					locations.put(VirtualLocation.valueOf(location.name()), q);
				}
				else if (q > review.getPrevious().total(id)) { throw new IllegalArgumentException("Elsewhere can preserve only previously earned copies."); }
			}
			return new VirtualItemOwnership(total, locations);
		}
	}
}

