		ItemReviewTable table = new ItemReviewTable(review(run, plan), Collections.emptyMap()); assertEquals(1, table.getRowCount());
	}
	@Test public void runDurationUsesSavedStartAndClampsClockRollback()
	{
		assertEquals("1d 2h 03m", RunDuration.format(RunDuration.minutes(TIME, TIME.plusSeconds((26 * 60 + 3) * 60))));
		assertEquals("0h 00m", RunDuration.format(RunDuration.minutes(TIME, TIME.minusSeconds(1))));
	}
	private static ItemReview review(RunRecord run, AccountingPlan plan)
	{
		return new ItemReview(UUID.randomUUID(), run.getItemProgress().getPhysical(), plan.getProgress().getPhysical(), plan.getOwnership(), run.getOwnership(), plan.getExplanation());
	}
	private static List<Component> components(Container parent)
	{
		List<Component> list = new ArrayList<>(); for (Component c : parent.getComponents()) { list.add(c); if (c instanceof Container) { list.addAll(components((Container) c)); } } return list;
	}
	private static List<String> labels(Container panel)
	{
		List<String> labels = new ArrayList<>(); for (Component c : components(panel)) { if (c instanceof JLabel) { labels.add(((JLabel) c).getText()); } } return labels;
	}
	private static JButton button(Container panel, String title)
	{
		return components(panel).stream().filter(c -> c instanceof JButton && title.equals(((JButton) c).getText())).map(c -> (JButton) c).findFirst().get();
	}
}

package com.fromscratch.ui;

import com.fromscratch.model.SnapshotLocation;
import com.fromscratch.observation.CaptureProgress;
import java.util.Arrays;
import java.util.List;

/** The same reliable-observation checklist guides first setup and returning host sessions. */
public final class PreparationChecklist
{
	private PreparationChecklist() { }
	public static List<String> steps(CaptureProgress progress)
	{
		return Arrays.asList(step(progress.ready(SnapshotLocation.INVENTORY), "Open your inventory."),
			step(progress.ready(SnapshotLocation.EQUIPMENT), "Open your worn equipment tab."),
			step(progress.ready(SnapshotLocation.BANK), "Open your bank."));
	}
	public static String step(boolean complete, String text) { return (complete ? "\u2713 " : "\u25cb ") + text; }
	public static String instruction(CaptureProgress progress)
	{
		if (!progress.ready(SnapshotLocation.INVENTORY)) { return "Open your inventory so its contents can be checked. Empty is fine."; }
		if (!progress.ready(SnapshotLocation.EQUIPMENT)) { return "Open your worn equipment tab so its contents can be checked. Empty is fine."; }
		if (!progress.ready(SnapshotLocation.BANK)) { return "Open your normal bank and enter your PIN if needed. Special storage is excluded."; }
		return "Review the detected items and confirm when they are correct.";
	}
}

package com.fromscratch.ui;

import java.util.UUID;

/** UI requests only local plugin operations; implementations never perform player actions. */
public interface SetupActions
{
	SetupActions NONE = new SetupActions()
	{
		public void begin() { }
		public void confirm(UUID reviewToken) { }
		public void cancel() { }
		public void reset(UUID runId) { }
		public void retry() { }
	};

	void begin();
	void confirm(UUID reviewToken);
	void cancel();
	void reset(UUID runId);
	void retry();
	default void reviewItems() { }
	default void confirmItems(UUID token, java.util.Map<Integer, com.fromscratch.model.VirtualItemOwnership> corrections, String reason, boolean permanentlyRemoved) { }
	default void confirmUpdate(UUID token, com.fromscratch.tracking.ItemReviewEdits edits)
	{ confirmItems(token, edits.getOwnership(), edits.getReason(), false); }
	default void cancelUpdate(UUID token) { }
}

package com.fromscratch.ui;

import com.fromscratch.model.LegacySnapshot;
import com.fromscratch.model.RunRecord;
import com.fromscratch.observation.CaptureProgress;
import java.util.UUID;
import java.util.Map;
import java.util.Collections;
import java.util.HashMap;
import lombok.Value;

/** Immutable presentation snapshot; no client objects or mutable session cross onto Swing. */
@Value
public class SetupView
{
	public enum Mode { SIGNED_OUT, LOADING, NOT_STARTED, INITIALIZING, SAVING, ACTIVE, RECONCILING, ERROR }

	Mode mode;
	String message;
	RunRecord saved;
	LegacySnapshot preview;
	UUID reviewToken;
	CaptureProgress progress;
	ItemReview itemReview;
	Map<Integer, String> itemNames;
	long elapsedMinutes;
	boolean writing;

	public SetupView(Mode mode, String message, RunRecord saved, LegacySnapshot preview, UUID reviewToken)
	{
		this(mode, message, saved, preview, reviewToken, CaptureProgress.from(preview));
	}

	public SetupView(Mode mode, String message, RunRecord saved, LegacySnapshot preview, UUID reviewToken, CaptureProgress progress)
	{
		this(mode, message, saved, preview, reviewToken, progress, null, Collections.emptyMap());
	}
	public SetupView(Mode mode, String message, RunRecord saved, LegacySnapshot preview, UUID reviewToken, CaptureProgress progress,
		ItemReview itemReview, Map<Integer, String> itemNames)
	{
		this(mode, message, saved, preview, reviewToken, progress, itemReview, itemNames, false);
	}
	public SetupView(Mode mode, String message, RunRecord saved, LegacySnapshot preview, UUID reviewToken, CaptureProgress progress,
		ItemReview itemReview, Map<Integer, String> itemNames, boolean writing)
	{
		this.mode = mode;
		this.message = message;
		this.saved = saved;
		this.preview = preview;
		this.reviewToken = reviewToken;
		this.progress = progress;
		this.itemReview = itemReview;
		this.itemNames = Collections.unmodifiableMap(new HashMap<>(itemNames));
		this.elapsedMinutes = RunDuration.minutes(saved == null ? null : saved.getState().getStartedAt(), java.time.Instant.now());
		this.writing = writing;
	}

	public static SetupView signedOut()
	{
		return new SetupView(Mode.SIGNED_OUT, "Log in and wait for a verified character identity.", null, null, null);
	}
}

